internal data class ChartChannel(val key:String,val unit:String,val color:Color,val values:List<Double>)
internal fun channels(history:List<LiveDataSnapshot>)=listOf(
    ChartChannel("RPM","rpm",Color(0xFF20B9FF),history.mapNotNull{it.rpm}),
    ChartChannel("Coolant","°C",Color(0xFFFF5D79),history.mapNotNull{it.coolantC}),
    ChartChannel("MAP pressure","kPa",Color(0xFFB67CFF),history.mapNotNull{it.mapKpa}),
    ChartChannel("Speed","km/h",Color(0xFF21D6A0),history.mapNotNull{it.speedKph}),
    ChartChannel("Engine load","%",Color(0xFFFFC663),history.mapNotNull{it.engineLoadPct}),
    ChartChannel("Intake air","°C",Color(0xFF20B9FF),history.mapNotNull{it.intakeAirC}),
    ChartChannel("Throttle","%",Color(0xFFB67CFF),history.mapNotNull{it.throttlePct}),
    ChartChannel("MAF","g/s",Color(0xFF20B9FF),history.mapNotNull{it.mafGps}),
    ChartChannel("STFT","%",Color(0xFF21D6A0),history.mapNotNull{it.shortFuelTrimPct}),
    ChartChannel("LTFT","%",Color(0xFFFFC663),history.mapNotNull{it.longFuelTrimPct})
)

@Composable
private fun ChannelTrace(channel:ChartChannel,modifier:Modifier=Modifier, chartHeight:androidx.compose.ui.unit.Dp=68.dp) {
    val grid=MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha=.16f)
    Canvas(modifier.fillMaxWidth().height(chartHeight)) {
        for(line in 1..3) drawLine(grid,Offset(0f,size.height*line/4),Offset(size.width,size.height*line/4))
        val values=channel.values
        if(values.size>=2){
            val low=values.minOrNull() ?: 0.0
            val high=values.maxOrNull() ?: low
            val padding=maxOf((high-low)*.1,kotlin.math.abs(high)*.01,1.0)
            val min=low-padding
            val span=high-low+2*padding
            val path=Path()
            values.forEachIndexed { index,value ->
                val x=size.width*index/(values.size-1)
                val y=size.height*(.92f-.84f*((value-min)/span).toFloat())
                if(index==0) path.moveTo(x,y) else path.lineTo(x,y)
            }
            drawPath(path,channel.color,style=Stroke(width=2.dp.toPx()))
        }
    }
}

internal fun channelTitle(key: String) = when(key) {
    "RPM" -> "Engine speed"
    "Coolant" -> "Coolant temperature"
    "Speed" -> "Vehicle speed"
    "Throttle" -> "Throttle position"
    "Intake air" -> "Intake air temperature"
    else -> key
}

internal val LocalDashboardUsUnits = staticCompositionLocalOf { false }
internal val LocalDashboardAnalog = staticCompositionLocalOf { true }

internal fun displayChannel(channel: ChartChannel, us: Boolean): ChartChannel {
    val normalized = if (channel.unit == "C") channel.copy(unit="°C") else channel
    return when {
        us && normalized.unit == "km/h" -> normalized.copy(unit="mph", values=normalized.values.map { it/1.609344 })
        us && normalized.unit == "°C" -> normalized.copy(unit="°F", values=normalized.values.map { it*1.8+32 })
        else -> normalized
    }
}

internal fun gaugeRange(unit: String, value: Double?) = when(unit) {
    "rpm" -> 0.0 to 8000.0
    "°C" -> -40.0 to 160.0
    "°F" -> -40.0 to 320.0
    "km/h" -> 0.0 to 260.0
    "mph" -> 0.0 to 160.0
    "%" -> 0.0 to 100.0
    else -> 0.0 to maxOf(100.0, (value ?: 0.0)*1.2)
}

// Presentation bands only: speed colors are not speed limits or RPM redlines.
internal fun gaugeBands(channel: ChartChannel): List<Triple<Double, Double, Color>> {
    val (low, high) = if(channel.key in setOf("STFT","LTFT")) -100.0 to 100.0 else gaugeRange(channel.unit, channel.values.lastOrNull())
    val coolant = channel.key.lowercase() in setOf("coolant", "coolant temperature", "coolant_temp", "0x05", "0105")
    val boundaries = if (coolant && channel.unit in setOf("C", "°C", "°F")) {
        listOf(60.0, 92.0, 102.0, 110.0).map { if (channel.unit == "°F") it*1.8+32 else it }
    } else listOf(.25, .45, .7, .85).map { low+(high-low)*it }
    val edges = listOf(low)+boundaries+listOf(high)
    val colors = listOf(Color(0xFF249BFF), Color(0xFF29CED3), Color(0xFF35CF87), Color(0xFFFFBD45), Color(0xFFFF5367))
    return colors.mapIndexed { index, color -> Triple(edges[index], edges[index+1], color) }
}

@Composable
private fun ChannelGauge(channel: ChartChannel, chartHeight:androidx.compose.ui.unit.Dp=140.dp) {
    val track=MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha=.25f)
    val (low,high)=if(channel.key in setOf("STFT","LTFT")) -100.0 to 100.0 else gaugeRange(channel.unit,channel.values.lastOrNull())
    val bands=gaugeBands(channel)
    val value=channel.values.lastOrNull() ?: low
    val needle=if(value in bands[2].first..bands[2].second) bands[2].third
        else bands.firstOrNull { value < it.second }?.third ?: bands.last().third
    Canvas(Modifier.fillMaxWidth().height(chartHeight).semantics { contentDescription="${channel.key} ${channel.values.lastOrNull() ?: "—"} ${channel.unit}" }) {
        val radius=minOf(size.width/2-10.dp.toPx(),size.height/2-8.dp.toPx())
        val center=Offset(size.width/2,size.height/2)
        drawCircle(Brush.radialGradient(listOf(Color(0xFF244762),Color(0xFF071322))),radius+5.dp.toPx(),center)
        drawCircle(track,radius+4.dp.toPx(),center,style=Stroke(2.dp.toPx()))
        drawArc(track,135f,270f,false,topLeft=center-Offset(radius,radius),size=androidx.compose.ui.geometry.Size(radius*2,radius*2),style=Stroke(8.dp.toPx()))
        bands.forEach { (start,end,color) ->
            drawArc(color,(135+270*(start-low)/(high-low)).toFloat(),(270*(end-start)/(high-low)).toFloat(),false,
                topLeft=center-Offset(radius,radius),size=androidx.compose.ui.geometry.Size(radius*2,radius*2),style=Stroke(8.dp.toPx()))
        }
        for(index in 0..8) {
            val angle=Math.toRadians(135.0+270.0*index/8)
            fun point(r:Float)=center+Offset((r*kotlin.math.cos(angle)).toFloat(),(r*kotlin.math.sin(angle)).toFloat())
            drawLine(track,point(radius-6.dp.toPx()),point(radius-13.dp.toPx()),2.dp.toPx())
        }
        channel.values.lastOrNull()?.let { value ->
            val angle=Math.toRadians(135+270*((value-low)/(high-low)).coerceIn(0.0,1.0))
            drawLine(needle,center,center+Offset(((radius-18.dp.toPx())*kotlin.math.cos(angle)).toFloat(),((radius-18.dp.toPx())*kotlin.math.sin(angle)).toFloat()),3.dp.toPx())
            drawCircle(needle,5.dp.toPx(),center)
        }
    }
    Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween) {
        Text("${low.toInt()}",style=MaterialTheme.typography.labelSmall)
        val coolant=channel.key.lowercase() in setOf("coolant", "coolant temperature", "coolant_temp", "0x05", "0105")
        Text(if(coolant) { if(channel.unit=="°F") "197.6–215.6 °F" else "92–102 °C" } else channel.unit,
            style=MaterialTheme.typography.labelSmall,color=if(coolant) Color(0xFF35CF87) else MaterialTheme.colorScheme.onSurfaceVariant)
        Text("${high.toInt()}",style=MaterialTheme.typography.labelSmall)
    }
}

@Composable
private fun ChannelWidget(channel: ChartChannel) {
    val analog=LocalDashboardAnalog.current
    val context=androidx.compose.ui.platform.LocalContext.current
    val density=androidx.compose.ui.platform.LocalDensity.current
    val prefs=remember {context.getSharedPreferences("widget_sizes",0)}
    var chartHeight by remember(channel.key) {mutableFloatStateOf(prefs.getFloat(channel.key,180f).coerceIn(140f,420f))}
    val resizeLabel=dashboardLabel("Resize widget")
    DemoPanel(dashboardLabel(channelTitle(channel.key))) {
        Text(channel.values.lastOrNull()?.let { "%.1f ${channel.unit}".format(it) } ?: "—",style=MaterialTheme.typography.titleLarge,color=channel.color,fontWeight=FontWeight.Bold)
        if(analog) ChannelGauge(channel,chartHeight.dp) else ChannelTrace(channel,chartHeight=chartHeight.dp)
        Box(Modifier.fillMaxWidth().height(14.dp).pointerInput(channel.key) {
            detectVerticalDragGestures(onDragEnd={prefs.edit().putFloat(channel.key,chartHeight).apply()}) {change,amount ->
                change.consume();chartHeight=(chartHeight+amount/density.density).coerceIn(140f,420f)
            }
        }.semantics {contentDescription=resizeLabel})
    }
}

internal fun backendChannels(records: List<BackendLiveRecordDto>): List<ChartChannel> =
    records.filter { it.numeric_value != null }.groupBy { it.channel ?: it.pid ?: "Unknown channel" }.map { (id,rows) ->
        val last=rows.last()
        val key=last.display_name ?: when(id.uppercase()) {
            "0X0C" -> "RPM"; "0X05" -> "Coolant"; "0X0D" -> "Speed"; "0X11" -> "Throttle"
            else -> id
        }
        ChartChannel(key,last.unit.orEmpty(),Color(0xFF20B9FF),rows.takeLast(90).mapNotNull { it.numeric_value })
    }

