package com.aicarscaner.mobile.presentation

// Backend entries and the bundled shared/vehicle_catalog.json snapshot are the
// only catalog sources. Never maintain a separate Kotlin vehicle seed list.

/** Remote catalog helpers. The backend DB is authoritative; local data is only a fallback. */
fun modelOptionsFor(catalog: List<com.aicarscaner.mobile.data.api.VehicleCatalogEntryDto>, make: String): List<String> =
    catalog.filter { it.make == make }.map { it.model }.distinct().sorted()

fun chassisOptionsFor(catalog: List<com.aicarscaner.mobile.data.api.VehicleCatalogEntryDto>, make: String, model: String): List<String> =
    catalog.filter { it.make == make && it.model == model }.mapNotNull { it.chassis }.distinct().sorted()

fun yearOptionsFor(catalog: List<com.aicarscaner.mobile.data.api.VehicleCatalogEntryDto>, make: String, model: String, chassis: String): List<Int> =
    catalog.filter { it.make == make && it.model == model && it.chassis == chassis }.map { it.year }.distinct().sortedDescending()

fun engineOptionsFor(catalog: List<com.aicarscaner.mobile.data.api.VehicleCatalogEntryDto>, make: String, model: String, chassis: String, year: Int? = null): List<String> =
    catalog.filter {
        it.make == make && it.model == model && it.chassis == chassis &&
            (year == null || it.year == year)
    }.map { it.engine }.distinct().sorted()

fun ecuOptionsFor(catalog: List<com.aicarscaner.mobile.data.api.VehicleCatalogEntryDto>, make: String, model: String, chassis: String, engine: String, year: Int? = null): List<String> =
    catalog.filter {
        it.make == make && it.model == model && it.chassis == chassis &&
            it.engine == engine && (year == null || it.year == year)
    }.mapNotNull { it.ecu }.distinct().sorted()

package com.aicarscaner.mobile.settings

import android.content.Context

enum class AppLanguage(val code: String) {
    EN("en"),
    RU("ru"),
    HY("hy")
}

data class AppSettings(
    val language: AppLanguage = AppLanguage.EN,
    val darkTheme: Boolean = true,
    val usUnits: Boolean = false,
    val analogDisplay: Boolean = true
)

class AppSettingsStore(context: Context) {
    private val prefs = context.getSharedPreferences("ai_car_scaner_settings", Context.MODE_PRIVATE)

    fun load(): AppSettings = AppSettings(
        language = runCatching {
            AppLanguage.valueOf(prefs.getString("language", AppLanguage.EN.name) ?: AppLanguage.EN.name)
        }.getOrDefault(AppLanguage.EN),
        darkTheme = prefs.getBoolean("dark_theme", true),
        usUnits = prefs.getBoolean("us_units", false),
        analogDisplay = prefs.getBoolean("analog_display", true)
    )

    fun save(settings: AppSettings) {
        prefs.edit()
            .putString("language", settings.language.name)
            .putBoolean("dark_theme", settings.darkTheme)
            .putBoolean("us_units", settings.usUnits)
            .putBoolean("analog_display", settings.analogDisplay)
            .apply()
    }
}

package com.aicarscaner.mobile.settings

import android.content.Context

internal fun normalizeLauncherOrder(saved: List<Int>, defaults: List<Int>): List<Int> =
    saved.filter { it in defaults }.distinct() + defaults.filter { it !in saved }

internal fun moveLauncherItem(order: List<Int>, source: Int, target: Int): List<Int> {
    if(source == target || source !in order || target !in order) return order
    val index=order.indexOf(target)
    return order.toMutableList().apply { remove(source);add(index,source) }
}

/** A native presentation preference; it never changes backend workflow identifiers. */
internal class LauncherOrderStore(context: Context, name: String = "ai_car_launcher_layout") {
    private val prefs=context.applicationContext.getSharedPreferences(name,Context.MODE_PRIVATE)
    fun load(defaults: List<Int>): List<Int> {
        val raw=runCatching {prefs.getString("order","")}.getOrNull().orEmpty()
        return normalizeLauncherOrder(raw.split(',').mapNotNull { it.toIntOrNull() },defaults)
    }
    fun save(order: List<Int>) { prefs.edit().putString("order",order.joinToString(",")).apply() }
}

