import Foundation
import Network

/// Byte transport only. The backend owns initialization, PID selection/scaling.
actor NativeObdWifiBridge {
    private var connection: NWConnection?
    private var endpoint: String?
    private var initialized = false
    private var liveSessionID: String?
    private var liveCommands: [String]?
    private var capabilityFrames: [String:String] = [:]
    private var busy = false
    private let queue = DispatchQueue(label: "ai-car-scanner.obd-wifi")

    enum BridgeError: LocalizedError {
        case disconnected, invalidPort, concurrentRead, oversizedResponse, timeout, capabilityUnavailable, noSupportedChannels
        var errorDescription: String? {
            switch self {
            case .disconnected: return "OBD adapter disconnected"
            case .invalidPort: return "Invalid adapter port"
            case .concurrentRead: return "An OBD read is already running"
            case .oversizedResponse: return "OBD response exceeded the transport limit"
            case .timeout: return "OBD adapter timed out"
            case .capabilityUnavailable: return "Backend capability discovery plan is unavailable"
            case .noSupportedChannels: return "Vehicle reports no supported live channels"
            }
        }
        func message(language: AppLanguage) -> String {
            let translated: (String,String)
            switch self {
            case .capabilityUnavailable:
                translated=("Backend-ի աջակցվող PID-երի հայտնաբերման պլանը հասանելի չէ", "План определения поддерживаемых PID недоступен на сервере")
            case .noSupportedChannels:
                translated=("Մեքենան չի հայտնել աջակցվող ընթացիկ տվյալների ալիքներ", "Автомобиль не сообщил о поддерживаемых каналах текущих данных")
            default: return errorDescription ?? "OBD error"
            }
            switch language {
            case .hy: return translated.0
            case .ru: return translated.1
            case .en: return errorDescription ?? "OBD error"
            }
        }

    }

    func disconnect() {
        connection?.cancel()
        connection = nil
        endpoint = nil
        initialized = false
        liveSessionID = nil
        liveCommands = nil
        capabilityFrames = [:]
    }

    func poll(host: String, port: Int, api: DiagnosticAPI, sessionID: String? = nil) async throws -> ObdDecodedSnapshot {
        guard !busy else { throw BridgeError.concurrentRead }
        busy = true
        defer { busy = false }
        try await ensureConnection(host:host,port:port)
        do {
            if liveSessionID != sessionID {
                liveCommands = nil
                capabilityFrames = [:]
                liveSessionID = sessionID
            }
            if liveCommands == nil {
                let bootstrap = try await api.obdPlan()
                if !initialized {
                    for command in bootstrap.initialization { _ = try await exchange(command, timeout: 35) }
                    initialized = true
                }
                guard let discovery=bootstrap.discovery, !discovery.isEmpty else { throw BridgeError.capabilityUnavailable }
                var observed: [String:String] = [:]
                for command in discovery { observed[command] = try await exchange(command, timeout:35) }
                let selected = try await api.supportedObdPlan(observed)
                guard !selected.commands.isEmpty else { throw BridgeError.noSupportedChannels }
                capabilityFrames = observed
                liveCommands = selected.commands
            }
            var responses = capabilityFrames
            for command in liveCommands ?? [] { responses[command] = try await exchange(command) }
            return try await api.decodeObd(responses, sessionID: sessionID)
        } catch {
            disconnect()
            throw error
        }
    }

    private func ensureConnection(host:String, port:Int) async throws {
        let target = "\(host):\(port)"
        if endpoint != target {
            disconnect()
            guard !host.isEmpty, let number = UInt16(exactly: port), number > 0,
                  let nwPort = NWEndpoint.Port(rawValue: number) else { throw BridgeError.invalidPort }
            let socket = NWConnection(host: NWEndpoint.Host(host), port: nwPort, using: .tcp)
            connection = socket
            do {
                try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
                    // State callbacks run on one serial queue. Clearing the handler
                    // before resuming guarantees a single continuation completion.
                    let deadline = DispatchWorkItem { socket.cancel() }
                    socket.stateUpdateHandler = { state in
                        switch state {
                        case .ready:
                            deadline.cancel()
                            socket.stateUpdateHandler = nil
                            continuation.resume()
                        case .failed(let error), .waiting(let error):
                            deadline.cancel()
                            socket.stateUpdateHandler = nil
                            socket.cancel()
                            continuation.resume(throwing: error)
                        case .cancelled:
                            deadline.cancel()
                            socket.stateUpdateHandler = nil
                            continuation.resume(throwing: BridgeError.disconnected)
                        default: break
                        }
                    }
                    socket.start(queue: queue)
                    queue.asyncAfter(deadline: .now()+10, execute: deadline)
                }
                endpoint = target
            } catch { disconnect(); throw error }
        }
    }

    func identify(host:String, port:Int, api:DiagnosticAPI) async throws -> DiscoveryResult {
        guard !busy else { throw BridgeError.concurrentRead }
        busy=true
        defer { busy=false; initialized=false; liveCommands=nil; capabilityFrames=[:] }
        try await ensureConnection(host:host,port:port)
        let bootstrap=try await api.obdPlan()
        for command in bootstrap.initialization { _ = try await exchange(command,timeout:35) }
        let plan=try await api.discoveryPlan()
        var responses:[String:String]=[:]
        do {
            for command in plan.commands { responses[command]=try await exchange(command,timeout:35) }
        } catch {
            for command in plan.restore { _ = try? await exchange(command) }
            disconnect()
            throw error
        }
        for command in plan.restore { _ = try await exchange(command) }
        return try await api.decodeDiscovery(responses)
    }

    private func exchange(_ command: String, timeout: TimeInterval = 3) async throws -> String {
        try Task.checkCancellation()
        guard let socket = connection else { throw BridgeError.disconnected }
        // Cancellation closes the receive operation rather than leaving an
        // outstanding continuation or reusing a partially consumed response.
        return try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<String, Error>) in
                let deadline = DispatchWorkItem { socket.cancel() }
                queue.asyncAfter(deadline: .now()+timeout, execute: deadline)
                socket.send(content: Data((command+"\r").utf8), completion: .contentProcessed { error in
                    if let error { deadline.cancel(); continuation.resume(throwing: error); return }
                    self.queue.async {
                        self.receivePrompt(socket, accumulated: Data(), deadline: deadline, continuation: continuation)
                    }
                })
            }
        } onCancel: { socket.cancel() }
    }

    nonisolated private func receivePrompt(_ socket: NWConnection, accumulated: Data, deadline: DispatchWorkItem,
                                           continuation: CheckedContinuation<String, Error>) {
        socket.receive(minimumIncompleteLength: 1, maximumLength: 8192) { data, _, complete, error in
            if let error { deadline.cancel(); continuation.resume(throwing: error); return }
            var result = accumulated
            if let data { result.append(data) }
            if result.count > 16384 { deadline.cancel(); socket.cancel(); continuation.resume(throwing: BridgeError.oversizedResponse); return }
            if let end = result.firstIndex(of: 62) { // ELM '>' transport prompt.
                deadline.cancel()
                continuation.resume(returning: String(decoding: result[..<end], as: UTF8.self)); return
            }
            if complete { deadline.cancel(); continuation.resume(throwing: BridgeError.disconnected); return }
            self.receivePrompt(socket, accumulated: result, deadline: deadline, continuation: continuation)
        }
    }
}

import Foundation
import CoreBluetooth
import Combine

/// BLE byte transport for known UART profiles. All OBD commands/decoding come from Backend.
@MainActor
final class OBDService: NSObject, ObservableObject, CBCentralManagerDelegate, CBPeripheralDelegate {
    @Published var status = "Not connected"
    @Published var devices: [CBPeripheral] = []
    @Published var connected = false
    private var central:CBCentralManager!
    private var peripheral:CBPeripheral?
    private var writer:CBCharacteristic?
    private var reader:CBCharacteristic?
    private var connectionWait:CheckedContinuation<Void,Error>?
    private var responseWait:CheckedContinuation<String,Error>?
    private var deadline:Task<Void,Never>?
    private var buffer=Data()
    private var initialized=false
    private var sessionID:String?
    private var liveCommands:[String]?
    private var capabilities:[String:String]=[:]
    private var busy=false
    // service : (write, notify), not inferred from a peripheral name.
    private let profiles:[String:(String,String)] = [
        "FFE0":("FFE1","FFE1"), "FFF0":("FFF2","FFF1"),
        "6E400001-B5A3-F393-E0A9-E50E24DCCA9E":("6E400002-B5A3-F393-E0A9-E50E24DCCA9E","6E400003-B5A3-F393-E0A9-E50E24DCCA9E")
    ]
    enum TransportError:LocalizedError {
        case unavailable, unsupported, timeout, disconnected, concurrent, oversized
        var errorDescription:String? {
            switch self {
            case .unavailable:return "Bluetooth unavailable"
            case .unsupported:return "Unsupported BLE UART profile"
            case .timeout:return "BLE adapter timed out"
            case .disconnected:return "BLE adapter disconnected"
            case .concurrent:return "An OBD read is already running"
            case .oversized:return "OBD response exceeded the transport limit"
            }
        }
    }
    override init() {super.init();central=CBCentralManager(delegate:self,queue:.main)}
    func centralManagerDidUpdateState(_ central:CBCentralManager) {
        status=central.state == .poweredOn ? "Bluetooth ready" : "Bluetooth unavailable"
        if central.state != .poweredOn {fail(TransportError.unavailable)}
    }
    func scan() {
        guard central.state == .poweredOn else {return}
        devices=[];status="Scanning…";central.scanForPeripherals(withServices:nil)
        Task {try? await Task.sleep(nanoseconds:5_000_000_000);central.stopScan();if !connected {status=devices.isEmpty ? "No BLE adapter found" : "Select BLE adapter"}}
    }
    func centralManager(_ central:CBCentralManager,didDiscover peripheral:CBPeripheral,advertisementData:[String:Any],rssi RSSI:NSNumber) {
        if !devices.contains(where:{$0.identifier==peripheral.identifier}) {devices.append(peripheral)}
    }
    func connect(_ target:CBPeripheral) async throws {
        if connected && peripheral === target {return}
        guard connectionWait==nil else {throw TransportError.concurrent}
        guard target.state != .disconnecting else {throw TransportError.disconnected}
        disconnect();central.stopScan()
        guard central.state == .poweredOn else {throw TransportError.unavailable}
        peripheral=target;target.delegate=self;status="Connecting…"
        try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { (wait:CheckedContinuation<Void,Error>) in
                connectionWait=wait;armTimeout(seconds:15);central.connect(target)
            }
        } onCancel:{Task { @MainActor in self.disconnect() }}
    }
    func centralManager(_ central:CBCentralManager,didConnect peripheral:CBPeripheral) {
        guard self.peripheral===peripheral else {return}
        peripheral.discoverServices(profiles.keys.map {CBUUID(string:$0)})
    }
    func centralManager(_ central:CBCentralManager,didFailToConnect peripheral:CBPeripheral,error:Error?) {if self.peripheral===peripheral {fail(error ?? TransportError.disconnected)}}
    func centralManager(_ central:CBCentralManager,didDisconnectPeripheral peripheral:CBPeripheral,error:Error?) {if self.peripheral===peripheral {fail(error ?? TransportError.disconnected)}}
    func peripheral(_ peripheral:CBPeripheral,didDiscoverServices error:Error?) {
        guard self.peripheral===peripheral else {return}
        if let error {fail(error);return}
        guard let service=peripheral.services?.first(where:{profiles[$0.uuid.uuidString] != nil}) else {fail(TransportError.unsupported);return}
        peripheral.discoverCharacteristics(nil,for:service)
    }
    func peripheral(_ peripheral:CBPeripheral,didDiscoverCharacteristicsFor service:CBService,error:Error?) {
        guard self.peripheral===peripheral else {return}
        if let error {fail(error);return}
        guard let profile=profiles[service.uuid.uuidString],
              let write=service.characteristics?.first(where:{$0.uuid==CBUUID(string:profile.0) && (!$0.properties.intersection([.write,.writeWithoutResponse]).isEmpty)}),
              let read=service.characteristics?.first(where:{$0.uuid==CBUUID(string:profile.1) && (!$0.properties.intersection([.notify,.indicate]).isEmpty)}) else {fail(TransportError.unsupported);return}
        writer=write;reader=read;peripheral.setNotifyValue(true,for:read)
    }
    func peripheral(_ peripheral:CBPeripheral,didUpdateNotificationStateFor characteristic:CBCharacteristic,error:Error?) {
        guard self.peripheral===peripheral,characteristic===reader else {return}
        if let error {fail(error);return}
        guard characteristic.isNotifying else {fail(TransportError.unsupported);return}
        deadline?.cancel();connected=true;status="Connected";let wait=connectionWait;connectionWait=nil;wait?.resume()
    }
    func peripheral(_ peripheral:CBPeripheral,didWriteValueFor characteristic:CBCharacteristic,error:Error?) {
        if self.peripheral===peripheral,let error {fail(error)}
    }
    func peripheral(_ peripheral:CBPeripheral,didUpdateValueFor characteristic:CBCharacteristic,error:Error?) {
        guard self.peripheral===peripheral,characteristic===reader,responseWait != nil else {return}
        if let error {fail(error);return}
        if let value=characteristic.value {buffer.append(value)}
        if buffer.count>16384 {fail(TransportError.oversized);return}
        if let end=buffer.firstIndex(of:62) {
            deadline?.cancel();let value=String(decoding:buffer[..<end],as:UTF8.self)
            let wait=responseWait;responseWait=nil;buffer=Data();wait?.resume(returning:value)
        }
    }
    private func armTimeout(seconds:UInt64) {
        deadline?.cancel();deadline=Task {do {try await Task.sleep(nanoseconds:seconds*1_000_000_000)} catch {return};fail(TransportError.timeout)}
    }
    private func fail(_ error:Error) {
        deadline?.cancel();let old=peripheral;peripheral=nil;writer=nil;reader=nil;connected=false;initialized=false;liveCommands=nil;capabilities=[:]
        if let old {central.cancelPeripheralConnection(old)}
        let connect=connectionWait;connectionWait=nil;let response=responseWait;responseWait=nil
        connect?.resume(throwing:error);response?.resume(throwing:error);status=error.localizedDescription
    }
    func disconnect() {central?.stopScan();fail(TransportError.disconnected);status="Not connected"}
    private func command(_ command:String) async throws -> String {
        guard let peripheral,let writer,connected else {throw TransportError.disconnected}
        guard responseWait==nil else {throw TransportError.concurrent}
        let data=Data((command+"\r").utf8)
        let type:CBCharacteristicWriteType=writer.properties.contains(.write) ? .withResponse : .withoutResponse
        guard data.count<=peripheral.maximumWriteValueLength(for:type) else {throw TransportError.oversized}
        return try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { (wait:CheckedContinuation<String,Error>) in
                buffer=Data();responseWait=wait;armTimeout(seconds:35)
                peripheral.writeValue(data,for:writer,type:type)
            }
        } onCancel:{Task { @MainActor in self.disconnect() }}
    }
    func read(api:DiagnosticAPI,session:String?) async throws -> ObdDecodedSnapshot {
        guard !busy else {throw TransportError.concurrent};busy=true;defer {busy=false}
        do {
            if sessionID != session {sessionID=session;liveCommands=nil;capabilities=[:]}
            if liveCommands==nil {
                let plan=try await api.obdPlan()
                if !initialized {for step in plan.initialization {_ = try await command(step)};initialized=true}
                guard let steps=plan.discovery,!steps.isEmpty else {throw TransportError.unsupported}
                for step in steps {capabilities[step]=try await command(step)}
                let supported=try await api.supportedObdPlan(capabilities)
                guard !supported.commands.isEmpty else {throw TransportError.unsupported};liveCommands=supported.commands
            }
            var responses=capabilities
            for step in liveCommands ?? [] {responses[step]=try await command(step)}
            return try await api.decodeObd(responses,sessionID:session)
        } catch {fail(error);throw error}
    }
    func identify(api:DiagnosticAPI) async throws -> DiscoveryResult {
        guard !busy else {throw TransportError.concurrent};busy=true
        defer {busy=false;initialized=false;liveCommands=nil;capabilities=[:]}
        let boot=try await api.obdPlan();for step in boot.initialization {_ = try await command(step)}
        let plan=try await api.discoveryPlan();var responses:[String:String]=[:]
        do {for step in plan.commands {responses[step]=try await command(step)}}
        catch {for step in plan.restore {_ = try? await command(step)};throw error}
        for step in plan.restore {_ = try await command(step)}
        return try await api.decodeDiscovery(responses)
    }
}

import Foundation

/// Reads the byte-identical shared catalog snapshot bundled with Android and Desktop.
enum SharedVehicleCatalog {
    static func offline(bundle: Bundle = .main) -> [VehicleCatalogEntry] {
        guard let url = bundle.url(forResource: "vehicle_catalog", withExtension: "json", subdirectory: "VehicleCatalog"),
              let data = try? Data(contentsOf: url),
              let root = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let rows = root["vehicles"] as? [[String: Any]] else { return [] }
        return rows.compactMap { row in
            guard let make = row["make"] as? String, let model = row["model"] as? String,
                  let year = row["year"] as? Int, let engine = row["engine"] as? String else { return nil }
            let fuel = (row["fuel"] as? String ?? "").lowercased()
                .components(separatedBy: CharacterSet(charactersIn: "+/,"))
                .map { $0.trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty }
            return VehicleCatalogEntry(make: make, model: model, chassis: row["chassis"] as? String,
                year: year, engine: engine, ecu: row["ecu"] as? String, fuel: fuel,
                source: "shared-offline-snapshot", scope: "offline-reference-not-vin-fitment")
        }
    }

    static func merge(server: [VehicleCatalogEntry], offline: [VehicleCatalogEntry]) -> [VehicleCatalogEntry] {
        var seen = Set<String>()
        return (server + offline).filter { item in
            let key = [item.make, item.model, item.chassis ?? "", String(item.year), item.engine, item.ecu ?? ""].joined(separator: "|")
            return seen.insert(key).inserted
        }
    }
}

import SwiftUI
import UIKit

/// Generated illustrations, matched to the exact catalog model and chassis.
struct VehicleModelArtwork: View {
    let make: String
    let model: String
    let chassis: String
    var backendURL: String? = nil
    var photoAttribution: [String: String]? = nil

    private func piece(_ text: String) -> String {
        text.lowercased()
            .replacingOccurrences(of: "[^a-z0-9]+", with: "-", options: .regularExpression)
            .trimmingCharacters(in: CharacterSet(charactersIn: "-"))
    }

    private var portrait: UIImage? {
        let name = [make, model, chassis].map(piece).joined(separator: "_")
        guard let url = Bundle.main.url(forResource: name, withExtension: "png",
                                        subdirectory: "VehicleModels"),
              let data = try? Data(contentsOf: url) else { return nil }
        return UIImage(data: data)
    }

    private var remoteURL: URL? {
        guard let backendURL, var url = URLComponents(string: backendURL) else { return nil }
        url.path = url.path.trimmingCharacters(in: CharacterSet(charactersIn: "/")) + "/api/v1/vehicle-reference/image"
        if !url.path.hasPrefix("/") { url.path = "/" + url.path }
        url.queryItems = [URLQueryItem(name: "make", value: make), URLQueryItem(name: "model", value: model), URLQueryItem(name: "chassis", value: chassis)]
        return url.url
    }

    var body: some View {
        Group {
        if let remoteURL {
            AsyncImage(url: remoteURL) { phase in
                if let image = phase.image {
                    VStack {
                        image.resizable().scaledToFit().frame(maxWidth: .infinity).frame(height: 170)
                        if let credit = photoAttribution, let source = credit["source_page"], let url = URL(string: source) {
                            Link([credit["creator"], credit["license"]].compactMap { $0 }.joined(separator: " • "), destination: url).font(.caption)
                        }
                    }
                }
                else { bundledArtwork }
            }.id(remoteURL)
        } else { bundledArtwork }
        }
        .padding(7)
        .background(
            RoundedRectangle(cornerRadius: 16, style: .continuous)
                .fill(LinearGradient(colors: [AutomotivePalette.navy,AutomotivePalette.panel,AutomotivePalette.midnight],
                                     startPoint: .topLeading,endPoint: .bottomTrailing))
        )
        .overlay(
            RoundedRectangle(cornerRadius: 16, style: .continuous)
                .stroke(AutomotivePalette.cyan.opacity(0.9), lineWidth: 1.5)
        )
        .shadow(color: AutomotivePalette.electricBlue.opacity(0.3),radius: 11,y: 3)
    }

    private var bundledArtwork: some View {
        Group {
            if let portrait {
                Image(uiImage: portrait)
                    .resizable()
                    .scaledToFit()
            } else {
                Image(systemName: "car.side.fill")
                    .resizable()
                    .scaledToFit()
                    .foregroundStyle(AutomotivePalette.electricBlue)
                    .padding(35)
            }
        }
        .frame(maxWidth: .infinity)
        .frame(height: 165)
        .accessibilityLabel("\(make) \(model) \(chassis) illustration")
    }
}

import Foundation
import XCTest
@testable import AICarScanner

final class AICarScannerTests: XCTestCase {
    override func tearDown() {
        MockURLProtocol.handler = nil
        MockURLProtocol.lastRequest = nil
        super.tearDown()
    }

    func testHypothesisDiagramUsesOnlyValidServerScores() {
        func score(_ status: String) -> Double? {
            Hypothesis(id: "h1", category: "ignition", statement: "Check ignition",
                       supporting_evidence_ids: [], contradicting_evidence_ids: [], status: status).evidenceScore
        }
        XCTAssertEqual(score("possible:0.65"), 0.65)
        XCTAssertEqual(score("supported_by_test:1"), 1)
        XCTAssertEqual(score("rejected:0"), 0)
        for status in ["possible", "possible:", "possible:NaN", "possible:inf", "possible:-0.1", "possible:1.1", "possible:0.5:0.7"] {
            XCTAssertNil(score(status), status)
        }
    }

    func testOutcomeLabelsFollowTheSelectedLanguage() {
        let hy = T(language: .hy)
        let ru = T(language: .ru)
        XCTAssertEqual(hy.testResultLabel("PASS"), "Նորմալ")
        XCTAssertEqual(hy.testResultLabel("FAIL"), "Խնդիր կա")
        XCTAssertEqual(hy.testResultLabel("INCOMPLETE"), "Անավարտ")
        XCTAssertEqual(ru.testResultLabel("PASS"), "Норма")
        XCTAssertEqual(ru.testResultLabel("FAIL"), "Есть проблема")
        XCTAssertEqual(ru.testResultLabel("INCOMPLETE"), "Не завершён")
        XCTAssertEqual(T(language: .en).testResultLabel("PASS"), "PASS")
        XCTAssertEqual(hy.testResultLabel("future", fallback: "server label"), "server label")
    }

    func testUserReportHidesSessionIDWithoutChangingTheInternalSession() throws {
        let session = try JSONDecoder().decode(DiagnosticSession.self, from: Self.sessionJSON)
        let report = session.userReportJSON
        let object = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(report.utf8)) as? [String: Any])
        XCTAssertNil(object["session_id"])
        XCTAssertFalse(report.contains(session.session_id))
        XCTAssertNotNil(object["dtcs"])
        XCTAssertEqual(session.session_id, try JSONDecoder().decode(DiagnosticSession.self, from: Self.sessionJSON).session_id)
    }

    func testVehicleRoundTrip() throws {
        let value = Vehicle(make: "Mercedes-Benz", model: "E-Class", chassis: "W211", year: 2006, engine: "M272 E35 3.5", fuel: ["petrol", "lpg"], ecu: "ME9.7")
        let data = try JSONEncoder().encode(value)
        let decoded = try JSONDecoder().decode(Vehicle.self, from: data)
        XCTAssertEqual(decoded.make, "Mercedes-Benz")
        XCTAssertEqual(decoded.year, 2006)
        XCTAssertEqual(decoded.fuel, ["petrol", "lpg"])
    }

    func testVehicleCatalogIdentityIncludesVehicleVariant() {
        let entry = VehicleCatalogEntry(
            make: "Mercedes-Benz", model: "E-Class", chassis: "W211", year: 2006,
            engine: "M272", ecu: "ME9.7", fuel: ["petrol", "lpg"], source: "fixture", scope: "exact"
        )
        XCTAssertEqual(entry.id, "Mercedes-Benz|E-Class|W211|2006|M272")
    }

    func testAppLanguageCasesAreStableAndIdentifiable() {
        XCTAssertEqual(AppLanguage.allCases.map(\.rawValue), ["en", "ru", "hy"])
        XCTAssertEqual(AppLanguage.allCases.map(\.id), ["en", "ru", "hy"])
        XCTAssertEqual(AppLanguage.en.label, "EN")
        XCTAssertEqual(AppLanguage.ru.label, "RU")
        XCTAssertEqual(AppLanguage.hy.label, "ARM")
    }

    func testDiagnosticModelsDecodeOptionalAndNestedFields() throws {
        let json = Data("""
        {
          "session_id":"s-2","state":"ANALYSIS_READY",
          "vehicle":{"make":"Kia","model":"Forte","chassis":null,"year":2017,"engine":"2.0","fuel":["petrol"],"ecu":null},
          "symptoms":[{"id":"sym-1","raw_text":"Hard cold start","normalized":{"condition":"cold"}}],
          "dtcs":[{"id":null,"code":"P0302","description":null,"source":"manual"}],
          "evidence":[{"id":"e-1","fact":"Only cold","source":"driver","status":"reported","confidence":0.8}],
          "hypotheses":[{"id":"h-1","category":"fuel","statement":"Check pressure","supporting_evidence_ids":["e-1"],"contradicting_evidence_ids":[],"status":"possible"}],
          "recommendations":[{"id":"t-1","name":"Fuel pressure","purpose":"Check it","priority_score":0.7,"expected_observation":"Stable","expected_information_gain":0.6,"estimated_cost":0.0,"risk_level":"LOW","prerequisites":[],"target_hypotheses":["h-1"],"safety_notes":[]}],
          "test_results":[{"test_id":"t-1","result":"PASS","measurements":{"bar":"3.5"},"notes":null,"test_name":"Fuel pressure"}],
          "audit_log":[{"event":"analysis","hypotheses":1,"evidence_count":1,"hypothesis_count":1,"questions":["Check pressure"]}]
        }
        """.utf8)
        let session = try JSONDecoder().decode(DiagnosticSession.self, from: json)
        XCTAssertEqual(session.session_id, "s-2")
        XCTAssertNil(session.vehicle?.chassis)
        XCTAssertEqual(session.symptoms.first?.normalized["condition"], "cold")
