from __future__ import annotations

import hashlib
import math
import os
import re
from typing import Any

from ai.interfaces import EmbeddingProvider


class HashEmbeddingProvider(EmbeddingProvider):
    """Offline deterministic embedding fallback.

    Python's built-in hash() is intentionally randomized between processes, so
    this implementation uses SHA-256 buckets to keep embeddings reproducible.
    """

    def __init__(self, dimensions: int = 256):
        if dimensions < 8:
            raise ValueError("dimensions must be >= 8")
        self.dimensions = dimensions

    async def embed(self, texts: list[str]) -> list[list[float]]:
        vectors: list[list[float]] = []
        for text in texts:
            vec = [0.0] * self.dimensions
            tokens = re.findall(r"[a-zA-Z0-9_]+", text.lower())
            for token in tokens:
                digest = hashlib.sha256(token.encode("utf-8")).digest()
                idx = int.from_bytes(digest[:8], "big") % self.dimensions
                vec[idx] += 1.0
            norm = math.sqrt(sum(v * v for v in vec)) or 1.0
            vectors.append([v / norm for v in vec])
        return vectors


class SentenceTransformerEmbeddingProvider(EmbeddingProvider):
    """Local sentence-transformers embedding provider.

    The dependency and model are loaded lazily so the base project stays
    installable without ML packages or model downloads.
    """

    def __init__(self, model_name: str | None = None, device: str | None = None, normalize: bool = True):
        self.model_name = model_name or os.getenv("RAG_EMBEDDING_MODEL", "sentence-transformers/all-MiniLM-L6-v2")
        self.device = device or os.getenv("RAG_EMBEDDING_DEVICE", "cpu")
        self.normalize = normalize
        self._model: Any | None = None

    def _load(self) -> Any:
        if self._model is None:
            try:
                from sentence_transformers import SentenceTransformer
            except ImportError as exc:
                raise RuntimeError(
                    "sentence-transformers is not installed. Install backend/requirements-ai.txt "
                    "or use RAG_EMBEDDING_PROVIDER=hash."
                ) from exc
            self._model = SentenceTransformer(self.model_name, device=self.device)
        return self._model

    @property
    def dimensions(self) -> int:
        model = self._load()
        return int(model.get_sentence_embedding_dimension())

    async def embed(self, texts: list[str]) -> list[list[float]]:
        model = self._load()
        encoded = model.encode(
            texts,
            normalize_embeddings=self.normalize,
            convert_to_numpy=True,
            show_progress_bar=False,
        )
        return encoded.tolist()


class FastEmbedEmbeddingProvider(EmbeddingProvider):
    """Optional ONNX/CPU embedding provider via fastembed."""

    def __init__(self, model_name: str | None = None):
        self.model_name = model_name or os.getenv("RAG_FASTEMBED_MODEL", "BAAI/bge-small-en-v1.5")
        self._model: Any | None = None

    def _load(self) -> Any:
        if self._model is None:
            try:
                from fastembed import TextEmbedding
            except ImportError as exc:
                raise RuntimeError(
                    "fastembed is not installed. Install backend/requirements-ai.txt "
                    "or use another embedding provider."
                ) from exc
            self._model = TextEmbedding(model_name=self.model_name)
        return self._model

    async def embed(self, texts: list[str]) -> list[list[float]]:
        model = self._load()
        return [vector.tolist() if hasattr(vector, "tolist") else list(vector) for vector in model.embed(texts)]


def create_embedding_provider(provider: str | None = None, dimensions: int = 256) -> EmbeddingProvider:
    name = (provider or os.getenv("RAG_EMBEDDING_PROVIDER", "hash")).lower()
    if name == "hash":
        return HashEmbeddingProvider(dimensions)
    if name in {"sentence_transformers", "sentence-transformers", "st"}:
        return SentenceTransformerEmbeddingProvider()
    if name == "fastembed":
        return FastEmbedEmbeddingProvider()
    raise ValueError(f"unsupported embedding provider: {name}")

from __future__ import annotations

import re
from dataclasses import dataclass
from pathlib import Path

import yaml


def _normalize_claim_text(value: str) -> str:
    """Normalize token-like and natural-language claims for robust matching."""
    return re.sub(r"\s+", " ", re.sub(r"[\W_]+", " ", value.casefold())).strip()

@dataclass(frozen=True)
class GoldenCase:
    case_id: str
    expected_categories: set[str]
    forbidden_claims: set[str]

    @classmethod
    def load(cls, path: str | Path) -> "GoldenCase":
        raw = yaml.safe_load(Path(path).read_text(encoding="utf-8"))
        return cls(
            raw["case_id"],
            set(raw.get("expected_categories", [])),
            set(raw.get("forbidden_claims", [])),
        )


@dataclass(frozen=True)
class GoldenResult:
    category_coverage: float
    forbidden_claims_present: list[str]
    passed: bool


class GoldenCaseEvaluator:
    def evaluate(self, categories: set[str], generated_text: str, case: GoldenCase) -> GoldenResult:
        coverage = len(categories & case.expected_categories) / max(1, len(case.expected_categories))
        normalized_text = f" {_normalize_claim_text(generated_text)} "
        forbidden: list[str] = []
        for claim in case.forbidden_claims:
            normalized_claim = _normalize_claim_text(claim)
            if normalized_claim and f" {normalized_claim} " in normalized_text:
                forbidden.append(claim)
        return GoldenResult(coverage, forbidden, coverage >= 0.5 and not forbidden)

from __future__ import annotations
from dataclasses import dataclass
import json
from pathlib import Path
import re
from typing import Iterable

from .models import IngestionResult

@dataclass(frozen=True)
class RetrievalExample:
    query: str
    relevant_chunk_ids: tuple[str, ...]
    metadata_filters: dict
    source_case: str

class RetrievalDatasetBuilder:
    """Builds a simple, human-reviewable retrieval regression dataset from ingested chunks."""
    def from_results(self, results: Iterable[IngestionResult]) -> list[RetrievalExample]:
        out: list[RetrievalExample] = []
        for result in results:
            dtc_codes = set(re.findall(r"\bP\d{4}\b", " ".join(c.content for c in result.chunks), re.I))
            for code in sorted(dtc_codes):
                relevant = tuple(c.chunk_id for c in result.chunks if code.lower() in c.content.lower())
                if relevant:
                    filters = {k: v for k, v in result.document.metadata.to_dict().items() if k in {"manufacturer", "model", "year", "engine", "ecu"} and v is not None}
                    out.append(RetrievalExample(code, relevant, filters, result.document.document_id))
        return out

    @staticmethod
    def save(examples: Iterable[RetrievalExample], path: str | Path) -> None:
        payload = [e.__dict__ | {"relevant_chunk_ids": list(e.relevant_chunk_ids)} for e in examples]
        Path(path).write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")

from __future__ import annotations
from html.parser import HTMLParser
import json
from pathlib import Path
import re
from typing import Protocol

from .models import ParsedDocument, ParsedPage

class SupportsParser(Protocol):
    extensions: tuple[str, ...]
    content_type: str
    def parse(self, path: Path) -> ParsedDocument: ...

class TextParser:
    extensions = (".txt", ".md", ".markdown", ".rst", ".csv", ".log")
    content_type = "text/plain"
    def parse(self, path: Path) -> ParsedDocument:
        text = path.read_text(encoding="utf-8", errors="replace")
        pages = tuple(ParsedPage(i + 1, part) for i, part in enumerate(re.split(r"\f", text)))
        return ParsedDocument(str(path), text, pages, self.content_type)

class JsonParser:
    extensions = (".json",)
    content_type = "application/json"
    def parse(self, path: Path) -> ParsedDocument:
        obj = json.loads(path.read_text(encoding="utf-8"))
        text = json.dumps(obj, ensure_ascii=False, indent=2)
        return ParsedDocument(str(path), text, (ParsedPage(1, text),), self.content_type)

class YamlParser:
    extensions = (".yaml", ".yml")
    content_type = "application/yaml"
    def parse(self, path: Path) -> ParsedDocument:
        try:
            import yaml
            obj = yaml.safe_load(path.read_text(encoding="utf-8"))
            text = yaml.safe_dump(obj, allow_unicode=True, sort_keys=False)
        except ImportError:
            text = path.read_text(encoding="utf-8", errors="replace")
        return ParsedDocument(str(path), text, (ParsedPage(1, text),), self.content_type)

class _HTMLTextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []
    def handle_data(self, data: str) -> None:
        if data.strip():
            self.parts.append(data.strip())
    def text(self) -> str:
        return "\n".join(self.parts)

class HtmlParser:
    extensions = (".html", ".htm")
    content_type = "text/html"
    def parse(self, path: Path) -> ParsedDocument:
        parser = _HTMLTextExtractor()
        parser.feed(path.read_text(encoding="utf-8", errors="replace"))
        text = parser.text()
        return ParsedDocument(str(path), text, (ParsedPage(1, text),), self.content_type)

class PdfParser:
    extensions = (".pdf",)
    content_type = "application/pdf"
    def parse(self, path: Path) -> ParsedDocument:
        try:
            from pypdf import PdfReader
        except ImportError as exc:
            raise RuntimeError("PDF ingestion requires pypdf") from exc
        reader = PdfReader(str(path))
        pages: list[ParsedPage] = []
        text_parts: list[str] = []
        for idx, page in enumerate(reader.pages, start=1):
            text = (page.extract_text() or "").strip()
            pages.append(ParsedPage(idx, text))
            text_parts.append(text)
        return ParsedDocument(str(path), "\n\n".join(text_parts), tuple(pages), self.content_type)

class DocumentParserRegistry:
    def __init__(self, parsers: list[SupportsParser] | None = None) -> None:
        self.parsers = parsers or [TextParser(), JsonParser(), YamlParser(), HtmlParser(), PdfParser()]
        self._by_ext = {ext: parser for parser in self.parsers for ext in parser.extensions}

    def get(self, path: Path) -> SupportsParser:
        try:
            return self._by_ext[path.suffix.lower()]
        except KeyError as exc:
            raise ValueError(f"Unsupported document type: {path.suffix or '<none>'}") from exc

    def parse(self, path: str | Path) -> ParsedDocument:
        p = Path(path)
        if not p.is_file():
            raise FileNotFoundError(p)
        return self.get(p).parse(p)

