from __future__ import annotations

import asyncio
import json
import os
from dataclasses import dataclass
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen
from typing import Any

from ai.interfaces import LLMProvider, LLMResponse


@dataclass(frozen=True)
class LlamaServerConfig:
    base_url: str = "http://127.0.0.1:8000"
    model: str = "Qwen3-8B-Q4_K_M.gguf"
    timeout_s: float = 300.0
    temperature: float = 0.1
    max_tokens: int = 700
    api_key: str | None = None
    configured_context: int = 8192
    context_safety_margin: int = 128

    @classmethod
    def from_env(cls) -> "LlamaServerConfig":
        return cls(
            base_url=os.getenv(
                "LOCAL_LLM_SERVER_URL",
                os.getenv("LLM_BASE_URL", "http://127.0.0.1:8000"),
            ).rstrip("/").removesuffix("/v1"),
            model=os.getenv(
                "LOCAL_LLM_SERVER_MODEL",
                os.getenv("LLM_MODEL", "Qwen3-8B-Q4_K_M.gguf"),
            ),
            timeout_s=max(10.0, float(os.getenv("LOCAL_LLM_SERVER_TIMEOUT_S", "300"))),
            temperature=max(
                0.0,
                min(2.0, float(os.getenv("LOCAL_LLM_TEMPERATURE", "0.1"))),
            ),
            max_tokens=max(64, int(os.getenv("LOCAL_LLM_MAX_TOKENS", "700"))),
            api_key=os.getenv("LOCAL_LLM_SERVER_API_KEY") or os.getenv("LLM_API_KEY"),
            configured_context=max(1024, int(os.getenv("LOCAL_LLM_SERVER_CONTEXT", "8192"))),
            context_safety_margin=max(64, int(os.getenv("LOCAL_LLM_CONTEXT_SAFETY_MARGIN", "128"))),
        )


class LlamaServerLLMProvider(LLMProvider):
    """OpenAI-compatible adapter for a standalone llama-server.exe process."""

    def __init__(self, config: LlamaServerConfig | None = None) -> None:
        self.config = config or LlamaServerConfig.from_env()

    def _headers(self) -> dict[str, str]:
        headers = {"Content-Type": "application/json"}
        if self.config.api_key:
            headers["Authorization"] = f"Bearer {self.config.api_key}"
        return headers

    def _get_json(self, path: str, timeout_s: float = 5.0) -> dict[str, Any]:
        req = Request(
            f"{self.config.base_url}{path}",
            headers=self._headers(),
            method="GET",
        )
        try:
            with urlopen(req, timeout=timeout_s) as response:
                payload = json.loads(response.read().decode("utf-8"))
        except HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")
            raise RuntimeError(
                f"llama-server {path} HTTP {exc.code}: {detail}"
            ) from exc
        except (URLError, TimeoutError, json.JSONDecodeError, OSError) as exc:
            raise RuntimeError(
                f"llama-server unavailable at {self.config.base_url}: {exc}"
            ) from exc

        if isinstance(payload, dict):
            return payload
        return {"data": payload}

    def _server_models(self) -> list[str]:
        payload = self._get_json("/v1/models")
        data = payload.get("data") if isinstance(payload, dict) else None
        return [
            str(item["id"])
            for item in data or []
            if isinstance(item, dict) and item.get("id")
        ]

    def _resolve_model_id(self) -> str:
        try:
            models = self._server_models()
        except Exception:
            return self.config.model
        if self.config.model in models:
            return self.config.model
        if len(models) == 1:
            return models[0]
        return self.config.model

    def _server_context_size(self) -> int:
        """Return the actual context size reported by llama-server, with a configured fallback."""
        try:
            props = self._get_json("/props", timeout_s=3.0)
            n_ctx = (
                props.get("default_generation_settings", {})
                .get("n_ctx")
            )
            if n_ctx is None:
                n_ctx = props.get("n_ctx")
            if n_ctx is not None:
                return max(1024, int(n_ctx))
        except Exception:
            pass
        return self.config.configured_context

    def availability(self) -> dict[str, Any]:
        base = {
            "provider": self.__class__.__name__,
            "model": self.config.model,
            "base_url": self.config.base_url,
            "runtime": "llama.cpp server",
        }
        try:
            health = self._get_json("/health", timeout_s=3.0)
            models = self._server_models()
            context_size = self._server_context_size()
            status = str(health.get("status", "")).lower()
            ready = status in {"ok", "no slot available"}
            return {
                **base,
                "available": ready and bool(models),
                "healthy": ready,
                "health_status": health.get("status"),
                "server_models": models,
                "resolved_model": self._resolve_model_id(),
                "server_context": context_size,
            }
        except Exception as exc:
            return {
                **base,
                "available": False,
                "healthy": False,
                "reason": str(exc),
            }

    @staticmethod
    def _json_compact(value: Any) -> str:
        return json.dumps(
            value,
            ensure_ascii=False,
            default=str,
            separators=(",", ":"),
        )

    def _safe_context_text(self, context: dict[str, Any]) -> str:
        """Serialize only the highest-value context within a token-aware character budget.

        llama-server rejects a request when prompt tokens + output tokens exceed its configured
        context. We therefore derive the input budget from the server's actual /props value.
        Four characters per token is only an approximation, so a safety margin is reserved.
        """
        server_ctx = self._server_context_size()
        reserved_output = min(self.config.max_tokens, max(64, server_ctx // 3))
        input_token_budget = max(
            512,
            server_ctx - reserved_output - self.config.context_safety_margin,
        )
        max_chars = max(1600, input_token_budget * 3)

        compact = {
            "vehicle": context.get("vehicle"),
            "dtcs": context.get("dtcs", [])[-8:],
            "symptoms": context.get("symptoms", [])[-6:],
            "evidence": context.get("evidence", [])[-10:],
            "hypotheses": context.get("hypotheses", [])[-6:],
            "telemetry_summary": context.get("telemetry_summary"),
            "recent_live_signals": context.get("recent_live_signals", [])[-16:],
            "safety_instruction": context.get("safety_instruction"),
        }
        text = self._json_compact(compact)
        if len(text) <= max_chars:
            return text

        # Second pass: retain only the most diagnostic fields.
        minimal = {
            "vehicle": context.get("vehicle"),
            "dtcs": context.get("dtcs", [])[-4:],
            "symptoms": context.get("symptoms", [])[-4:],
            "evidence": context.get("evidence", [])[-6:],
            "hypotheses": context.get("hypotheses", [])[-4:],
            "telemetry_summary": context.get("telemetry_summary"),
            "recent_live_signals": context.get("recent_live_signals", [])[-8:],
            "safety_instruction": context.get("safety_instruction"),
        }
        text = self._json_compact(minimal)
        if len(text) <= max_chars:
            return text
        return text[:max_chars] + "\n[CONTEXT_COMPACTED]"

    def _build_payload(self, prompt: str, context: dict[str, Any]) -> dict[str, Any]:
        system = (
            "You are an evidence-driven automotive diagnostic assistant. "
            "Use only the supplied diagnostic evidence and retrieved knowledge. "
            "Never invent measurements. Never claim a component failure is confirmed "
            "unless the evidence explicitly has status CONFIRMED. Distinguish "
            "REPORTED, MEASURED, CALCULATED, INFERRED, CONFIRMED and REJECTED. "
            "Treat live telemetry as measured data. Explain relationships and uncertainty. "
            "Prefer the safest high-information next diagnostic test."
        )
        response_language = {"en": "English", "ru": "Russian", "hy": "Armenian"}.get(context.get("response_language"), "English")
        system += f" Write every explanatory sentence in {response_language}; preserve diagnostic codes, units and identifiers."
        server_ctx = self._server_context_size()
        # Keep enough room for the response and system/task framing. The context text is already
        # bounded, but this also prevents an oversized max_tokens on small external servers.
        max_output = min(
            self.config.max_tokens,
            max(64, server_ctx // 3),
        )
        return {
            "model": self._resolve_model_id(),
            "messages": [
                {"role": "system", "content": system},
                {
                    "role": "user",
                    "content": (
                        f"TASK:\n{prompt}\n\n"
                        f"DIAGNOSTIC CONTEXT:\n{self._safe_context_text(context)}"
                    ),
                },
            ],
            "temperature": self.config.temperature,
            "max_tokens": max_output,
            "stream": False,
        }

    def _generate_sync(self, prompt: str, context: dict[str, Any]) -> LLMResponse:
        body = self._build_payload(prompt, context)
        req = Request(
            f"{self.config.base_url}/v1/chat/completions",
            data=json.dumps(body, ensure_ascii=False).encode("utf-8"),
            headers=self._headers(),
            method="POST",
        )
        try:
            with urlopen(req, timeout=self.config.timeout_s) as response:
                result = json.loads(response.read().decode("utf-8"))
        except HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")
            # llama-server reports context overflow as HTTP 400. Surface the measured server
            # limit and ask the UI layer to refresh/restart with a larger context if needed.
            if exc.code == 400 and "exceeds the available context size" in detail:
                raise RuntimeError(
                    "llama-server context overflow: "
                    f"{detail}. The client now compacts live diagnostic context automatically. "
                    "If this persists, restart llama-server with a larger --ctx-size (for example 8192)."
                ) from exc
            raise RuntimeError(
                f"llama-server inference HTTP {exc.code}: {detail}"
            ) from exc
        except (URLError, TimeoutError, json.JSONDecodeError, OSError) as exc:
            raise RuntimeError(
                f"llama-server inference failed: {exc}"
            ) from exc

        choices = result.get("choices") or []
        if not choices:
            raise RuntimeError("llama-server returned no choices")
        message = choices[0].get("message") or {}
        text = str(message.get("content") or "").strip()
        if not text:
            raise RuntimeError("llama-server returned an empty response")

        return LLMResponse(
            text=text,
            model=str(body["model"]),
            provider="llama-server",
            raw=result,
        )

    async def generate(self, prompt: str, context: dict[str, Any]) -> LLMResponse:
        return await asyncio.wait_for(
            asyncio.to_thread(self._generate_sync, prompt, context),
            timeout=self.config.timeout_s + 10.0,
        )

from __future__ import annotations

import asyncio
import json
from dataclasses import dataclass
from urllib.request import Request, urlopen
from urllib.error import URLError, HTTPError
from ai.interfaces import LLMProvider, LLMResponse


@dataclass(frozen=True)
class OpenAICompatibleConfig:
    base_url: str
    model: str
    api_key: str | None = None
    timeout_s: float = 60.0
    temperature: float = 0.1


class HttpOpenAICompatibleProvider(LLMProvider):
    """Serve LM Studio, Jan, local GGUF, or compatible hosted APIs.

    These runtimes use GET /v1/models rather than the llama.cpp-only /health.
    """
    def __init__(self, config: OpenAICompatibleConfig):
        self.config = config

    @property
    def _root(self) -> str:
        value = self.config.base_url.rstrip("/")
        return value[:-3] if value.endswith("/v1") else value

    def _headers(self) -> dict[str, str]:
        headers = {"Content-Type": "application/json"}
        if self.config.api_key:
            headers["Authorization"] = f"Bearer {self.config.api_key}"
        return headers

    def availability(self) -> dict:
        """Model availability is independent of the FastAPI /health endpoint."""
        result = {
            "provider": self.__class__.__name__,
            "model": self.config.model,
            "base_url": self._root,
            "available": False,
            "healthy": False,
        }
        req = Request(self._root + "/v1/models", headers=self._headers(), method="GET")
        try:
            with urlopen(req, timeout=4.0) as response:
                payload = json.loads(response.read().decode("utf-8"))
            entries = payload.get("data", []) if isinstance(payload, dict) else []
            models = [
                str(row["id"]) for row in entries
                if isinstance(row, dict) and row.get("id")
            ]
            result["healthy"] = True
            result["server_models"] = models
            result["available"] = self.config.model in models
            if not models:
                result["reason"] = "No models are available. Load a model in the local AI server."
            elif not result["available"]:
                result["reason"] = (
                    f"Model '{self.config.model}' not found. "
                    "Set LLM_MODEL to one of the server_models."
                )
        except (HTTPError, URLError, TimeoutError, json.JSONDecodeError, OSError) as exc:
            result["reason"] = f"AI runtime unavailable: {exc}"
        return result

    def _generate_sync(self, prompt: str, context: dict) -> LLMResponse:
        language = {"en": "English", "ru": "Russian", "hy": "Armenian"}.get(
            context.get("response_language"), "English"
        )
        messages = [
            {"role": "system", "content": (
                "You are an evidence-driven automotive diagnostic assistant. "
                "Use only supplied diagnostic evidence and retrieved sources. "
                "Never invent measurements or claim confirmed faults without evidence. "
                f"Explain uncertainty, and write in {language}."
            )},
            {"role": "user", "content": json.dumps(
                {"task": prompt, "context": context}, ensure_ascii=False
            )},
        ]
        payload = {
            "model": self.config.model,
            "messages": messages,
            "temperature": self.config.temperature,
        }
        req = Request(
            self._root + "/v1/chat/completions",
            data=json.dumps(payload).encode("utf-8"),
            headers=self._headers(),
            method="POST",
        )
        try:
            with urlopen(req, timeout=self.config.timeout_s) as resp:
                body = json.loads(resp.read().decode("utf-8"))
        except (HTTPError, URLError, TimeoutError, json.JSONDecodeError, OSError) as exc:
            raise RuntimeError(f"OpenAI-compatible inference failed: {exc}") from exc
        choices = body.get("choices") or []
        response_text = str((choices[0].get("message") or {}).get("content", "")) if choices else ""
        return LLMResponse(response_text, self.config.model, "openai-compatible", raw=body)

    async def generate(self, prompt: str, context: dict) -> LLMResponse:
        # urllib is synchronous; do not block FastAPI's event loop during inference.
        return await asyncio.to_thread(self._generate_sync, prompt, context)

from __future__ import annotations
from dataclasses import dataclass
from math import sqrt
from statistics import mean

@dataclass(frozen=True)
class AnomalyResult:
    signal: str
    value: float
    baseline_mean: float
    z_score: float
    anomalous: bool
    explanation: str

class NumericAnomalyDetector:
    """Dependency-free baseline detector for live-data smoke analysis; production can swap in ML models."""
    def score(self, signal: str, value: float, baseline: list[float], z_threshold: float = 3.0) -> AnomalyResult:
        if len(baseline) < 2:
            return AnomalyResult(signal, value, baseline[0] if baseline else value, 0.0, False, "Insufficient baseline data.")
        mu = mean(baseline)
        variance = sum((x - mu) ** 2 for x in baseline) / len(baseline)
        sd = sqrt(variance)
        z = 0.0 if sd == 0 else (value - mu) / sd
        return AnomalyResult(signal, value, mu, z, abs(z) >= z_threshold, "Signal is outside the configured baseline threshold." if abs(z) >= z_threshold else "Signal is within the baseline range.")

from __future__ import annotations

import math
from dataclasses import dataclass
from typing import Iterable, Sequence


@dataclass(frozen=True)
class RetrievalCase:
    query: str
    expected_document_ids: frozenset[str]
    required_terms: tuple[str, ...] = ()
    graded_relevance: dict[str, float] | None = None


@dataclass(frozen=True)
class RetrievalEvaluation:
    passed: bool
    recall_at_k: float
    mrr: float
    ndcg_at_k: float
    relevant_found: int
    expected_relevant: int
    missing_terms: tuple[str, ...]


@dataclass(frozen=True)
class RetrievalQualityGate:
    min_recall_at_k: float = 1.0
    min_mrr: float = 1.0
    min_ndcg_at_k: float = 1.0

    def validate(self, result: RetrievalEvaluation) -> bool:
        return (
            result.recall_at_k >= self.min_recall_at_k
            and result.mrr >= self.min_mrr
            and result.ndcg_at_k >= self.min_ndcg_at_k
            and not result.missing_terms
        )


def reciprocal_rank(expected: set[str], ranked_ids: Sequence[str]) -> float:
    for index, document_id in enumerate(ranked_ids, start=1):
        if document_id in expected:
            return 1.0 / index
    return 0.0


def ndcg_at_k(relevance: dict[str, float], ranked_ids: Sequence[str], k: int) -> float:
    def dcg(values: Sequence[float]) -> float:
        return sum((2.0**score - 1.0) / math.log2(i + 2.0) for i, score in enumerate(values))

    predicted = [float(relevance.get(doc_id, 0.0)) for doc_id in ranked_ids[:k]]
    ideal = sorted((float(score) for score in relevance.values()), reverse=True)[:k]
    ideal_dcg = dcg(ideal)
    return 0.0 if ideal_dcg == 0 else dcg(predicted) / ideal_dcg


class RetrievalEvaluator:
    def __init__(self, quality_gate: RetrievalQualityGate | None = None):
        self.quality_gate = quality_gate or RetrievalQualityGate()

    def evaluate(self, case: RetrievalCase, document_ids: Iterable[str], texts: Iterable[str]) -> RetrievalEvaluation:
        ids = list(document_ids)
        text = " ".join(texts).lower()
        found = len(case.expected_document_ids.intersection(ids))
        recall = found / max(1, len(case.expected_document_ids))
        mrr = reciprocal_rank(set(case.expected_document_ids), ids)
        relevance = case.graded_relevance or {doc_id: 1.0 for doc_id in case.expected_document_ids}
        ndcg = ndcg_at_k(relevance, ids, len(ids))
        missing = tuple(term for term in case.required_terms if term.lower() not in text)
        result = RetrievalEvaluation(
            passed=False,
            recall_at_k=recall,
            mrr=mrr,
            ndcg_at_k=ndcg,
            relevant_found=found,
            expected_relevant=len(case.expected_document_ids),
            missing_terms=missing,
        )
        return RetrievalEvaluation(**{**result.__dict__, "passed": self.quality_gate.validate(result)})

