from __future__ import annotations

from dataclasses import dataclass
import re
from collections import Counter
from typing import Any, Sequence


TOKEN_RE = re.compile(r"[a-zA-Z0-9_\-\.]+")

@dataclass(frozen=True)
class RetrievedChunk:
    chunk_id: str
    document_id: str
    content: str
    metadata: dict[str, Any]
    vector_score: float = 0.0
    lexical_score: float = 0.0
    fused_score: float = 0.0
    rank: int = 0


def tokenize(text: str) -> list[str]:
    return [t.lower() for t in TOKEN_RE.findall(text) if len(t) > 1]


class QueryRewriter:
    """Deterministic query expansion for automotive diagnostic terminology.

    This is deliberately transparent: it adds aliases/canonical terms without
    inventing vehicle-specific facts.
    """
    ALIASES = {
        "misfire": ["misfire", "combustion", "cylinder"],
        "shaking": ["rough running", "rough idle", "vibration"],
        "lpg": ["LPG", "autogas", "gas injection", "gas fuel"],
        "maf": ["MAF", "mass air flow", "air mass"],
        "o2": ["O2", "oxygen sensor", "lambda"],
        "trim": ["fuel trim", "STFT", "LTFT"],
    }

    def rewrite(self, query: str) -> list[str]:
        base = query.strip()
        terms = set(tokenize(base))
        expansions: list[str] = []
        for token, aliases in self.ALIASES.items():
            if token in terms or any(a.lower() in base.lower() for a in aliases):
                expansions.extend(aliases)
        expanded = " ".join(dict.fromkeys([base, *expansions]))
        return [base] if expanded == base else [base, expanded]


class HybridFusion:
    """Rank-fusion utility independent of a particular database/vector engine."""
    def __init__(self, vector_weight: float = 0.65, lexical_weight: float = 0.35):
        if vector_weight < 0 or lexical_weight < 0 or vector_weight + lexical_weight <= 0:
            raise ValueError("weights must be non-negative and not both zero")
        total = vector_weight + lexical_weight
        self.vector_weight = vector_weight / total
        self.lexical_weight = lexical_weight / total

    def fuse(self, vector_hits: Sequence[RetrievedChunk], lexical_hits: Sequence[RetrievedChunk], top_k: int = 5) -> list[RetrievedChunk]:
        by_key: dict[str, RetrievedChunk] = {}
        max_v = max((h.vector_score for h in vector_hits), default=1.0) or 1.0
        max_l = max((h.lexical_score for h in lexical_hits), default=1.0) or 1.0
        for h in vector_hits:
            by_key[h.chunk_id] = RetrievedChunk(**{**h.__dict__, "vector_score": h.vector_score / max_v})
        for h in lexical_hits:
            current = by_key.get(h.chunk_id)
            if current is None:
                current = RetrievedChunk(**{**h.__dict__, "lexical_score": h.lexical_score / max_l})
            else:
                current = RetrievedChunk(**{**current.__dict__, "lexical_score": h.lexical_score / max_l})
            by_key[h.chunk_id] = current
        ranked = []
        for h in by_key.values():
            fused = self.vector_weight * h.vector_score + self.lexical_weight * h.lexical_score
            ranked.append(RetrievedChunk(**{**h.__dict__, "fused_score": fused}))
        ranked.sort(key=lambda x: (x.fused_score, x.vector_score, x.lexical_score), reverse=True)
        return [RetrievedChunk(**{**h.__dict__, "rank": i + 1}) for i, h in enumerate(ranked[:top_k])]


def lexical_score(query: str, content: str) -> float:
    q = Counter(tokenize(query))
    d = Counter(tokenize(content))
    if not q or not d:
        return 0.0
    overlap = sum(min(freq, d.get(token, 0)) for token, freq in q.items())
    coverage = overlap / max(1, sum(q.values()))
    phrase = 0.25 if query.strip().lower() in content.lower() else 0.0
    return min(1.0, coverage + phrase)


def metadata_matches(metadata: dict[str, Any], filters: dict[str, Any] | None) -> bool:
    for key, expected in (filters or {}).items():
        if expected is None:
            continue
        actual = metadata.get(key)
        if isinstance(expected, (list, tuple, set)):
            if actual not in expected:
                return False
        elif actual != expected:
            return False
    return True

from __future__ import annotations

import os
import re
from dataclasses import dataclass
from typing import Any, Sequence

from .store import RetrievalHit


@dataclass(frozen=True)
class RerankedHit:
    hit: RetrievalHit
    rerank_score: float


class LexicalReranker:
    """Deterministic reranker for offline/dev use."""

    def rerank(self, query: str, hits: Sequence[RetrievalHit], top_k: int = 5) -> list[RerankedHit]:
        q = [t for t in re.findall(r"[a-zA-Z0-9_]+", query.lower()) if len(t) > 1]
        qset = set(q)
        out: list[RerankedHit] = []
        for h in hits:
            text = f"{h.title} {h.text}".lower()
            matched = sum(1 for t in qset if t in text)
            phrase_bonus = 0.15 if query.lower() in text else 0.0
            score = min(1.0, 0.65 * h.score + 0.35 * (matched / max(1, len(qset))) + phrase_bonus)
            out.append(RerankedHit(h, score))
        return sorted(out, key=lambda x: x.rerank_score, reverse=True)[:top_k]


class CrossEncoderReranker:
    """Optional local cross-encoder reranker.

    Model loading is lazy; production deployments can select a domain-tuned
    cross-encoder without forcing the base test environment to download it.
    """

    def __init__(self, model_name: str | None = None, device: str | None = None, batch_size: int = 16):
        self.model_name = model_name or os.getenv("RAG_RERANKER_MODEL", "cross-encoder/ms-marco-MiniLM-L-6-v2")
        self.device = device or os.getenv("RAG_RERANKER_DEVICE", "cpu")
        self.batch_size = batch_size
        self._model: Any | None = None

    def _load(self) -> Any:
        if self._model is None:
            # PyTorch/sentence-transformers can trigger a native DLL access
            # violation on some Windows environments. Keep the optional
            # cross-encoder opt-in there; the deterministic lexical path remains
            # the safe default. Set RAG_RERANKER_ALLOW_NATIVE=1 to enable it.
            if os.name == "nt" and os.getenv("RAG_RERANKER_ALLOW_NATIVE", "").lower() not in {"1", "true", "yes"}:
                raise RuntimeError(
                    "sentence-transformers is not installed or unavailable. Install backend/requirements-ai.txt "
                    "or use the lexical reranker."
                )
            try:
                from sentence_transformers import CrossEncoder
                self._model = CrossEncoder(self.model_name, device=self.device)
            except Exception as exc:
                raise RuntimeError(
                    "sentence-transformers is not installed or unavailable. Install backend/requirements-ai.txt "
                    "or use the lexical reranker."
                ) from exc
        return self._model

    def rerank(self, query: str, hits: Sequence[RetrievalHit], top_k: int = 5) -> list[RerankedHit]:
        if not hits:
            return []
        model = self._load()
        pairs = [[query, f"{h.title}\n{h.text}"] for h in hits]
        scores = model.predict(pairs, batch_size=self.batch_size, show_progress_bar=False)
        scored = [RerankedHit(hit=h, rerank_score=float(score)) for h, score in zip(hits, scores)]
        scored.sort(key=lambda x: x.rerank_score, reverse=True)
        return scored[:top_k]


def create_reranker(name: str | None = None) -> Any:
    provider = (name or os.getenv("RAG_RERANKER_PROVIDER", "lexical")).lower()
    if provider in {"lexical", "baseline"}:
        return LexicalReranker()
    if provider in {"cross_encoder", "cross-encoder", "ce"}:
        return CrossEncoderReranker()
    raise ValueError(f"unsupported reranker provider: {provider}")

from __future__ import annotations
from dataclasses import dataclass, field
from typing import Iterable

@dataclass(frozen=True)
class KnowledgeDocument:
    document_id: str
    title: str
    text: str
    metadata: dict = field(default_factory=dict)

@dataclass(frozen=True)
class RetrievalHit:
    document_id: str
    title: str
    text: str
    score: float
    metadata: dict

class HybridKnowledgeStore:
    """Small local RAG foundation. Uses lexical scoring now; embedding/reranker adapters can be added later."""
    def __init__(self, documents: Iterable[KnowledgeDocument] = ()):
        self.documents: dict[str, KnowledgeDocument] = {d.document_id: d for d in documents}

    def add(self, document: KnowledgeDocument) -> None:
        self.documents[document.document_id] = document

    def search(self, query: str, filters: dict | None = None, top_k: int = 5) -> list[RetrievalHit]:
        filters = filters or {}
        tokens = {t.lower() for t in query.split() if len(t) > 1}
        hits: list[RetrievalHit] = []
        for d in self.documents.values():
            if any(filters.get(k) is not None and d.metadata.get(k) != v for k, v in filters.items()):
                continue
            hay = f"{d.title} {d.text}".lower()
            matched = sum(1 for t in tokens if t in hay)
            if matched:
                score = matched / max(1, len(tokens))
                hits.append(RetrievalHit(d.document_id, d.title, d.text, score, d.metadata))
        return sorted(hits, key=lambda x: x.score, reverse=True)[:top_k]

from __future__ import annotations
import json
from diagnostic.models import DiagnosticSession, EvidenceStatus, EvidenceSource, DiagnosticTest, SessionState
from diagnostic.rules import DiagnosticReasoningEngine
from ai.reasoning.evidence_extractor import StructuredEvidenceExtractor
from ai.ml.anomaly import NumericAnomalyDetector
from diagnostic.decision import DiagnosticDecisionEngine

class DiagnosticIntelligenceEngine:
    """Evidence-driven loop around the deterministic domain engine."""
    def __init__(self):
        self.extractor = StructuredEvidenceExtractor()
        self.rules = DiagnosticReasoningEngine()
        self.anomaly = NumericAnomalyDetector()
        self.decision = DiagnosticDecisionEngine()

    def ingest_text(self, session: DiagnosticSession, text: str, source: EvidenceSource = EvidenceSource.USER_REPORTED) -> DiagnosticSession:
        session.evidence.extend(self.extractor.extract(text, source))
        session.state = SessionState.SYMPTOMS_COLLECTED
        return session

    def normalize_existing(self, session: DiagnosticSession) -> DiagnosticSession:
        existing = {e.fact for e in session.evidence}
        for symptom in session.symptoms:
            for e in self.extractor.from_symptom(symptom):
                if e.fact not in existing:
                    session.evidence.append(e)
                    existing.add(e.fact)
        for dtc in session.dtcs:
            e = self.extractor.from_dtc(dtc)
            if e.fact not in existing:
                session.evidence.append(e); existing.add(e.fact)
        return session

    def analyze(self, session: DiagnosticSession) -> DiagnosticSession:
        self.normalize_existing(session)
        self.rules.analyze(session)
        self._annotate_scores(session)
        self._apply_test_history(session)
        self._add_missing_questions(session)
        session.state = SessionState.QUESTIONS_PENDING if session.audit_log and session.audit_log[-1].get("event") == "QUESTIONS_IDENTIFIED" else SessionState.INITIAL_ANALYSIS
        rule_recommendations = list(session.recommendations)
        self.decision.refresh_recommendations(session)
        if not session.recommendations and rule_recommendations:
            session.recommendations = self._fallback_recommendations(
                session, rule_recommendations
            )
        if session.recommendations:
            session.state = SessionState.TESTING
        elif any(x.get("event") == "QUESTIONS_IDENTIFIED" for x in session.audit_log[-3:]):
            session.state = SessionState.QUESTIONS_PENDING
        else:
            session.state = SessionState.INITIAL_ANALYSIS
        session.audit_log.append({"event": "INTELLIGENCE_ANALYSIS_COMPLETED", "evidence_count": len(session.evidence), "hypothesis_count": len(session.hypotheses)})
        return session

    def record_test_result(self, session: DiagnosticSession, test_id, result: str, measurements: dict | None = None, notes: str | None = None) -> DiagnosticSession:
        from diagnostic.models import TestResult, Evidence
        measurements = measurements or {}
        normalized_result = result.strip().upper()
        selected_test = next(
            (x for x in session.recommendations if str(x.id) == str(test_id)),
            None,
        )
        if selected_test is None:
            previous = next((x for x in reversed(session.test_results) if str(x.test_id) == str(test_id)), None)
            if previous is not None:
                selected_test = DiagnosticTest(id=test_id, name=previous.test_name or str(test_id), purpose="", target_hypotheses=previous.target_hypotheses)
        session.test_results.append(TestResult(
            test_id=test_id,
            target_hypotheses=list(selected_test.target_hypotheses) if selected_test else [],
            result=normalized_result,
            measurements=measurements,
            notes=notes,
            test_name=selected_test.name if selected_test else None,
        ))
        evidence_parts = [
            f"Completed diagnostic test: {selected_test.name}" if selected_test else f"Completed diagnostic test ID: {test_id}",
            f"result: {normalized_result}",
        ]
        if notes and notes.strip():
            evidence_parts.append(f"technician notes: {notes.strip()}")
        if measurements:
            evidence_parts.append(
                "measurements: " + json.dumps(measurements, ensure_ascii=False, sort_keys=True, default=str)
            )
        session.evidence.append(Evidence(
            fact="; ".join(evidence_parts),
            source=EvidenceSource.TECHNICIAN_OBSERVED,
            status=EvidenceStatus.MEASURED,
            confidence=0.95,
            metadata={"test_id": str(test_id), "target_hypotheses": list(selected_test.target_hypotheses) if selected_test else [], "test_name": selected_test.name if selected_test else None, "result": normalized_result, "measurements": measurements, "notes": notes},
        ))
        analyzed = self.analyze(session)
        supported = [h.category for h in analyzed.hypotheses if h.status == "supported_by_test"]
        analyzed.audit_log.append({"event": "TEST_RESULT_INTERPRETED", "test_id": str(test_id), "supported_hypotheses": supported})
        analyzed.state = SessionState.HYPOTHESIS_VALIDATION
        return analyzed

    def _fallback_recommendations(
        self, session: DiagnosticSession, candidates: list[DiagnosticTest]
    ) -> list[DiagnosticTest]:
        """Keep rule-generated tests, but never reintroduce a completed test by name.

        Rule analysis creates fresh UUIDs on each pass, so UUID-only filtering can
        accidentally resurrect a test that was already recorded. Stable names are
        the fallback identity for completed tests.
        """
        latest_ids = {str(item.test_id): item.result for item in session.test_results}
        latest_names = {self.decision._recommendation_key(item.test_name): item.result for item in session.test_results if item.test_name}
        completed_ids = {key for key, result in latest_ids.items() if result in {"PASS", "FAIL"}}
        completed_names = {key for key, result in latest_names.items() if result in {"PASS", "FAIL"}}
        remaining = [
            item for item in candidates
            if str(item.id) not in completed_ids
            and self.decision._recommendation_key(item.name) not in completed_names
        ]
        enriched = self.decision.enrich_external_recommendations(session, remaining)
        return sorted(
            enriched,
            key=lambda item: (
                -item.priority_score,
                {"LOW": 0, "MEDIUM": 1, "HIGH": 2}.get(item.risk_level.upper(), 3),
                item.estimated_cost,
                item.name,
            ),
        )

    def next_test(self, session: DiagnosticSession) -> DiagnosticTest | None:
        return session.recommendations[0] if session.recommendations else None

    def _annotate_scores(self, session: DiagnosticSession) -> None:
        text = " ".join(e.fact.lower() for e in session.evidence if not e.metadata.get("test_id"))
        for h in session.hypotheses:
            score = 0.25
            category = h.category.lower()
            if category in text:
                score += 0.10
            if category in {"lpg injection", "lpg fuel delivery", "lpg calibration"} and "lpg" in text:
                score += 0.25
            if category == "ignition under lpg load" and "misfire" in text and "lpg" in text:
                score += 0.22
            if category == "lean mixture" and any(x in text for x in ("lean", "fuel trim", "p0171", "p0174")):
                score += 0.25
            if category == "rich mixture" and any(x in text for x in ("rich", "p0172", "p0175")):
                score += 0.25
            if category == "air metering / maf" and any(x in text for x in ("maf", "p0101", "airflow")):
                score += 0.25
            if category == "catalyst efficiency" and any(x in text for x in ("p0420", "p0430", "catalyst")):
                score += 0.25
            if category == "cam/crank correlation" and any(x in text for x in ("p0016", "p0017", "p0018", "p0019", "timing")):
                score += 0.25
            if category == "transmission control / gear ratio" and any(x in text for x in ("p0730", "gear", "transmission", "slip")):
                score += 0.25
            if category == "vehicle network communication" and any(x in text for x in ("u0100", "u0121", "can", "communication")):
                score += 0.25
            h.confidence_score = round(min(score, 0.95), 4)
            h.status = f"possible:{h.confidence_score:.2f}"

    def _apply_test_history(self, session: DiagnosticSession) -> None:
        """Replay latest outcomes from baseline; refreshes never compound scores.

        These bounded evidence scores are heuristic rankings, not calibrated
        failure probabilities. PASS weakens a targeted fault; FAIL supports it;
        INCOMPLETE withdraws a previous conclusion for the same test.
        """
        from diagnostic.decision import CATALOG
        aliases = {
            "LPG injection": "LPG fuel delivery / mixture",
            "LPG fuel delivery": "LPG fuel delivery / mixture",
            "LPG calibration": "LPG fuel delivery / mixture",
            "ignition": "ignition / combustion",
            "ignition under LPG load": "ignition / combustion",
            "intake": "air-fuel / intake",
        }
        latest = {}
        for result in session.test_results:
            key = self.decision._recommendation_key(result.test_name) if result.test_name else str(result.test_id)
            latest[key] = result
        for result in latest.values():
            targets = list(result.target_hypotheses)
            if not targets:
                # Older persisted sessions may carry the targets in evidence or
                # still have the test in the canonical catalog/recommendations.
                for evidence in reversed(session.evidence):
                    if evidence.metadata.get("test_id") == str(result.test_id):
                        targets = evidence.metadata.get("target_hypotheses", [])
                        if targets:
                            break
                if not targets:
                    candidates = list(CATALOG) + list(session.recommendations)
                    match = next((x for x in candidates if result.test_name and self.decision._recommendation_key(x.name) == self.decision._recommendation_key(result.test_name)), None)
                    targets = list(match.target_hypotheses) if match else []
            target_groups = {aliases.get(x, x) for x in targets}
            for h in session.hypotheses:
                if aliases.get(h.category, h.category) not in target_groups:
                    continue
                probe = h.model_copy(deep=True)
                probe.status = "possible"
                probe_session = DiagnosticSession(hypotheses=[probe])
                self.decision.update_hypotheses_from_result(
                    probe_session, DiagnosticTest(name="result", purpose="", target_hypotheses=[h.category]),
                    " ".join(x for x in (result.result, result.notes or "") if x),
                )
                multiplier = {"supported_by_test": 2.0, "disfavored_by_test": 0.4}.get(probe.status)
                if multiplier is None:
                    continue
                score = h.confidence_score if h.confidence_score is not None else 0.25
                odds = score / max(1.0 - score, 0.0001) * multiplier
                h.confidence_score = round(min(max(odds / (1.0 + odds), 0.01), 0.95), 4)
                h.status = probe.status
                evidence_ids = [e.id for e in session.evidence if e.metadata.get("test_id") == str(result.test_id) and e.metadata.get("result") == result.result]
                links = h.supporting_evidence_ids if multiplier > 1 else h.contradicting_evidence_ids
                if evidence_ids and evidence_ids[-1] not in links:
                    links.append(evidence_ids[-1])
        session.hypotheses.sort(key=lambda h: -(h.confidence_score or 0))

    def _add_missing_questions(self, session: DiagnosticSession) -> None:
        text = " ".join(e.fact.lower() for e in session.evidence)
        questions = []
        if "lpg" in text and "gas pressure" not in text:
            questions.append("What is LPG gas pressure at idle and during the reported load/RPM window?")
        if "misfire" in text and not any("fuel trim" in e.fact.lower() for e in session.evidence):
            questions.append("What are STFT/LTFT values on petrol versus LPG at idle and under load?")
        if not questions:
            return
        session.audit_log.append({"event": "QUESTIONS_IDENTIFIED", "questions": questions})

from __future__ import annotations
import re
from diagnostic.models import EvidenceSource, EvidenceStatus, Evidence, Symptom, DTC

class StructuredEvidenceExtractor:
    """Conservative rule-based extraction: converts language into explicit evidence, never a diagnosis."""

    PATTERNS = {
        "fuel_mode_lpg": [r"\blpg\b", r"gas mode", r"on lpg"],
        "fuel_mode_petrol": [r"\bpetrol\b", r"\bgasoline\b", r"\bbenzine\b"],
        "misfire": [r"misfire", r"shak(?:e|ing|es)", r"rough idle", r"jerk(?:ing|s)"],
        "acceleration": [r"acceleration", r"accelerat(?:e|ing|ion)", r"under load"],
        "below_2000_rpm": [r"below\s*2000\s*rpm", r"under\s*2000\s*rpm", r"<\s*2000\s*rpm"],
        "petrol_normal": [r"petrol.*normal", r"normal.*petrol", r"runs fine on petrol"],
    }

    def extract(self, text: str, source: EvidenceSource = EvidenceSource.USER_REPORTED) -> list[Evidence]:
        raw = " ".join(text.strip().split())
        if not raw:
            return []
        out: list[Evidence] = [Evidence(fact=raw, source=source, status=EvidenceStatus.REPORTED)]
        lowered = raw.lower()
        for key, patterns in self.PATTERNS.items():
            if any(re.search(p, lowered) for p in patterns):
                out.append(Evidence(fact=key, source=source, status=EvidenceStatus.REPORTED, confidence=0.8, metadata={"derived_from": raw}))
        return out

    def from_symptom(self, symptom: Symptom) -> list[Evidence]:
        out = self.extract(symptom.raw_text)
        if symptom.normalized:
            for key, value in symptom.normalized.items():
                out.append(Evidence(fact=f"{key}={value}", source=EvidenceSource.USER_REPORTED, status=EvidenceStatus.REPORTED, confidence=0.9))
        return out

    def from_dtc(self, dtc: DTC) -> Evidence:
        status = EvidenceStatus.MEASURED if dtc.source == EvidenceSource.ECU_REPORTED else EvidenceStatus.REPORTED
        return Evidence(fact=dtc.code.upper(), source=dtc.source, status=status, confidence=0.95 if status == EvidenceStatus.MEASURED else 0.8)

from __future__ import annotations
from fastapi import APIRouter, HTTPException
from api.state import sessions
from acquisition.models import AcquisitionStartRequest, AcquisitionStatus, SimulatorParameters
from acquisition.service import AcquisitionApiService
from telemetry.channels import channel_name

router=APIRouter(prefix='/api/v1/acquisition',tags=['vehicle-acquisition'])
service=AcquisitionApiService()

@router.post('/sessions/{session_id}/start',response_model=AcquisitionStatus)
async def start_acquisition(session_id: str, request: AcquisitionStartRequest):
    if session_id not in sessions: raise HTTPException(404,'Session not found')
    if request.adapter != 'simulator':
        from api.state import vci_manager
        device_id = request.device_id or sessions[session_id].connected_device_id
        if not device_id:
            raise HTTPException(409, 'Bind a connected server-local device or supply device_id')
        try:
            device = vci_manager.status(device_id)
            kind = device.connection_type.lower().replace('-', '')
            if request.adapter == 'bound':
                if kind not in {'wifi', 'usb', 'ble'}:
                    raise ValueError('Bound acquisition requires a physical server-local adapter')
                request = request.model_copy(update={'adapter': kind})
            if device.status.value != 'connected' or kind != request.adapter:
                raise ValueError('Connected device transport does not match requested adapter')
            return await service.start_device(sessions[session_id].session_id, request, vci_manager, device_id)
        except Exception as error:
            raise HTTPException(409, str(error)) from error
    try: return await service.start_simulator(sessions[session_id].session_id,request)
    except ValueError as exc: raise HTTPException(409, str(exc)) from exc
    except Exception as exc: raise HTTPException(502,f'Acquisition start failed: {exc}') from exc

@router.post('/sessions/{session_id}/stop',response_model=AcquisitionStatus)
async def stop_acquisition(session_id: str):
    if session_id not in sessions: raise HTTPException(404,'Session not found')
    try: return await service.stop(sessions[session_id].session_id)
    except KeyError: raise HTTPException(409,'Acquisition is not running')

@router.get('/sessions/{session_id}/status',response_model=AcquisitionStatus)
def acquisition_status(session_id: str):
    if session_id not in sessions: raise HTTPException(404,'Session not found')
    try: return service.status(sessions[session_id].session_id)
    except KeyError: raise HTTPException(404,'Acquisition not started')

@router.get('/sessions/{session_id}/records')
def acquisition_records(session_id: str, limit: int = 100):
    if session_id not in sessions: raise HTTPException(404,'Session not found')
    if limit < 1 or limit > 1000: raise HTTPException(400,'limit must be between 1 and 1000')
    try:
        return {'records':[r.__dict__ | {'display_name':channel_name(r.channel),'id':str(r.id),'session_id':str(r.session_id),'source_type':r.source_type.value,'raw':r.raw.hex() if r.raw else None} for r in service.snapshot(sessions[session_id].session_id,limit)]}
    except KeyError: raise HTTPException(404,'Acquisition not started')


@router.put('/sessions/{session_id}/simulator/parameters')
def simulator_parameters(session_id: str, parameters: SimulatorParameters):
    if session_id not in sessions:
        raise HTTPException(404, 'Session not found')
    try:
        return service.set_simulator_parameters(sessions[session_id].session_id, parameters)
    except (KeyError, ValueError) as exc:
        raise HTTPException(409, str(exc)) from exc

from __future__ import annotations
from fastapi import APIRouter, HTTPException
from pydantic import BaseModel, Field
from api.state import sessions
from network_discovery.state import passive_service, active_service
from api.multi_bus_routes import _runtime as multi_bus_runtime
from vehicle.network.active_discovery import ActiveProbePolicy

router = APIRouter(prefix='/api/v1/network-discovery', tags=['network-discovery-active'])

class ActiveProbeRequest(BaseModel):
    candidate_ids: list[str] | None = Field(default=None, max_length=64)
    timeout_ms: int = Field(default=800, ge=100, le=5000)
    max_targets: int = Field(default=16, ge=1, le=64)
    inter_probe_ms: int = Field(default=50, ge=0, le=5000)
    allowed_dids: list[int] = Field(default_factory=lambda: [0xF190, 0xF187, 0xF191], max_length=8)

@router.post('/sessions/{session_id}/active-probe')
async def active_probe(session_id: str, request: ActiveProbeRequest):
    if session_id not in sessions: raise HTTPException(404, 'Session not found')
    runtime = multi_bus_runtime.get(session_id)
    if not runtime: raise HTTPException(409, 'Multi-bus diagnostic runtime is required for active discovery')
    try:
        policy = ActiveProbePolicy(tuple(request.allowed_dids), request.timeout_ms, request.max_targets, request.inter_probe_ms)
        passive = passive_service.analyze(sessions[session_id].session_id)
        results = await active_service.probe_candidates(sessions[session_id].session_id, passive, runtime.raw_buses, runtime.topology, request.candidate_ids, policy)
        return {'session_id': session_id, 'results': [r.to_dict() for r in results], 'correlation': active_service.correlate(sessions[session_id].session_id, passive, runtime.topology)}
    except ValueError as exc: raise HTTPException(400, str(exc)) from exc

@router.get('/sessions/{session_id}/active-map')
def active_map(session_id: str):
    if session_id not in sessions: raise HTTPException(404, 'Session not found')
    runtime = multi_bus_runtime.get(session_id)
    if not runtime: raise HTTPException(409, 'Multi-bus diagnostic runtime is required for active discovery')
    passive = passive_service.analyze(sessions[session_id].session_id)
    return active_service.correlate(sessions[session_id].session_id, passive, runtime.topology)

"""Read-only advanced diagnostic interfaces shared by all presentation clients."""
from fastapi import APIRouter, HTTPException
from pydantic import BaseModel, Field
from obd.j1939 import decode_diagnostic_frame
from vehicle.doip.client import DoipClient, DoipError
from vehicle.uds.read_only import read_request

router = APIRouter(prefix='/api/v1/obd', tags=['OBD'])


class DoipRead(BaseModel):
    host: str = Field(min_length=1, max_length=253)
    port: int = Field(default=13400, ge=1, le=65535)
    source_address: int = Field(ge=1, le=65535)
    target_address: int = Field(ge=1, le=65535)
    did: int | None = Field(default=None, ge=0, le=65535)
    dtc_status_mask: int | None = Field(default=None, ge=0, le=255)
    timeout: float = Field(default=5, gt=0, le=30)


class J1939Frame(BaseModel):
    arbitration_id: int = Field(ge=0, le=0x1FFFFFFF)
    data: str = Field(min_length=4, max_length=24)


@router.post('/uds/doip/read')
async def read_doip(request: DoipRead):
    try:
        command = read_request(request.did, request.dtc_status_mask)
    except ValueError as error:
        raise HTTPException(422, str(error)) from error
    client = DoipClient(request.host, source_address=request.source_address,
                        target_address=request.target_address, port=request.port, timeout=request.timeout)
    try:
        raw = await client.read(command)
    except DoipError as error:
        raise HTTPException(502, str(error)) from error
    return {'response_hex': raw.hex().upper(), 'service': raw[0],
            'data_hex': raw[3 if request.did is not None else 2:].hex().upper(),
            'source': 'server_local_doip', 'read_only': True,
            'ecu_address': request.target_address, 'scope': 'Requested ECU/service only',
            'hardware_verified': False}


@router.post('/j1939/decode')
def decode_j1939(request: J1939Frame):
    try:
        return decode_diagnostic_frame(request.arbitration_id, bytes.fromhex(request.data))
    except ValueError as error:
        raise HTTPException(422, str(error)) from error


class J1939Capture(BaseModel):
    frames: list[J1939Frame] = Field(min_length=2, max_length=256)


class J1708Packet(BaseModel):
    data: str = Field(min_length=8, max_length=64)


@router.post('/j1939/decode-bam')
def decode_j1939_bam(request: J1939Capture):
    from obd.j1939 import decode_bam_capture
    try:
        return decode_bam_capture([(frame.arbitration_id, bytes.fromhex(frame.data)) for frame in request.frames])
    except ValueError as error:
        raise HTTPException(422, str(error)) from error


@router.post('/j1708/decode')
def decode_j1708(request: J1708Packet):
    from obd.j1587 import decode_packet
    try:
        return decode_packet(bytes.fromhex(request.data))
    except ValueError as error:
        raise HTTPException(422, str(error)) from error


class ElmUdsRead(BaseModel):
    device_id: str = Field(min_length=1, max_length=256)
    request_id: int = Field(ge=0, le=0x1FFFFFFF)
    response_id: int = Field(ge=0, le=0x1FFFFFFF)
    did: int | None = Field(default=None, ge=0, le=65535)
    dtc_status_mask: int | None = Field(default=None, ge=0, le=255)


@router.post('/uds/elm/read')
async def read_elm_uds(request: ElmUdsRead):
    from api.state import vci_manager
    try:
        command = read_request(request.did, request.dtc_status_mask)
    except ValueError as error:
        raise HTTPException(422, str(error)) from error
    try:
        if vci_manager.status(request.device_id).connection_type.lower() == 'simulator':
            raise ValueError('This endpoint requires a physical CAN adapter')
        physical = vci_manager if hasattr(vci_manager, 'connected_obd') else vci_manager._physical()
        client = physical.connected_obd(request.device_id)
        raw = await client.read_uds(request.request_id, request.response_id, command)
    except Exception as error:
        raise HTTPException(409, str(error)) from error
    return {'response_hex': raw.hex().upper(), 'source': 'server_local_elm_can',
            'read_only': True, 'hardware_verified': False,
            'scope': 'Explicitly addressed ECU/read service only'}

from __future__ import annotations

from fastapi import APIRouter, HTTPException, Query
from pydantic import BaseModel

from api.state import sessions
from ai.llm.factory import build_llm_provider
from ai.rag.store import HybridKnowledgeStore, KnowledgeDocument
from ai.reasoning.pipeline import DiagnosticIntelligencePipeline

router = APIRouter(prefix="/api/v1/ai", tags=["ai"])
knowledge_store = HybridKnowledgeStore()
pipeline = DiagnosticIntelligencePipeline(knowledge_store)


class KnowledgeRequest(BaseModel):
    document_id: str
    title: str
    text: str
    metadata: dict = {}


class SearchRequest(BaseModel):
    query: str
    filters: dict = {}
    top_k: int = 5


@router.post("/knowledge")
def add_knowledge(request: KnowledgeRequest):
    knowledge_store.add(KnowledgeDocument(request.document_id, request.title, request.text, request.metadata))
    return {"status": "indexed", "document_id": request.document_id}


@router.post("/knowledge/search")
