        candidate["image_authority"] = "backend"
        return candidate
    except ValueError as exc:
        raise HTTPException(422, str(exc)) from exc
    except RemoteRegistryUnavailable as exc:
        raise HTTPException(503, str(exc)) from exc

"""Import licensed Commons page images with source/creator/license metadata."""
from html import unescape
import json
import re
from urllib.parse import urlencode, urlparse
from urllib.request import Request, urlopen

ALLOWED_LICENSES = {"CC0", "Public domain", "CC BY 2.0", "CC BY 3.0", "CC BY 4.0",
                    "CC BY-SA 2.0", "CC BY-SA 2.5", "CC BY-SA 3.0", "CC BY-SA 4.0"}
MAX_IMAGE_BYTES = 8 * 1024 * 1024


def fetch_json(host: str, **params) -> dict:
    url = f"https://{host}/w/api.php?" + urlencode(params | {"format": "json", "formatversion": 2})
    with urlopen(Request(url, headers={"User-Agent": "AI-Car-Scanner/0.6.0 (vehicle reference import)"}), timeout=20) as response:
        return json.loads(response.read(2 * 1024 * 1024))


def clean_text(value: str) -> str:
    return unescape(re.sub(r"<[^>]*>", "", value)).strip()


def image_metadata(title: str, get=fetch_json) -> dict:
    page = get("en.wikipedia.org", action="query", prop="pageimages", piprop="name", titles=title, redirects=1)
    pages = page.get("query", {}).get("pages", [])
    filename = next((p.get("pageimage") for p in pages if p.get("pageimage")), None)
    if not filename:
        raise ValueError("Article has no Commons page image")
    details = get("commons.wikimedia.org", action="query", prop="imageinfo", titles="File:"+filename,
                  iiprop="url|extmetadata", iiurlwidth=960)
    infos = [i for p in details.get("query", {}).get("pages", []) for i in p.get("imageinfo", [])]
    if not infos:
        raise ValueError("Image is not available from Wikimedia Commons")
    info = infos[0]
    ext = info.get("extmetadata", {})
    def text(name):
        return clean_text(ext.get(name, {}).get("value", ""))
    license_name = text("LicenseShortName")
    if license_name not in ALLOWED_LICENSES:
        raise ValueError(f"License is missing or outside the supported reuse list: {license_name}")
    url = info.get("thumburl") or info["url"]
    parsed = urlparse(url)
    if parsed.scheme != "https" or parsed.netloc != "upload.wikimedia.org":
        raise ValueError("Unexpected Commons image host")
    return {"download_url": url, "original_url": info["url"], "source_page": info["descriptionurl"],
            "creator": text("Artist"), "credit": text("Credit"), "license": license_name,
            "license_url": text("LicenseUrl"), "file_title": filename,
            "kind": "wikimedia_commons", "article_title": title}


def fetch_image(url: str) -> bytes:
    parsed = urlparse(url)
    if parsed.scheme != "https" or parsed.netloc != "upload.wikimedia.org":
        raise ValueError("Only HTTPS Commons image downloads are supported")
    with urlopen(Request(url, headers={"User-Agent": "AI-Car-Scanner/0.6.0"}), timeout=30) as response:
        if urlparse(response.geturl()).netloc != "upload.wikimedia.org":
            raise ValueError("Unexpected download redirect")
        data = response.read(MAX_IMAGE_BYTES+1)
    if len(data) > MAX_IMAGE_BYTES:
        raise ValueError("Image exceeds import size limit")
    return data

"""Immutable startup snapshots plus a deliberately small, audited hot-reload surface.

Priority: model defaults, global JSON, environment overlay, allowlisted ENV,
then explicitly user-adjustable preferences. No secret values belong in JSON.
"""
from __future__ import annotations
from copy import deepcopy
from functools import lru_cache
import json
import os
import sys
from pathlib import Path
from threading import RLock
from urllib.parse import urlsplit

ROOT = Path(getattr(sys, "_MEIPASS", Path(__file__).resolve().parents[3]))
ENV_PATHS = {"AI_CAR_BACKEND_PORT": ("services.backend_port", int),
             "DIAGNOSTIC_LLM_PROVIDER": ("ai.provider", str),
             "LOCAL_LLM_SERVER_CONTEXT": ("ai.context", int),
             "LOCAL_LLM_SERVER_URL": ("ai.endpoint", str),
             "LOCAL_LLM_TEMPERATURE": ("ai.temperature", float),
             "LOCAL_LLM_MAX_TOKENS": ("ai.max_tokens", int),
             "LOCAL_LLM_SERVER_TIMEOUT_S": ("ai.timeout_seconds", float),
             "AI_CAR_CATALOG_URL": ("services.vehicle_catalog.url", str),
             "AI_CAR_CATALOG_MODE": ("services.vehicle_catalog.mode", str)}
PREFERENCES = {"app.language", "app.units", "ui.theme", "ui.chart"}
RELOADABLE = {"services.vehicle_catalog.timeout_seconds", "services.vehicle_catalog.retries"}

class ConfigurationError(ValueError):
    """A sanitized error; raw configuration and credentials are never echoed."""

def merge(base, overlay):
    if not isinstance(overlay, dict):
        raise ConfigurationError("Configuration must be an object")
    result = deepcopy(base) if isinstance(base, dict) else {}
    for key, value in overlay.items():
        result[key] = merge(result.get(key, {}), value) if isinstance(value, dict) else value
    return result

def put(data, path, value):
    parts = path.split(".")
    target = data
    for part in parts[:-1]:
        target = target.setdefault(part, {})
    target[parts[-1]] = value

def read(path):
    try:
        if path.stat().st_size > 131072:
            raise ConfigurationError("Configuration exceeds size limit")
        def unique(pairs):
            result = {}
            for key, value in pairs:
                if key in result: raise ConfigurationError("Duplicate configuration key")
                result[key] = value
            return result
        return json.loads(path.read_text(encoding="utf-8"), object_pairs_hook=unique)
    except (OSError, ValueError):
        raise ConfigurationError("Configuration file is missing or invalid JSON") from None

def source_data(root, env):
    """Stdlib-only document loading, shared by first-clone setup and runtime.

    This is syntax/version preflight, not a replacement for backend schema
    validation. Native clients never receive a configuration control plane.
    """
    directory = Path(root) / "config"
    data = read(directory / "global_config.json")
    if not isinstance(data, dict) or type(data.get('schema_version', 1)) is not int or data.get('schema_version', 1) != 1:
        raise ConfigurationError("Unsupported configuration schema version")
    name = env.get("AI_CAR_CONFIG_ENV", "development")
    if name not in {"development", "testing", "production"}:
        raise ConfigurationError("Unknown configuration environment")
    overlay = directory / "environments" / f"{name}.json"
    if overlay.is_file(): data = merge(data, read(overlay))
    elif name == "production": raise ConfigurationError("Production overlay must be explicitly installed")
    if type(data.get('schema_version', 1)) is not int or data.get('schema_version', 1) != 1:
        raise ConfigurationError("Unsupported configuration schema version")
    return data


def validate(data):
    from pydantic import ValidationError
    from .models import GlobalConfig
    # JSON conversion accepts JSON arrays as frozen tuples without type coercion.
    try:
        model = GlobalConfig.model_validate_json(json.dumps(data))
    except (ValidationError, ValueError, TypeError):
        raise ConfigurationError("Configuration schema validation failed") from None
    for url, paths in ((model.ai.endpoint, {"", "/", "/v1", "/v1/"}), (model.services.vehicle_catalog.url, {"", "/"})):
        parsed = urlsplit(url)
        try:
            if parsed.port == 0: raise ValueError("Invalid service port")
        except ValueError:
            raise ConfigurationError("Invalid service URL") from None
        if parsed.scheme not in {"http", "https"} or not parsed.hostname or parsed.username or parsed.password or parsed.query or parsed.fragment:
            raise ConfigurationError("Service URLs must be HTTP(S) origins without credentials")
        if parsed.path not in paths:
            raise ConfigurationError("Service URLs must be origins")
        if parsed.scheme == "http" and parsed.hostname not in {"localhost", "127.0.0.1", "::1"}:
            raise ConfigurationError("Remote services require HTTPS")
    return model

def classification(path):
    if path.startswith("native."): return "STATIC_BUILD_TIME"
    if path in PREFERENCES: return "USER_PREFERENCE"
    if path in RELOADABLE: return "RUNTIME_RELOADABLE"
    if path.startswith(("marketplace.", "obd.read_only", "obd.write_policy", "updates.")) or path.endswith("_env"):
        return "SECURITY_SENSITIVE"
    return "STARTUP_ONLY"

class ConfigManager:
    def __init__(self, root=ROOT, environ=None, preferences=None):
        env = os.environ if environ is None else environ
        from .models import GlobalConfig
        data = merge(GlobalConfig().model_dump(mode="json"), source_data(root, env))
        for key, (path, cast) in ENV_PATHS.items():
            if key in env:
                try: put(data, path, cast(env[key]))
                except (ValueError, TypeError): raise ConfigurationError("Invalid authorized environment override") from None
        for path, value in (preferences or {}).items():
            if path not in PREFERENCES: raise ConfigurationError("Preference is not user-adjustable")
            put(data, path, value)
        self._snapshot = validate(data)
        self._lock = RLock()
        self.revision = 1

    @property
    def snapshot(self):
        with self._lock: return self._snapshot

    def public_snapshot(self):
        with self._lock:
            data = self.snapshot.model_dump(mode="json")
            # Paths, origins and environment reference names are internal deployment data.
            return {"schema_version": 1, "revision": self.revision, "app": data["app"],
                    "ui": data["ui"], "marketplace": data["marketplace"],
                    "native": data["native"], "runtime_status": "not_probed"}

    def reload(self, changes, *, expected_revision, audit):
        """Caller must authorize admin; audit must durably succeed before publication."""
        with self._lock:
            if expected_revision != self.revision: raise ConfigurationError("Configuration revision conflict")
            if not changes or not set(changes) <= RELOADABLE:
                raise ConfigurationError("Only runtime-reloadable fields may change; other settings require restart")
            data = self._snapshot.model_dump(mode="json")
            for path, value in changes.items(): put(data, path, value)
            candidate = validate(data)
            audit({"revision": self.revision + 1, "paths": sorted(changes)})
            self._snapshot = candidate
            self.revision += 1
            return self.public_snapshot()

@lru_cache(maxsize=1)
def get_manager():
    return ConfigManager()

from __future__ import annotations

import argparse
import os
import shutil
import socket
import subprocess
import sys
import threading
import time
from datetime import datetime, timezone
from pathlib import Path
from urllib.error import URLError
from urllib.request import urlopen
from urllib.parse import urlsplit

SOURCE_ROOT = Path(__file__).resolve().parents[1]
if getattr(sys, "frozen", False):
    BUNDLE_ROOT = Path(getattr(sys, "_MEIPASS", Path(sys.executable).resolve().parent))
    ROOT = Path(sys.executable).resolve().parent
else:
    BUNDLE_ROOT = SOURCE_ROOT
    ROOT = SOURCE_ROOT
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from shared.environment import apply_environment

apply_environment()

HOST = os.environ.get("AI_CAR_BACKEND_HOST", "127.0.0.1")
_default_port = int(os.environ.get("AI_CAR_BACKEND_PORT", "8001"))
_requested_url = os.environ.get("AI_CAR_BACKEND_URL", "").rstrip("/")
_parsed_url = urlsplit(_requested_url) if _requested_url else None
# Exact host matching avoids treating localhost.attacker.example as local.
LOCAL_BACKEND = _parsed_url is None or (
    _parsed_url.scheme == "http"
    and _parsed_url.hostname in {"127.0.0.1", "localhost"}
)
PORT = (
    _parsed_url.port if LOCAL_BACKEND and _parsed_url is not None and _parsed_url.port
    else _default_port
)
BACKEND_URL = _requested_url or f"http://127.0.0.1:{PORT}"
LLM_HOST = os.environ.get("LOCAL_LLM_SERVER_HOST", "127.0.0.1")
LLM_PORT = int(os.environ.get("LOCAL_LLM_SERVER_PORT", "8000"))
LLM_BASE_URL = os.environ.get("LOCAL_LLM_SERVER_URL", f"http://{LLM_HOST}:{LLM_PORT}").rstrip("/").removesuffix("/v1")
if os.environ.get("LOCAL_LLM_SERVER_URL"):
    _llm_target = urlsplit(LLM_BASE_URL)
    if _llm_target.hostname:
        LLM_HOST = _llm_target.hostname
        LLM_PORT = _llm_target.port or (443 if _llm_target.scheme == "https" else 80)
LLM_MODEL = os.environ.get("LOCAL_LLM_SERVER_MODEL", "Qwen3-8B-Q4_K_M.gguf")
HEALTH_URL = f"{BACKEND_URL}/health"
LLM_HEALTH_URL = f"{LLM_BASE_URL}/health"
_STARTUP_TIMEOUT = float(os.environ.get("AI_CAR_BACKEND_STARTUP_TIMEOUT", "60"))
_LLM_STARTUP_TIMEOUT = float(os.environ.get("LOCAL_LLM_SERVER_STARTUP_TIMEOUT_S", "180"))

_backend_process: subprocess.Popen[bytes] | None = None
_llm_process: subprocess.Popen[bytes] | None = None
_backend_log = None
_llm_log = None

def _close_backend_log() -> None:
    global _backend_log
    if _backend_log is not None:
        _backend_log.close()
        _backend_log = None


def _close_llm_log() -> None:
    global _llm_log
    if _llm_log is not None:
        _llm_log.close()
        _llm_log = None


def _is_port_open(host: str, port: int) -> bool:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
        sock.settimeout(0.25)
        return sock.connect_ex((host, port)) == 0


def _json_health(url: str, timeout: float = 1.0) -> bool:
    try:
        with urlopen(url, timeout=timeout) as response:
            return response.status == 200
    except (OSError, URLError):
        return False


def _backend_healthy() -> bool:
    return _json_health(HEALTH_URL)


def _llm_healthy() -> bool:
    return _json_health(LLM_HEALTH_URL)


def _appdata_log(name: str) -> Path:
    appdata = Path(os.environ.get("APPDATA", Path.home()))
    log_dir = appdata / "AI-Car-Scanner"
    log_dir.mkdir(parents=True, exist_ok=True)
    return log_dir / name


def _resolve_llama_server() -> Path | None:
    configured = os.environ.get("LOCAL_LLM_SERVER_PATH")
    candidates: list[Path] = []
    if configured:
        candidates.append(Path(configured).expanduser())
    for directory in (ROOT, BUNDLE_ROOT):
        candidates.extend([
            directory / "llama-server.exe",
            directory / "llama-server",
            directory / "tools" / "llama.cpp" / "llama-server.exe",
            directory / "tools" / "llama.cpp" / "llama-server",
            directory / "bin" / "llama-server.exe",
            directory / "bin" / "llama-server",
        ])
    which = shutil.which("llama-server.exe") or shutil.which("llama-server")
    if which:
        candidates.append(Path(which))
    for candidate in candidates:
        try:
            if candidate.is_file():
                return candidate.resolve()
        except OSError:
            continue
    return None


def _resolve_model_path() -> Path:
    configured = os.environ.get("LOCAL_LLM_MODEL_PATH")
    if configured:
        return Path(configured).expanduser().resolve()
    preferred = (ROOT / "models" / (os.environ.get("LOCAL_LLM_SERVER_MODEL") or LLM_MODEL)).resolve()
    if preferred.is_file() or os.environ.get("LOCAL_LLM_SERVER_MODEL"):
        return preferred
    # A single installed GGUF is unambiguous; never guess among several models
    # or override an explicitly requested filename/path.
    installed = sorted((ROOT / "models").glob("*.gguf"))
    return installed[0].resolve() if len(installed) == 1 else preferred


def start_llama_server(wait_for_ready: bool = True) -> subprocess.Popen[bytes] | None:
    """Start llama-server; optionally return immediately while the model loads."""
    global _llm_process, _llm_log

    if os.environ.get("AI_CAR_DISABLE_LLM_AUTOSTART", "0").lower() in {"1", "true", "yes"}:
        return None
    if _llm_healthy():
        return None
    target = urlsplit(LLM_BASE_URL)
    if target.scheme != "http" or target.hostname not in {"127.0.0.1", "localhost", "::1"}:
        print("[AI-Car-Scanner] LLM endpoint is externally managed; local autostart skipped.", file=sys.stderr)
        return None

    model = _resolve_model_path()
    if not model.is_file():
        print(f"[AI-Car-Scanner] Local LLM model not found: {model}", file=sys.stderr)
        return None

    server = _resolve_llama_server()
    if server is None:
        print("[AI-Car-Scanner] llama-server.exe not found; continuing with deterministic AI fallback.", file=sys.stderr)
        return None

    if _is_port_open(LLM_HOST, LLM_PORT):
        print(
            f"[AI-Car-Scanner] LLM port {LLM_PORT} is busy but {LLM_HEALTH_URL} is not healthy; "
            "local LLM autostart skipped.",
            file=sys.stderr,
        )
        return None

    log_path = _appdata_log("llama-server.log")
    _llm_log = log_path.open("ab")
    env = os.environ.copy()
    env["LOCAL_LLM_SERVER_URL"] = LLM_BASE_URL
    env["LOCAL_LLM_SERVER_MODEL"] = LLM_MODEL

    context = max(2048, int(os.environ.get("LOCAL_LLM_SERVER_CONTEXT", "8192")))
    threads = max(1, int(os.environ.get("LOCAL_LLM_SERVER_THREADS", "8")))
    command = [
        str(server),
        "-m", str(model),
        "-c", str(context),
        "-t", str(threads),
        "--host", LLM_HOST,
        "--port", str(LLM_PORT),
    ]
    if os.environ.get("LOCAL_LLM_SERVER_NO_WEBUI", "0").lower() in {"1", "true", "yes"}:
        command.append("--no-webui")

    creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0) if sys.platform == "win32" else 0
    try:
        _llm_process = subprocess.Popen(
            command,
            cwd=str(ROOT),
            env=env,
            stdout=_llm_log,
            stderr=subprocess.STDOUT,
            creationflags=creationflags,
        )
    except OSError as exc:
        _llm_log.close()
        _llm_log = None
        print(f"[AI-Car-Scanner] Could not start llama-server.exe: {exc}", file=sys.stderr)
        return None

    if not wait_for_ready:
        # Model loading can take minutes; keep the desktop UI responsive while it loads.
        return _llm_process

    deadline = time.monotonic() + _LLM_STARTUP_TIMEOUT
    while time.monotonic() < deadline:
        if _llm_process.poll() is not None:
            returncode = _llm_process.returncode
            _llm_process = None
            _close_llm_log()
            print(
                f"[AI-Car-Scanner] llama-server exited with code {returncode}. Log: {log_path}",
                file=sys.stderr,
            )
            return None
        if _llm_healthy():
            return _llm_process
        time.sleep(0.25)

    print(
        f"[AI-Car-Scanner] llama-server did not become healthy within {_LLM_STARTUP_TIMEOUT:g}s. Log: {log_path}",
        file=sys.stderr,
    )
    process = _llm_process
    try:
        if process is not None:
            process.terminate()
            process.wait(timeout=2)
    except Exception:
        try:
            if process is not None:
                process.kill()
                process.wait(timeout=2)
        except Exception:
            pass
    _llm_process = None
    _close_llm_log()
    return None


def stop_llama_server() -> None:
    global _llm_process, _llm_log
    process = _llm_process
    _llm_process = None
    if process is not None and process.poll() is None:
        try:
            process.terminate()
            process.wait(timeout=5)
        except subprocess.TimeoutExpired:
            process.kill()
            process.wait(timeout=2)
    if _llm_log is not None:
        _llm_log.close()
        _llm_log = None


def _log_path() -> Path:
    """Backward-compatible backend log path helper used by tests/tools."""
    return _appdata_log("backend.log")


def _backend_log_path() -> Path:
    return _log_path()


def start_backend(*, cancel_event: threading.Event | None = None) -> subprocess.Popen[bytes] | None:
    global _backend_process, _backend_log
    if cancel_event is not None and cancel_event.is_set():
        return None
    if not LOCAL_BACKEND:
        # The default is the shared cloud API. Do not spawn an unused local API
        # process when Desktop is configured for Render or another remote host.
        return None
    if _backend_healthy():
        return None
    if _backend_process is not None:
        if _backend_process.poll() is None:
            # Do not start two instances while our previous child is starting.
            raise RuntimeError("Desktop-owned FastAPI child is running but not healthy yet.")
        _backend_process = None
        _close_backend_log()
    if _is_port_open(HOST, PORT):
        raise RuntimeError(
            f"Port {PORT} is already in use, but {HEALTH_URL} is not healthy. "
            "Stop the process using this port or set AI_CAR_BACKEND_PORT to another port."
        )

    backend_log_path = _backend_log_path()
    _backend_log = backend_log_path.open("ab")
    env = os.environ.copy()
    env["PYTHONUNBUFFERED"] = "1"
    env.pop("AI_CAR_DESKTOP_LOCAL_DB", None)
    force_local = env.get("AI_CAR_USE_LOCAL_DATABASE", "").lower() in {"1", "true", "yes"}
    if force_local or not env.get("DATABASE_URL", "").strip():
        database_file = backend_log_path.parent / "diagnostic.sqlite"
        env["DATABASE_URL"] = "sqlite:///" + database_file.resolve().as_posix()
        env["AI_CAR_DESKTOP_LOCAL_DB"] = "1"
    _backend_log.write((
        f"\n[launcher] {datetime.now(timezone.utc).isoformat()} root={ROOT}; "
        f"python={sys.executable}; storage="
        f"{'local SQLite' if env.get('AI_CAR_DESKTOP_LOCAL_DB') == '1' else 'configured DATABASE_URL'}\n"
    ).encode("utf-8"))
    _backend_log.flush()
    storage_hint = (
        " Check configured DATABASE_URL and start its database service; "
        "or explicitly select Desktop SQLite with AI_CAR_USE_LOCAL_DATABASE=1."
        if env.get("AI_CAR_DESKTOP_LOCAL_DB") != "1" else
        " Check local SQLite permissions and the active Python dependencies."
    )
    backend_path = BUNDLE_ROOT / "backend" if getattr(sys, "frozen", False) else ROOT / "backend"
    if backend_path.exists():
        existing = env.get("PYTHONPATH")
        env["PYTHONPATH"] = str(backend_path) if not existing else str(backend_path) + os.pathsep + existing
    env["AI_CAR_BACKEND_HOST"] = HOST
    env["AI_CAR_BACKEND_PORT"] = str(PORT)
    env.setdefault("DIAGNOSTIC_LLM_PROVIDER", "llama-server")
    env.setdefault("LOCAL_LLM_SERVER_URL", LLM_BASE_URL)
    env.setdefault("LOCAL_LLM_SERVER_MODEL", LLM_MODEL)

    if getattr(sys, "frozen", False):
        backend_exe = ROOT / "backend_service.exe"
        if not backend_exe.exists():
            backend_exe = BUNDLE_ROOT / "backend_service.exe"
        if not backend_exe.exists():
            _backend_log.close(); _backend_log = None
            raise RuntimeError("Bundled backend_service.exe was not found next to AICarScanner.exe.")
        command = [str(backend_exe)]
    else:
        command = [sys.executable, "-m", "apps.desktop.backend_worker"]

    creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0) if sys.platform == "win32" else 0
    try:
        _backend_process = subprocess.Popen(
            command,
            cwd=str(ROOT),
            env=env,
            stdout=_backend_log,
            stderr=subprocess.STDOUT,
            creationflags=creationflags,
        )
    except FileNotFoundError as exc:
        _backend_log.close(); _backend_log = None
        raise RuntimeError(
            "Could not start backend: uvicorn is not installed in the active Python environment."
        ) from exc
    except OSError as exc:
        _backend_log.close(); _backend_log = None
        raise RuntimeError(f"Could not start backend process: {exc}") from exc

    deadline = time.monotonic() + _STARTUP_TIMEOUT
    while time.monotonic() < deadline:
        if cancel_event is not None and cancel_event.is_set():
            break
        if _backend_process.poll() is not None:
            returncode = _backend_process.returncode
            _backend_process = None
            _close_backend_log()
            raise RuntimeError(
                f"Backend exited during startup with code {returncode}. Log: {backend_log_path}{storage_hint}"
            )
        if _backend_healthy():
            return _backend_process
        time.sleep(0.25)

    process = _backend_process
    try:
        if process is not None:
            process.terminate()
            process.wait(timeout=2)
    except Exception:
        try:
            if process is not None:
                process.kill()
                process.wait(timeout=2)
        except Exception:
            pass
    _backend_process = None
    _close_backend_log()
    if cancel_event is not None and cancel_event.is_set():
        raise RuntimeError("FastAPI startup canceled during Desktop shutdown.")
    raise RuntimeError(f"Backend did not become healthy within {_STARTUP_TIMEOUT:g}s. Log: {backend_log_path}{storage_hint}")


def stop_backend() -> None:
    global _backend_process, _backend_log
    process = _backend_process
    _backend_process = None
    try:
        if process is not None and process.poll() is None:
            if sys.platform == "win32":
                try:
                    # Stop descendants too: a Windows child can retain the
                    # inherited log handle after its parent has exited.
                    subprocess.run(
                        ["taskkill", "/PID", str(process.pid), "/T", "/F"],
                        capture_output=True, check=True, timeout=5,
                        creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                    )
                    process.wait(timeout=5)
                    return
                except (OSError, subprocess.SubprocessError):
                    pass
            try:
                process.terminate(); process.wait(timeout=5)
            except subprocess.TimeoutExpired:
                process.kill(); process.wait(timeout=2)
    finally:
        _close_backend_log()


def run(argv: list[str] | None = None) -> None:
    global BACKEND_URL, HEALTH_URL, LOCAL_BACKEND
    parser = argparse.ArgumentParser(description="AI Car Scanner Desktop")
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--with-backend", action="store_true", help="Start a local backend with persistent SQLite storage before opening Desktop")
    mode.add_argument("--no-backend", action="store_true", help="Connect to an existing backend without starting local services")
    parser.add_argument("--local-ai", action="store_true",
                        help="Use and autostart local llama-server with a GGUF in models, overriding an external AI provider for this launch")
    args = parser.parse_args(argv or [])
    if args.local_ai:
        if args.no_backend:
            parser.error("--local-ai needs a launcher-managed local backend; remove --no-backend")
        if not LOCAL_BACKEND and not args.with_backend:
            parser.error("--local-ai requires --with-backend when a remote backend is configured")
        target = urlsplit(LLM_BASE_URL)
        if target.scheme != "http" or target.hostname not in {"127.0.0.1", "localhost", "::1"}:
            parser.error("--local-ai needs a local HTTP LOCAL_LLM_SERVER_URL, for example http://127.0.0.1:8000")
        os.environ["DIAGNOSTIC_LLM_PROVIDER"] = "llama-server"
        os.environ["AI_CAR_DISABLE_LLM_AUTOSTART"] = "0"
        os.environ["LOCAL_LLM_SERVER_URL"] = LLM_BASE_URL
        selected_model = _resolve_model_path()
        if selected_model.is_file():
            os.environ["LOCAL_LLM_SERVER_MODEL"] = selected_model.name
        print(f"[AI-Car-Scanner] Local AI selected: {selected_model}; endpoint={LLM_BASE_URL}")
    if args.with_backend:
        BACKEND_URL = f"http://127.0.0.1:{PORT}"
        HEALTH_URL = f"{BACKEND_URL}/health"
        LOCAL_BACKEND = True
        os.environ["AI_CAR_BACKEND_URL"] = BACKEND_URL
        os.environ["AI_CAR_USE_LOCAL_DATABASE"] = "1"
    try:
        from apps.desktop.ui import run as run_ui
    except ImportError:
        from apps.desktop.ui import run as run_ui

    backend_error: str | None = None
    backend_recovery = None
    initial_failure_recovered = False
    llm_backend = os.environ.get("DIAGNOSTIC_LLM_PROVIDER", "llama-server").lower()
    # OpenAI-compatible runtimes (LM Studio, Jan) manage their own model
    # lifecycle. Never spawn a competing llama-server on port 8000 for them.
    if LOCAL_BACKEND and not args.no_backend and llm_backend in {
        "llama-server", "llama_server", "llamaserver", "local"
    }:
        try:
            start_llama_server(wait_for_ready=False)
        except Exception as exc:
            print(f"[AI-Car-Scanner] Local LLM startup failed: {exc}", file=sys.stderr)

    if not args.no_backend:
        try:
            start_backend()
        except Exception as exc:
            backend_error = str(exc)
            print(f"[AI-Car-Scanner] Backend startup failed: {backend_error}", file=sys.stderr)

    if (
        LOCAL_BACKEND
        and not args.no_backend
        and os.environ.get("AI_CAR_BACKEND_AUTO_RECOVER", "1").lower() in {"1", "true", "yes"}
    ):
        from apps.desktop.backend_recovery import BackendRecoverySupervisor
        backend_recovery = BackendRecoverySupervisor(
            process=lambda: _backend_process,
            restart=lambda: start_backend(cancel_event=backend_recovery.stop_event),
            healthy=_backend_healthy,
            allow_initial_retry=backend_error is not None,
        )
        backend_recovery.start()

    def trace_shutdown(stage: str) -> None:
        path = os.environ.get("AI_CAR_SHUTDOWN_TRACE_PATH")
        if path:
            try:
                with open(path, "a", encoding="utf-8") as stream:
                    stream.write("main: " + stage + "\n")
            except OSError:
                pass

    try:
        trace_shutdown("entering ui.run")
        run_ui()
        trace_shutdown("ui.run returned")
        if backend_error and backend_recovery is not None:
            initial_failure_recovered = _backend_healthy()
    finally:
        trace_shutdown("starting backend/LLM cleanup")
        if backend_recovery is not None:
            backend_recovery.stop(join_timeout=max(8.0, _STARTUP_TIMEOUT + 3.0))
        stop_backend()
        stop_llama_server()
        trace_shutdown("backend/LLM cleanup complete")

    if backend_error and not initial_failure_recovered:
        raise SystemExit(1)


if __name__ == "__main__":
    run(sys.argv[1:])

from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum


class DeviceConnectionError(RuntimeError):
    pass


class DeviceStatus(str, Enum):
    DISCONNECTED = "disconnected"
    CONNECTED = "connected"


@dataclass
class DeviceCapabilities:
    obd: bool = True
    can: bool = True
    uds: bool = True


@dataclass
class DeviceDescriptor:
    device_id: str
    manufacturer: str = "AI-CAR-SCANER"
    model: str = "Simulator"
    firmware_version: str | None = None
    protocol: str = "OBD/CAN"
    connection_type: str = "simulator"
    capabilities: DeviceCapabilities = field(default_factory=DeviceCapabilities)
    status: DeviceStatus = DeviceStatus.DISCONNECTED
    metadata: dict = field(default_factory=dict)


class VCIConnectionManager:
    """Backend device facade: explicit simulator plus real server-local transports."""

    def __init__(self):
        self.devices: dict[str, DeviceDescriptor] = {}
        self.connections: dict[str, dict] = {}
        self._physical_manager = None

    def _physical(self):
        if self._physical_manager is None:
            from vehicle.devices.connection import VCIConnectionManager as PhysicalManager
            self._physical_manager = PhysicalManager()
        return self._physical_manager

    def _publish(self, descriptor):
        self.devices[descriptor.device_id] = descriptor
        return descriptor

    async def _physical_call(self, method, *args):
        try:
            result = await getattr(self._physical(), method)(*args)
            return result
        except Exception as error:
            raise DeviceConnectionError(str(error)) from error

    def add_simulator(self) -> DeviceDescriptor:
        device = DeviceDescriptor(
            device_id="simulator-vci",
            status=DeviceStatus.DISCONNECTED,
            metadata={"simulated": True},
        )
        self.devices[device.device_id] = device
        self.connections.pop(device.device_id, None)
        return device

    async def scan(self, transport: str, timeout: float = 3.0):
        if transport.lower() == "simulator":
            return [self.add_simulator()]
        return [self._publish(d) for d in await self._physical_call("scan", transport, timeout)]

    async def probe_wifi(self, host: str, port: int, timeout: float):
        return self._publish(await self._physical_call("probe_wifi", host, port, timeout))

    async def connect(self, device_id: str, config: dict | None = None):
        if device_id != "simulator-vci":
            return self._publish(await self._physical_call("connect", device_id, config))
        device = self._get(device_id)
        device.status = DeviceStatus.CONNECTED
        self.connections[device_id] = dict(config or {})
        return device

    async def reconnect(self, device_id: str):
        if device_id != "simulator-vci":
            return self._publish(await self._physical_call("reconnect", device_id))
        return await self.connect(device_id, self.connections.get(device_id, {}))

    async def disconnect(self, device_id: str):
        if device_id != "simulator-vci":
            return self._publish(await self._physical_call("disconnect", device_id))
        device = self._get(device_id)
        device.status = DeviceStatus.DISCONNECTED
        return device

    def status(self, device_id: str) -> DeviceDescriptor:
        if device_id != "simulator-vci":
            try:
                return self._physical().status(device_id)
            except Exception as error:
                raise DeviceConnectionError(str(error)) from error
        return self._get(device_id)

    async def read_vin(self, device_id: str):
        if device_id != "simulator-vci":
            return await self._physical_call("read_vin", device_id)
        self._require_connected(device_id)
        return "WDD2110801A123456"

    async def read_dtcs(self, device_id: str):
        if device_id != "simulator-vci":
            return await self._physical_call("read_dtcs", device_id)
        self._require_connected(device_id)
        return ["P0102"]

    async def read_live_data(self, device_id: str):
        if device_id != "simulator-vci":
            return await self._physical_call("read_live_data", device_id)
        self._require_connected(device_id)
        return {
            "rpm": 1696.0,
            "coolant_temp_c": 50.0,
            "vehicle_speed_kmh": 40.0,
            "throttle_pct": 52.0,
        }

    def _get(self, device_id: str) -> DeviceDescriptor:
        device = self.devices.get(device_id)
        if device is None:
            raise DeviceConnectionError(f"Device not found: {device_id}")
        return device

    def _require_connected(self, device_id: str) -> DeviceDescriptor:
        device = self._get(device_id)
        if device.status != DeviceStatus.CONNECTED:
            raise DeviceConnectionError(f"Device is not connected: {device_id}")
        return device

    async def shutdown(self):
        if self._physical_manager is not None:
            await self._physical_manager.shutdown()


def _build_vci_manager():
    """Use real USB/BLE/Wi-Fi adapters ONLY with explicit local opt-in.

    Cloud backends have no access to the user's mobile BLE adapter and must
    never probe local devices or expose LAN probing by default.
    """
    import os
    enabled = os.getenv("AI_CAR_ENABLE_PHYSICAL_VCI", "").strip().lower() in {"1", "true", "yes"}
    host = os.getenv("AI_CAR_BACKEND_HOST", "127.0.0.1").strip().lower()
    if not enabled or host not in {"127.0.0.1", "localhost", "::1"}:
        return VCIConnectionManager()
    from vehicle.devices.connection import VCIConnectionManager as PhysicalManager

    class LocalVciManager(PhysicalManager):
        async def scan(self, transport: str, timeout: float = 3.0):
            if transport.strip().lower() == "simulator":
                return [self.add_simulator()]
            return await super().scan(transport, timeout)

    return LocalVciManager()


vci_manager = _build_vci_manager()
if type(vci_manager).__name__ == "LocalVciManager":
    # Keep the public API's error mapping (409/502) consistent across real and
    # simulated manager implementations.
    from vehicle.devices.connection import DeviceConnectionError as DeviceConnectionError

