class ActiveNetworkDiscoveryService:
    def __init__(self):
        self._engine = ActiveEcuDiscoveryEngine()
        self._results: dict[str, list[ActiveProbeResult]] = defaultdict(list)

    async def probe_candidates(self, session_id: UUID, passive: VehicleNetworkDiscoveryResult,
                               buses: dict, topology: VehicleNetworkTopology | None = None,
                               candidate_ids: list[str] | None = None,
                               policy: ActiveProbePolicy | None = None) -> list[ActiveProbeResult]:
        engine = ActiveEcuDiscoveryEngine(policy or self._engine.policy)
        allowed = set(candidate_ids) if candidate_ids else None
        targets: list[ActiveProbeTarget] = []
        for candidate in passive.ecu_candidates:
            if allowed is not None and candidate.candidate_id not in allowed: continue
            if candidate.request_id is None or candidate.response_id is None: continue
            access_bus = candidate.bus
            gateway_id = None
            if topology:
                for route in topology.routes:
                    try: ecu = topology.ecu(route.target_ecu_id)
                    except KeyError: continue
                    if ecu.request_id == candidate.request_id and ecu.response_id == candidate.response_id and ecu.bus == candidate.bus:
                        access_bus, gateway_id = route.source_bus, route.gateway_id
                        break
            if access_bus not in buses: continue
            targets.append(ActiveProbeTarget(candidate.candidate_id, access_bus, candidate.request_id, candidate.response_id, gateway_id))
        results = await engine.probe_many(targets, buses)
        self._results[str(session_id)] = results
        return results

    def results(self, session_id: UUID) -> list[ActiveProbeResult]:
        return list(self._results.get(str(session_id), ()))

    def correlate(self, session_id: UUID, passive: VehicleNetworkDiscoveryResult, topology: VehicleNetworkTopology | None = None) -> dict:
        results = self.results(session_id)
        by_id = {r.candidate_id: r for r in results}
        candidates = []
        for c in passive.ecu_candidates:
            result = by_id.get(c.candidate_id)
            if result is None:
                candidates.append({'candidate_id': c.candidate_id, 'status': 'PASSIVE_ONLY', 'classification': c.classification, 'confidence': c.confidence})
                continue
            if result.classification == 'CONFIRMED_UDS_ECU':
                status = 'CONFIRMED'
            elif result.classification == 'ACTIVE_UDS_RESPONDER':
                status = 'ACTIVE_RESPONDER'
            else:
                status = 'NO_RESPONSE'
            item = {'candidate_id': c.candidate_id, 'status': status, 'passive': c.to_dict(), 'active': result.to_dict()}
            if result.gateway_id: item['gateway_correlation'] = {'gateway_id': result.gateway_id, 'access_bus': result.bus, 'target_bus': c.bus, 'status': 'CORRELATED'}
            candidates.append(item)
        passive_ids = {c.candidate_id for c in passive.ecu_candidates}
        unmatched_active = [r.to_dict() for r in results if r.candidate_id not in passive_ids]
        return {'candidates': candidates, 'active_probe_count': len(results), 'confirmed_count': sum(x['status'] == 'CONFIRMED' for x in candidates), 'gateway_correlations': sum(1 for x in candidates if x.get('gateway_correlation')), 'unmatched_active': unmatched_active}

from __future__ import annotations

from collections import defaultdict
from uuid import UUID

from vehicle.can.models import CanFrame
from vehicle.network.discovery import CanIdObservation, VehicleNetworkDiscoveryEngine


class VehicleNetworkDiscoveryService:
    """Session-scoped passive network discovery with replayable observations."""

    def __init__(self) -> None:
        self._observations: dict[str, list[CanIdObservation]] = defaultdict(list)
        self._engine = VehicleNetworkDiscoveryEngine()

    def ingest_frame(self, session_id: UUID, *, bus: str, frame: CanFrame) -> None:
        self._observations[str(session_id)].append(
            CanIdObservation(
                bus=bus,
                arbitration_id=frame.arbitration_id,
                timestamp_ns=frame.timestamp_ns or 0,
                dlc=frame.dlc,
                data_hex=frame.data.hex().upper(),
                extended=frame.is_extended,
                fd=frame.is_fd,
            )
        )

    def ingest_frames(self, session_id: UUID, *, bus: str, frames: list[CanFrame]) -> int:
        for frame in frames:
            self.ingest_frame(session_id, bus=bus, frame=frame)
        return len(frames)

    def analyze(self, session_id: UUID):
        return self._engine.analyze_observations(self._observations.get(str(session_id), []))

    def reset(self, session_id: UUID) -> None:
        self._observations.pop(str(session_id), None)

    def observation_count(self, session_id: UUID) -> int:
        return len(self._observations.get(str(session_id), []))

"""Generation/engine references shared by every native client.

A reference is not VIN fitment, engine-year availability or observed protocol.
"""
import json
from pathlib import Path
import sys


def project_root() -> Path:
    return Path(getattr(sys, "_MEIPASS", Path(__file__).resolve().parents[2]))


def reference_vehicles() -> list[dict]:
    root = project_root()
    data = json.loads((root / "data/vehicle_reference.json").read_text(encoding="utf-8"))
    manifest = root / "data/vehicle_images/manifest.json"
    images = json.loads(manifest.read_text(encoding="utf-8")) if manifest.is_file() else {}
    result = []
    for row in data["vehicles"]:
        row = dict(row)
        image = dict(images.get(row["id"], row["image"]))
        image["url"] = f"/api/v1/vehicle-reference/{row['id']}/image" if image.get("path") else None
        row["image"] = image
        result.append(row)
    return result


def selector_entries(**filters) -> list[dict]:
    rows = []
    for car in reference_vehicles():
        for engine in car["engines"]:
            for year in range(car["year_start"], car["year_end"]+1):
                row = {key: car[key] for key in ("make", "model", "chassis")}
                row.update(year=year, engine=engine["name"], engine_type=engine["type"], ecu=None,
                           fuel=[engine["type"]], source=car["source_url"], scope="generation-reference-not-vin-fitment",
                           image_url=car["image"]["url"], vehicle_reference_id=car["id"],
                           image_attribution={k: car["image"][k] for k in ("creator", "license", "license_url", "source_page") if car["image"].get(k)} or None,
                           fitment_verified=False, protocol_policy="auto_detect_on_vehicle")
                if all(value is None or row.get(key) == value for key, value in filters.items()):
                    rows.append(row)
    return rows


def compatibility(make: str, model: str, year: int, engine: str | None, market: str | None) -> dict:
    matches = [c for c in reference_vehicles() if c["make"].casefold() == make.casefold()
               and c["model"].casefold() == model.casefold() and c["year_start"] <= year <= c["year_end"]
               and (not engine or any(e["name"].casefold() == engine.casefold() for e in c["engines"]))]
    # Regulation provides candidates, never a verified ECU-specific mapping.
    can_required = market == "US" and year >= 2008
    candidates = ["can-11-500", "can-29-500", "can-11-250", "can-29-250"]
    if not can_required:
        candidates += ["iso9141-2", "kwp-5baud", "kwp-fast", "j1850-pwm", "j1850-vpw"]
    return {"references": matches, "protocol_id": "auto", "candidates": candidates,
            "observed_protocol": None, "status": "requires_adapter_detection", "market": market,
            "basis": "US model-year 2008+ OBD CAN requirement" if can_required else "generic OBD-II adapter candidates; market applicability unverified",
            "confirmed_fitment": False, "all_vehicles_supported": False,
            "next_steps": ["Initialize adapter", "Read 0100 supported PID mask", "Read ATDPN", "Read VIN and ECU identification"]}

"""Shared Mode 01 scaling and native byte-transport bridge contract."""
from dataclasses import dataclass

from vehicle.obd.protocols.elm327 import ELM327Protocol, OBDProtocolError
from obd.protocols import initialization, detected_protocol


@dataclass(frozen=True)
class Pid:
    command: str
    key: str
    length: int
    unit: str
    offset: float = 0
    scale: float = 1


PIDS = (
    Pid("010C", "rpm", 2, "rpm", scale=0.25),
    Pid("010D", "speed_kmh", 1, "km/h"),
    Pid("0105", "coolant_c", 1, "°C", offset=-40),
    Pid("0104", "engine_load_percent", 1, "%", scale=100/255),
    Pid("010F", "intake_air_c", 1, "°C", offset=-40),
    Pid("0110", "maf_gps", 2, "g/s", scale=0.01),
    Pid("010B", "map_kpa", 1, "kPa"),
    Pid("0111", "throttle_percent", 1, "%", scale=100/255),
    Pid("0106", "short_fuel_trim_percent", 1, "%", offset=-100, scale=100/128),
    Pid("0107", "long_fuel_trim_percent", 1, "%", offset=-100, scale=100/128),
)


def polling_plan(protocol_id="auto") -> dict:
    return {"schema_version": 1, "protocol_id": protocol_id,
            "initialization": initialization(protocol_id) + ["0100"],
            "initialization_timeout_ms": 35000,
            "discovery": ["0100", "ATDPN"],
            "commands": ["0100", "ATDPN"] + [p.command for p in PIDS],
            "read_only": True, "requires_prompt_terminated_responses": True}


def supported_polling_plan(responses: dict[str, str]) -> dict:
    """Select implemented live PIDs from observed Mode 01 PID 00 bitmaps.

    All current live channels are in the first page (01..20). Combine complete
    responses from multiple ECUs; never infer support from a model or a value.
    """
    frames = {key.upper().replace(" ", ""): value for key, value in responses.items()}
    payloads = ELM327Protocol.payloads("0100", frames.get("0100", "NO DATA"))
    masks = [int.from_bytes(p[2:], "big") for p in payloads if p[:2] == b"\x41\x00" and len(p) == 6]
    if not masks:
        raise OBDProtocolError("A complete Mode 01 PID 00 capability reply is required")
    mask = 0
    for value in masks:
        mask |= value
    supported = [pid for pid in range(1, 33) if mask & (1 << (32-pid))]
    commands = [pid.command for pid in PIDS if int(pid.command[2:], 16) in supported]
    return {"schema_version": 2, "initialization": [], "discovery": [],
            "commands": commands, "supported_pids": supported,
            "unsupported_commands": [pid.command for pid in PIDS if pid.command not in commands],
            "capabilities_observed": True, "read_only": True,
            "requires_prompt_terminated_responses": True}


def decode_snapshot(responses: dict[str, str]) -> dict:
    normalized = {key.upper().replace(" ", ""): value for key, value in responses.items()}
    values, errors = {}, {}
    for pid in PIDS:
        try:
            data = ELM327Protocol.parse_pid(int(pid.command[2:], 16), normalized.get(pid.command, "NO DATA"))
            if len(data) != pid.length:
                raise OBDProtocolError(f"Expected {pid.length} bytes; received {len(data)}")
            values[pid.key] = int.from_bytes(data, "big") * pid.scale + pid.offset
        except (ValueError, OBDProtocolError) as error:
            values[pid.key] = None
            errors[pid.command] = str(error)
    protocol = None
    if "ATDPN" in normalized:
        try:
            protocol = detected_protocol(normalized["ATDPN"])
        except ValueError as error:
            errors["ATDPN"] = str(error)
    return {"protocol": protocol, "values": values, "units": {p.key: p.unit for p in PIDS}, "errors": errors,
            "source": "native_transport_bridge", "hardware_verified": False}

"""Passive SAE J1708 checksum and J1587 parameter framing decoder.

The bridge supplies one complete packet, including its checksum. Electrical
bus arbitration/timing and OEM parameter scaling require an appropriate driver.
"""


def decode_packet(packet: bytes) -> dict:
    if not 4 <= len(packet) <= 21:
        raise ValueError('J1708 packets must contain 4..21 bytes including checksum')
    if sum(packet) & 255:
        raise ValueError('J1708 checksum mismatch')
    if packet[0] < 128:
        raise ValueError('Expected a J1587 application MID (128..255)')
    cursor, end, parameters = 1, len(packet)-1, []
    while cursor < end:
        pid = packet[cursor]
        cursor += 1
        extended = pid == 255
        if extended:
            if cursor >= end:
                raise ValueError('Missing extended PID')
            pid = packet[cursor]
            cursor += 1
        if pid >= 254:
            raise ValueError('Reserved/data-link escape PID needs a dedicated decoder')
        size = 1 if pid < 128 else 2 if pid < 192 else None
        if size is None:
            if cursor >= end:
                raise ValueError('Missing variable parameter length')
            size = packet[cursor]
            cursor += 1
        if size < 1 or cursor+size > end:
            raise ValueError('Truncated or empty J1587 parameter')
        parameters.append({'pid': pid+256 if extended else pid,
                           'raw_hex': packet[cursor:cursor+size].hex().upper()})
        cursor += size
    return {'mid': packet[0], 'parameters': parameters, 'checksum_valid': True,
            'source': 'native_j1708_capture', 'scope': 'Parameter framing only; no OEM scaling',
            'hardware_verified': False}

"""Passive J1939-73 DM1/DM2 decoding. No emissions Mode 01 PID assumptions."""


def decode_diagnostic_frame(arbitration_id: int, payload: bytes) -> dict:
    if not 0 <= arbitration_id <= 0x1FFFFFFF or len(payload) not in (6, 8):
        raise ValueError('Expected a 29-bit CAN identifier and a 6- or 8-byte single CAN frame')
    pf, ps = (arbitration_id >> 16) & 255, (arbitration_id >> 8) & 255
    pgn = (arbitration_id >> 8) & 0x3FFFF
    if pf < 240:
        pgn &= 0x3FF00
    if pgn not in (65226, 65227):
        raise ValueError('Only complete single-frame DM1/DM2 are supported; TP requires reassembly')
    records = []
    body = payload[2:]
    if len(body) not in (0, 4, 6) or (len(body) == 6 and body[4:] != b'\xFF\xFF'):
        raise ValueError('Truncated or invalid DM diagnostic record/padding')
    if len(body) >= 4 and body[:4] not in (b'\x00'*4, b'\xFF'*4):
        a, b, c, d = body[:4]
        cm = bool(d & 128)
        records.append({'spn': None if cm else a | (b << 8) | ((c & 224) << 11),
                        'fmi': c & 31, 'occurrence_count': d & 127,
                        'conversion_method': int(cm), 'raw': body[:4].hex().upper(),
                        'status': 'legacy_conversion_requires_profile' if cm else 'decoded'})
    return {'pgn': pgn, 'source_address': arbitration_id & 255,
            'destination_address': ps if pf < 240 else None,
            'kind': 'DM1' if pgn == 65226 else 'DM2',
            'lamp_status': payload[0], 'lamp_flash': payload[1], 'dtcs': records,
            'source': 'native_can_capture', 'hardware_verified': False}


def decode_bam_capture(frames: list[tuple[int, bytes]]) -> dict:
    """Reassemble one complete globally broadcast TP.BAM DM1/DM2 capture.

    Captures must already be time ordered. RTS/CTS and overlapping unrelated
    sessions are intentionally rejected instead of guessing packet ownership.
    """
    if not frames:
        raise ValueError('A complete BAM capture is required')
    identifier, announcement = frames[0]
    if not 0 <= identifier <= 0x1FFFFFFF or (identifier >> 8) & 0x3FFFF != 0xECFF:
        raise ValueError('First frame must be a global TP.CM BAM announcement')
    if len(announcement) != 8 or announcement[0] != 32 or announcement[4] != 255:
        raise ValueError('Invalid BAM announcement')
    size = int.from_bytes(announcement[1:3], 'little')
    count = announcement[3]
    pgn = int.from_bytes(announcement[5:8], 'little')
    if pgn not in (65226, 65227) or not 9 <= size <= 1785 or count != (size+6)//7 or len(frames) != count+1:
        raise ValueError('Incomplete/unsupported BAM diagnostic message')
    source = identifier & 255
    message = bytearray()
    for sequence, (identifier, payload) in enumerate(frames[1:], 1):
        if not 0 <= identifier <= 0x1FFFFFFF or (identifier >> 8) & 0x3FFFF != 0xEBFF or identifier & 255 != source:
            raise ValueError('BAM data source/destination mismatch')
        if len(payload) != 8 or payload[0] != sequence:
            raise ValueError('BAM data packet missing or out of sequence')
        message.extend(payload[1:])
    if any(value != 255 for value in message[size:]):
        raise ValueError('Invalid BAM trailing padding')
    message = message[:size]
    if (len(message)-2) % 4:
        raise ValueError('Truncated BAM diagnostic record')
    dtcs = []
    for offset in range(2, len(message), 4):
        decoded = decode_diagnostic_frame((pgn << 8) | source, bytes(message[:2]+message[offset:offset+4]))
        dtcs.extend(decoded['dtcs'])
    return {'pgn': pgn, 'source_address': source, 'kind': 'DM1' if pgn == 65226 else 'DM2',
            'lamp_status': message[0], 'lamp_flash': message[1], 'dtcs': dtcs,
            'transport': 'TP.BAM', 'source': 'native_can_capture', 'hardware_verified': False}

