from __future__ import annotations
from dataclasses import dataclass

@dataclass(frozen=True)
class CanFrame:
    arbitration_id: int
    data: bytes
    timestamp_ns: int | None = None
    is_extended: bool = False
    is_fd: bool = False

    def __post_init__(self):
        if not 0 <= self.arbitration_id <= (0x1FFFFFFF if self.is_extended else 0x7FF):
            raise ValueError("invalid CAN arbitration id")
        max_len = 64 if self.is_fd else 8
        if len(self.data) > max_len:
            raise ValueError(f"CAN payload exceeds {max_len} bytes")

    @property
    def dlc(self) -> int:
        return len(self.data)

"""Single backend registry for the project global seed and curated engine fitments.

The NHTSA-derived make/model year ranges are broad, engine_families are hints;
the 22 curated chassis entries have engine labels but are NOT VIN-verified
individual vehicles. All clients must use this API as their authoritative
catalogue, preserving only a clearly labelled offline presentation fallback.
"""
from __future__ import annotations

from functools import lru_cache
import json
import sys
from pathlib import Path
from typing import Any

ROOT = Path(getattr(sys,"_MEIPASS",Path(__file__).resolve().parents[2]))
GLOBAL_PATH = ROOT / "data" / "vehicle_catalog.json"
FITMENT_PATH = ROOT / "data" / "vehicle_fitments.json"


@lru_cache(maxsize=1)
def global_catalog() -> dict[str, Any]:
    return json.loads(GLOBAL_PATH.read_text(encoding="utf-8"))


@lru_cache(maxsize=1)
def curated_fitments() -> dict[str, Any]:
    return json.loads(FITMENT_PATH.read_text(encoding="utf-8"))


def makes(query: str = "") -> list[str]:
    needle = query.casefold().strip()
    return sorted({
        entry["make"] for entry in global_catalog()["makes"]
        if needle in entry["make"].casefold()
    })


def models(make: str, year: int | None = None, query: str = "", limit: int = 300) -> list[dict[str, Any]]:
    if not make.strip():
        return []
    result: list[dict[str, Any]] = []
    for brand in global_catalog()["makes"]:
        if brand["make"].casefold() != make.casefold():
            continue
        for row in brand["models"]:
            if query and query.casefold().strip() not in row["model"].casefold():
                continue
            ranges = row.get("year_ranges") or []
            if year is not None and not any(low <= year <= high for low, high in ranges):
                continue
            result.append({
                "make": brand["make"],
                "model": row["model"],
                "year_ranges": ranges,
                "vehicle_type": row.get("vehicle_type"),
                "engine_families": row.get("engine_families", []),
                "common_fuels": row.get("common_fuels", []),
                "engine_scope": row.get("engine_data_scope", "family-level"),
                "source": global_catalog().get("source", {}).get("name", "project-seed"),
                "disclaimer": "Model-family hints only; year-specific engine fitment requires VIN/market confirmation.",
            })
    return sorted(result, key=lambda row: row["model"])[:limit]


def fitments(make: str, model: str, year: int | None = None) -> list[dict[str, Any]]:
    answer: list[dict[str, Any]] = []
    for row in curated_fitments()["entries"]:
        if row["make"].casefold() != make.casefold() or row["model"].casefold() != model.casefold():
            continue
        years = row.get("years", [])
        if year is not None and year not in years:
            continue
        answer.append({
            "make": row["make"], "model": row["model"],
            "chassis": row["chassis"], "years": years if year is None else [year],
            "engines": row.get("engines", []),
            "source": "project-curated-fitment",
            "scope": "selector_hint_not_vin_verified",
            "disclaimer": "Chassis, engine and ECU choices vary by model year, VIN, engine market and option code.",
        })
    return answer


def registry_stats() -> dict[str, Any]:
    brands = global_catalog()["makes"]
    curated = curated_fitments()["entries"]
    return {
        "make_count": len(brands),
        "global_model_families": sum(len(make["models"]) for make in brands),
        "curated_chassis_entries": len(curated),
        "global_source": global_catalog().get("source", {}),
        "worldwide_exhaustive": False,
        "data_authority": "backend",
        "engines": "family-level globally; selected curated chassis hints, not VIN-level certainty",
    }


def vehicle_protocol_profile(
    *, make: str, model: str, year: int, market: str = "unknown",
    engine: str = "", chassis: str = "", fuel: str = "",
    vehicle_class: str = "passenger", detected_elm: str | None = None,
) -> dict[str, Any]:
    """One canonical response for ALL seeded make/model/year combinations.

    The year/market regulation hints are the same for any client. An engine
    label does not confirm a real engine, a physical ECU or a transport.
    """
    from urllib.parse import urlencode
    from vehicle.protocol.registry import assess_protocols

    if not make.strip() or not model.strip():
        raise ValueError("make and model are required")
    if not (1886 <= year <= 2100):
        raise ValueError("Year outside supported range")
    matching_models = [
        row for row in models(make, year=year, limit=500)
        if row["model"].casefold() == model.casefold()
    ]
    if not matching_models:
        return {
            "status": "not_in_seed_catalog",
            "make": make, "model": model, "year": year,
            "protocols": None,
            "engines": [],
            "notice": "Not in local seed. Query /vpic/models or VIN/OEM documentation; do not infer a protocol.",
        }

    representative = matching_models[0]
    entries = [
        row for row in fitments(make, model, year=year)
        if not chassis or row["chassis"].casefold() == chassis.casefold()
    ]
    selected_engine = engine.strip()
    listed_engines = [
        {"name": eng.get("name"), "ecus": eng.get("ecus", []),
         "scope": "curated_not_vin_verified"}
        for entry in entries for eng in entry["engines"]
    ]
    exact_engines = [
        e for e in listed_engines if e["name"].casefold() == selected_engine.casefold()
    ] if selected_engine else []
    matched_chassis = next(
        (entry["chassis"] for entry in entries if not chassis or entry["chassis"].casefold() == chassis.casefold()),
        chassis or None,
    )
    compatibility = assess_protocols(
        year=year, market=market, make=representative["make"],
        fuel=fuel, vehicle_class=vehicle_class, detected_elm=detected_elm,
    )
    portrait = (
        "/api/v1/vehicle-registry/portrait?"
        + urlencode({
            "make": representative["make"], "model": representative["model"],
            "chassis": matched_chassis or "",
        })
    )
    return {
        "status": "seeded_not_vin_verified",
        "make": representative["make"],
        "model": representative["model"],
        "year": year,
        "market": market,
        "chassis": matched_chassis,
        "requested_engine": selected_engine or None,
        "engine_found_in_curated_hints": bool(exact_engines),
        "engines": listed_engines,
        "engine_families": representative["engine_families"],
        "common_fuels": representative["common_fuels"],
        "vehicle_type": representative["vehicle_type"],
        "engine_scope": "curated_selector_hints" if entries else representative["engine_scope"],
        "protocols": compatibility,
        "image": {
            "source": "project-generated",
            "portrait_api_url": portrait,
            "real_photo_lookup_api_url": (
                "/api/v1/vehicle-registry/photo?"
                + urlencode({
                    "make": representative["make"], "model": representative["model"],
                    "chassis": matched_chassis or "",
                })
            ),
            "real_photo_match_status": "unverified_until_attributed_commons_response",
        },
        "sources": ["NHTSA-derived local model seed"]
        + (["project curated engine hints"] if entries else []),
        "verified_ecu_protocol": False,
        "notice": (
            "Catalog vehicle/engine/protocol information is advisory only; "
            "VIN/market/engine ECU/adapter handshake required for exact support."
        ),
    }

from __future__ import annotations

import asyncio
from dataclasses import dataclass
from typing import Any
from uuid import uuid4

from vehicle.devices.models import DeviceCapabilities, DeviceDescriptor, DeviceStatus
from vehicle.obd.adapters.ble import ObdBleTransport
from vehicle.obd.adapters.simulator import SimulatorTransport
from vehicle.obd.adapters.tcp_wifi import ObdWifiTransport
from vehicle.obd.adapters.usb_serial import ObdUsbSerialTransport
from vehicle.obd.client import GenericObdClient
from vehicle.obd.transport import DiagnosticTransport


@dataclass
class ManagedConnection:
    descriptor: DeviceDescriptor
    transport: DiagnosticTransport
    obd: GenericObdClient | None = None


class DeviceConnectionError(ConnectionError):
    pass


class VCIConnectionManager:
    """Runtime device discovery and connection manager.

    Physical discovery is intentionally generic: USB means serial adapters,
    BLE means discoverable GATT peripherals, and Wi-Fi uses explicit host/port
    probing because a generic automotive TCP broadcast protocol does not exist.
    """

    def __init__(self) -> None:
        self.devices: dict[str, DeviceDescriptor] = {}
        self.connections: dict[str, ManagedConnection] = {}

    def _register(self, descriptor: DeviceDescriptor) -> DeviceDescriptor:
        self.devices[descriptor.device_id] = descriptor
        return descriptor

    async def scan(self, transport: str, timeout: float = 3.0) -> list[DeviceDescriptor]:
        transport = transport.lower().strip()
        if transport == "usb":
            return await self._scan_usb()
        if transport == "ble":
            return await self._scan_ble(timeout)
        raise DeviceConnectionError(
            "Generic Wi-Fi discovery is intentionally not automatic; provide a host/port and use Wi-Fi probe."
        )

    async def _scan_usb(self) -> list[DeviceDescriptor]:
        try:
            from serial.tools import list_ports
        except ImportError as exc:
            raise DeviceConnectionError("pyserial is required for USB device discovery") from exc

        ports = await asyncio.to_thread(lambda: list(list_ports.comports()))
        found: list[DeviceDescriptor] = []
        for port in ports:
            descriptor = DeviceDescriptor(
                device_id=f"usb:{port.device}",
                manufacturer=(port.manufacturer or "Unknown USB").strip(),
                model=(port.product or port.description or "Serial VCI").strip(),
                protocol="ELM327-compatible serial",
                connection_type="USB",
                capabilities=DeviceCapabilities(obd=True, can=False, uds=False, usb=True),
                metadata={
                    "port": port.device,
                    "serial_number": port.serial_number,
                    "vid": port.vid,
                    "pid": port.pid,
                    "description": port.description,
                    "hwid": port.hwid,
                },
            )
            found.append(self._register(descriptor))
        return found

    async def _scan_ble(self, timeout: float) -> list[DeviceDescriptor]:
        try:
            from bleak import BleakScanner
        except ImportError as exc:
            raise DeviceConnectionError("bleak is required for BLE discovery") from exc

        devices = await BleakScanner.discover(timeout=max(0.5, min(timeout, 30.0)))
        found: list[DeviceDescriptor] = []
        for device in devices:
            metadata = dict(getattr(device, "metadata", {}) or {})
            descriptor = DeviceDescriptor(
                device_id=f"ble:{device.address}",
                manufacturer="Unknown BLE",
                model=(device.name or "BLE VCI").strip(),
                protocol="BLE GATT / adapter-specific",
                connection_type="BLE",
                capabilities=DeviceCapabilities(obd=True, ble=True),
                metadata={
                    "address": device.address,
                    "name": device.name,
                    "rssi": getattr(device, "rssi", None),
                    "details": metadata,
                },
            )
            found.append(self._register(descriptor))
        return found

    async def probe_wifi(self, host: str, port: int = 35000, timeout: float = 2.0) -> DeviceDescriptor:
        host = host.strip()
        if not host:
            raise DeviceConnectionError("Wi-Fi host is required")
        try:
            reader, writer = await asyncio.wait_for(asyncio.open_connection(host, int(port)), timeout=timeout)
            writer.close()
            await writer.wait_closed()
        except Exception as exc:
            raise DeviceConnectionError(f"Wi-Fi probe failed for {host}:{port}: {exc}") from exc

        descriptor = DeviceDescriptor(
            device_id=f"wifi:{host}:{int(port)}",
            manufacturer="Unknown Wi-Fi",
            model="TCP OBD VCI",
            protocol="ELM327-compatible TCP",
            connection_type="Wi-Fi",
            capabilities=DeviceCapabilities(obd=True, wifi=True),
            metadata={"host": host, "port": int(port)},
        )
        return self._register(descriptor)

    def add_simulator(self) -> DeviceDescriptor:
        device_id = f"simulator:{uuid4()}"
        descriptor = DeviceDescriptor(
            device_id=device_id,
            manufacturer="AI Auto Diagnostic",
            model="OBD-II Simulator",
            firmware_version="sim-1",
            protocol="ELM327 simulator",
            connection_type="SIMULATOR",
            capabilities=DeviceCapabilities(obd=True, can=True, uds=True),
            metadata={
                "responses": {
                    "0100": "41 00 08 18 80 00",
                    "ATZ": "ELM327 v2.2",
                    "ATE0": "OK",
                    "ATL0": "OK",
                    "ATS0": "OK",
                    "ATSP0": "OK",
                    "0902": "49 02 01 57 44 44 32 31 31 30 38 30 31 41 31 32 33 34 35 36",
                    "03": "43 01 02",
                    "010C": "41 0C 1A 80",
                    "0105": "41 05 5A",
                    "010D": "41 0D 28",
                    "0111": "41 11 80",
                }
            },
        )
        return self._register(descriptor)

    def _transport_for(self, descriptor: DeviceDescriptor, config: dict[str, Any]) -> DiagnosticTransport:
        kind = descriptor.connection_type.upper().replace("-", "") if descriptor.connection_type else ""
        if kind == "USB":
            port = str(config.get("port") or descriptor.metadata.get("port") or "")
            if not port:
                raise DeviceConnectionError("USB serial port is required")
            return ObdUsbSerialTransport(port, int(config.get("baudrate", 115200)))
        if kind == "WIFI":
            host = str(config.get("host") or descriptor.metadata.get("host") or "")
            port = int(config.get("port") or descriptor.metadata.get("port") or 35000)
            return ObdWifiTransport(host, port)
        if kind == "BLE":
            address = str(config.get("address") or descriptor.metadata.get("address") or "")
            tx_uuid = str(config.get("tx_uuid") or "")
            rx_uuid = str(config.get("rx_uuid") or "")
            if not tx_uuid or not rx_uuid:
                raise DeviceConnectionError("BLE TX UUID and RX UUID are required for adapter-specific GATT communication")
            return ObdBleTransport(address, tx_uuid, rx_uuid)
        if kind == "SIMULATOR":
            return SimulatorTransport(dict(descriptor.metadata.get("responses") or {}))
        raise DeviceConnectionError(f"Unsupported device connection type: {kind}")

    async def connect(self, device_id: str, config: dict[str, Any] | None = None) -> DeviceDescriptor:
        descriptor = self.devices.get(device_id)
        if descriptor is None:
            raise DeviceConnectionError(f"Unknown device: {device_id}")
        config = dict(config or {})
        if device_id in self.connections:
            await self.disconnect(device_id)
        descriptor.status = DeviceStatus.CONNECTING
        transport = None
        try:
            transport = self._transport_for(descriptor, config)
            obd = GenericObdClient(transport, protocol_id=str(config.get("protocol_id", "auto")))
            await obd.connect()
            self.connections[device_id] = ManagedConnection(descriptor, transport, obd)
            descriptor.status = DeviceStatus.CONNECTED
            descriptor.metadata["last_error"] = None
            descriptor.metadata["connection_config"] = config
            return descriptor
        except BaseException as exc:
            if transport is not None:
                await transport.disconnect()
            descriptor.status = DeviceStatus.ERROR
            descriptor.metadata["last_error"] = str(exc)
            if isinstance(exc, asyncio.CancelledError):
                raise
            raise DeviceConnectionError(str(exc)) from exc

    async def disconnect(self, device_id: str) -> DeviceDescriptor:
        descriptor = self.devices.get(device_id)
        if descriptor is None:
            raise DeviceConnectionError(f"Unknown device: {device_id}")
        managed = self.connections.pop(device_id, None)
        if managed:
            await managed.transport.disconnect()
        descriptor.status = DeviceStatus.DISCONNECTED
        return descriptor

    def status(self, device_id: str) -> DeviceDescriptor:
        descriptor = self.devices.get(device_id)
        if descriptor is None:
            raise DeviceConnectionError(f"Unknown device: {device_id}")
        managed = self.connections.get(device_id)
        if managed is not None and not managed.transport.connected:
            descriptor.status = DeviceStatus.ERROR
        return descriptor

    async def reconnect(self, device_id: str) -> DeviceDescriptor:
        descriptor = self.devices.get(device_id)
        if descriptor is None:
            raise DeviceConnectionError(f"Unknown device: {device_id}")
        config = dict(descriptor.metadata.get("connection_config") or {})
        try:
            await self.disconnect(device_id)
        except DeviceConnectionError:
            pass
        return await self.connect(device_id, config)

    def connected_obd(self, device_id: str) -> GenericObdClient:
        managed = self.connections.get(device_id)
        if managed is None or managed.obd is None:
            raise DeviceConnectionError(f"Device is not connected: {device_id}")
        return managed.obd

    async def read_vin(self, device_id: str) -> str | None:
        return await self.connected_obd(device_id).read_vin()

    async def read_dtcs(self, device_id: str) -> list[str]:
        return await self.connected_obd(device_id).read_dtcs()

    async def read_live_data(self, device_id: str) -> dict[str, Any]:
        return await self.connected_obd(device_id).read_standard_live_data()

    async def shutdown(self) -> None:
        for device_id in list(self.connections):
            try:
                await self.disconnect(device_id)
            except Exception:
                pass

from vehicle.devices.models import DeviceDescriptor, DeviceStatus

class DeviceRegistry:
    def __init__(self): self._devices = {}
    def register(self, descriptor: DeviceDescriptor): self._devices[descriptor.device_id] = descriptor
    def remove(self, device_id: str): self._devices.pop(device_id, None)
    def get(self, device_id: str): return self._devices.get(device_id)
    def list(self): return list(self._devices.values())
    def connected(self): return [d for d in self._devices.values() if d.status == DeviceStatus.CONNECTED]

"""VIN-first, read-only discovery shared by local adapters and native bridges."""
from __future__ import annotations
import asyncio
import re
from vehicle.obd.protocols.elm327 import ELM327Protocol
from vehicle.external_registry import nhtsa_decode_vin

PLAN = {"commands": ["0902", "ATH1", "0100", "ATDPN"], "restore": ["ATH0"]}


def vin_from_response(raw: str) -> str | None:
    try:
        for payload in ELM327Protocol.payloads("0902", raw):
            if not payload.startswith(b"\x49\x02"):
                continue
            match = re.search(r"[A-HJ-NPR-Z0-9]{17}", payload[3:].decode("ascii", errors="ignore"))
            if match:
                return match.group()
    except ValueError:
        pass
    return None


def responding_modules(raw: str) -> list[dict]:
    modules = {}
    for line in re.split(r"[\r\n>]+", raw.upper()):
        match = re.match(r"^\s*([0-9A-F]{3}|[0-9A-F]{8})\s+", line)
        compact = "".join(line.split())
        address = match[1] if match else None
        if address is None and re.fullmatch(r"[0-9A-F]+", compact):
            if len(compact) > 10 and compact.startswith(("18DA", "18DB")):
                address = compact[:8]
            elif len(compact) >= 5 and len(compact) % 2:
                address = compact[:3]
        if address is None:
            continue
        try:
            payloads = ELM327Protocol.payloads("0100", line)
        except ValueError:
            continue
        if any(p.startswith(b"\x41\x00") and len(p) >= 6 for p in payloads):
            modules[address] = {"address": address, "name": "OBD ECU", "services": ["01-00"], "observed": True}
    if not modules:
        try:
            payloads = ELM327Protocol.payloads("0100", raw)
            if any(p.startswith(b"\x41\x00") and len(p) >= 6 for p in payloads):
                modules[None] = {"address": None, "name": "OBD ECU", "services": ["01-00"], "observed": True}
        except ValueError:
            pass
    return list(modules.values())


async def identify(responses: dict[str, str], *, simulated: bool = False) -> dict:
    vin = vin_from_response(responses.get("0902", ""))
    vehicle, lookup_status = None, "vin_unavailable"
    if vin and not simulated:
        try:
            vehicle = await asyncio.to_thread(nhtsa_decode_vin, vin)
            lookup_status = "identified" if vehicle.get("make") and vehicle.get("model") and vehicle.get("error_code") == "0" else "incomplete"
        except Exception:
            lookup_status = "lookup_unavailable"
    elif simulated:
        lookup_status = "simulated"
    modules = responding_modules(responses.get("0100", ""))
    protocol = None
    if modules and not simulated:
        from obd.protocols import detected_protocol
        try:
            protocol = detected_protocol(responses.get("ATDPN", ""))
        except ValueError:
            pass  # An adapter label alone is not proof of a negotiated ECU link.
    return {"vin": vin, "vehicle": vehicle, "identification_status": lookup_status,
            "modules": modules, "protocol": protocol, "simulated": simulated,
            "scope": "generic_obd_responders_only"}


async def collect(command) -> dict[str, str]:
    responses = {}
    try:
        for step in PLAN["commands"]:
            responses[step] = await command(step)
    finally:
        # Restore even when a bridge request times out or fails midway.
        for step in PLAN["restore"]:
            await command(step)
    return responses

"""ISO 13400-2 TCP routing activation and bounded read-only UDS exchanges.

No discovery inference, authentication bypass, coding or programming services.
TLS-only gateways need a separate authenticated/TLS transport, not this client.
"""
from __future__ import annotations

import asyncio
import struct
from vehicle.uds.read_only import validate_read_request, validate_positive


class DoipError(ConnectionError):
    pass


class DoipClient:
    def __init__(self, host: str, *, source_address: int, target_address: int,
                 port: int = 13400, timeout: float = 5):
        if not host.strip() or not 1 <= port <= 65535:
            raise ValueError('A valid host and TCP port are required')
        if not all(1 <= address <= 65535 for address in (source_address, target_address)):
            raise ValueError('Logical addresses must be nonzero uint16 values')
        if not 0 < timeout <= 30:
            raise ValueError('Timeout must be within 0..30 seconds')
        self.host, self.port = host, port
        self.source, self.target, self.timeout = source_address, target_address, timeout
        self.reader = self.writer = None
        self.lock = asyncio.Lock()

    async def close(self):
        writer, self.writer = self.writer, None
        self.reader = None
        if writer:
            writer.close()
            try:
                await writer.wait_closed()
            except OSError:
                pass

    async def _send(self, kind: int, payload: bytes):
        self.writer.write(struct.pack('!BBHI', 2, 0xFD, kind, len(payload)) + payload)
        await self.writer.drain()

    async def _receive(self):
        header = await self.reader.readexactly(8)
        version, inverse, kind, size = struct.unpack('!BBHI', header)
        if version not in (2, 3) or version ^ inverse != 255:
            raise DoipError('Invalid DoIP version/header')
        if size > 65536:
            raise DoipError('DoIP payload exceeds 64 KiB limit')
        return kind, await self.reader.readexactly(size)

    async def _read_exchange(self, request: bytes):
        self.reader, self.writer = await asyncio.open_connection(self.host, self.port)
        await self._send(5, struct.pack('!HB4x', self.source, 0))
        kind, body = await self._receive()
        if kind != 6 or len(body) not in (9, 13) or int.from_bytes(body[:2], 'big') != self.source or body[4] != 0x10:
            raise DoipError('DoIP routing activation was not accepted')
        await self._send(0x8001, struct.pack('!HH', self.source, self.target) + request)
        for _ in range(32):
            kind, body = await self._receive()
            if kind == 7 and not body:
                await self._send(8, self.source.to_bytes(2, 'big'))
                continue
            if kind == 0x8002:
                if len(body) < 5 or body[:4] != struct.pack('!HH', self.target, self.source) or body[4] != 0:
                    raise DoipError('Invalid diagnostic acknowledgement')
                continue
            if kind != 0x8001 or len(body) < 5:
                raise DoipError(f'DoIP diagnostic request rejected (payload type 0x{kind:04X})')
            if body[:4] != struct.pack('!HH', self.target, self.source):
                raise DoipError('Diagnostic logical addresses do not match the requested ECU')
            response = body[4:]
            if response == bytes((0x7F, request[0], 0x78)):
                continue  # responsePending remains within the overall deadline.
            try:
                validate_positive(request, response)
            except ValueError as error:
                raise DoipError(str(error)) from error
            return response
        raise DoipError('DoIP response frame limit exceeded')

    async def read(self, request: bytes) -> bytes:
        validate_read_request(request)
        async with self.lock:
            try:
                async with asyncio.timeout(self.timeout):
                    return await self._read_exchange(request)
            except DoipError:
                raise
            except (TimeoutError, OSError, asyncio.IncompleteReadError) as error:
                raise DoipError(f'DoIP transport failed: {type(error).__name__}') from error
            finally:
                await self.close()

"""Optional NHTSA VIN and Wikimedia Commons image lookups.

Public remote data is advisory and must never override a measured ECU/VIN
identification. Return provenance and attribution; never scrape Wikipedia
HTML or silently import unlicensed photographs into application bundles.
"""
from __future__ import annotations

from functools import lru_cache
from html import unescape
from html.parser import HTMLParser
import json
import re
from typing import Any
from urllib.parse import quote, urlencode, urlsplit
from urllib.request import Request, urlopen


class RemoteRegistryUnavailable(RuntimeError):
    pass


class _PlainText(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts: list[str] = []

    def handle_data(self, data: str) -> None:
        self.parts.append(data)


def _plain(html: str) -> str:
    parser = _PlainText()
    parser.feed(html)
    return unescape("".join(parser.parts)).strip()[:300]


def _get_json(url: str) -> dict[str, Any]:
    # URL is built ONLY by the functions below with fixed HTTPS domains.
    request = Request(url, headers={"User-Agent": "AI-Car-Scanner/0.6 (+vehicle metadata lookup)"})
    try:
        with urlopen(request, timeout=6.0) as result:
            payload = json.loads(result.read(1_000_000).decode("utf-8"))
    except (OSError, ValueError, TimeoutError) as exc:
        raise RemoteRegistryUnavailable("Remote vehicle metadata source unavailable") from exc
    if not isinstance(payload, dict):
        raise RemoteRegistryUnavailable("Unexpected remote vehicle metadata format")
    return payload


@lru_cache(maxsize=1)
def nhtsa_available_makes() -> dict[str, Any]:
    """NHTSA GetAllMakes: live optional supplemental list, US-oriented."""
    payload = _get_json(
        "https://vpic.nhtsa.dot.gov/api/vehicles/GetAllMakes?format=json"
    )
    values = payload.get("Results") or []
    if not isinstance(values, list):
        raise RemoteRegistryUnavailable("NHTSA makes response format changed")
    return {
        "source": "NHTSA vPIC / GetAllMakes",
        "market_scope": "US intended-sale/import market; not all world brands",
        "makes": sorted(set(
            str(row["Make_Name"]).strip()
            for row in values if isinstance(row, dict) and row.get("Make_Name")
        )),
        "requires_live_network": True,
    }


@lru_cache(maxsize=128)
def nhtsa_models_for_make(make: str, year: int | None = None) -> dict[str, Any]:
    """Optional live make/model discovery; NEVER assume engine/ECU specifics."""
    name = make.strip()
    if not (1 <= len(name) <= 80) or any(c in name for c in "<>\\\\\r\n"):
        raise ValueError("Invalid make")
    if year is not None and not (1996 <= year <= 2100):
        raise ValueError("vPIC model-year filtering requires >=1996")
    prefix = "https://vpic.nhtsa.dot.gov/api/vehicles/"
    if year is not None:
        url = (
            prefix + "GetModelsForMakeYear/make/" + quote(name, safe="")
            + "/modelyear/" + str(year) + "?format=json"
        )
    else:
        url = prefix + "GetModelsForMake/" + quote(name, safe="") + "?format=json"
    values = _get_json(url).get("Results") or []
    if not isinstance(values, list):
        raise RemoteRegistryUnavailable("NHTSA models response format changed")
    return {
        "source": "NHTSA vPIC / " + ("GetModelsForMakeYear" if year is not None else "GetModelsForMake"),
        "make": name,
        "year": year,
        "market_scope": "US intended-sale/import; exact engine and ECU require VIN/OEM identification",
        "model_names": sorted(set(
            str(row["Model_Name"]).strip() for row in values
            if isinstance(row, dict) and row.get("Model_Name")
        )),
        "engine_details": "not_provided",
        "requires_live_network": True,
    }


def nhtsa_decode_vin(vin: str, model_year: int | None = None) -> dict[str, Any]:
    """NHTSA vPIC VIN decoder; US-oriented coverage; not an ECU protocol oracle.

    Caller must supply a valid 17-character VIN; no VIN is logged.
    """
    vin = vin.strip().upper()
    if not re.fullmatch(r"[A-HJ-NPR-Z0-9]{17}", vin):
        raise ValueError("VIN must contain exactly 17 valid VIN characters")
    params = {"format": "json"}
    if model_year is not None:
        if not 1980 <= model_year <= 2100:
            raise ValueError("Invalid VIN model year")
        params["modelyear"] = str(model_year)
    url = (
        "https://vpic.nhtsa.dot.gov/api/vehicles/DecodeVinValuesExtended/"
        + quote(vin, safe="") + "?" + urlencode(params)
    )
    payload = _get_json(url)
    rows = payload.get("Results") or []
    if not isinstance(rows, list) or not rows:
        raise RemoteRegistryUnavailable("NHTSA VIN decoder returned no records")
    row = rows[0]
    def field(key: str) -> str | None:
        value = row.get(key) if isinstance(row, dict) else None
        result = str(value).strip() if value is not None else ""
        return result or None
    return {
        "source": "NHTSA vPIC DecodeVinValuesExtended",
        "scope": "US intended-sale/import market; global VIN coverage incomplete",
        "vin_last4": vin[-4:],
        "make": field("Make"),
        "model": field("Model"),
        "model_year": field("ModelYear"),
        "engine_model": field("EngineModel"),
        "engine_cylinders": field("EngineCylinders"),
        "engine_displacement_l": field("DisplacementL"),
        "fuel_type": field("FuelTypePrimary"),
        "vehicle_type": field("VehicleType"),
        "error_code": field("ErrorCode"),
        "error_text": field("ErrorText"),
        "protocol_detected": None,
        "notice": "VIN decoding does not identify live CAN/UDS/OBD transport or validate installed engine.",
    }


def _permissive_license(name: str) -> bool:
    normalized = re.sub(r"[-_\s]+", " ", name.casefold()).strip()
    # Never accept NonCommercial / NoDerivatives licences.
    if re.search(r"\b(nc|nd|noncommercial|no derivatives)\b", normalized):
        return False
    return (
        normalized.startswith(("cc0", "public domain", "pd "))
        or bool(re.fullmatch(r"cc by(?: sa)?(?: [0-9.]+)?", normalized))
    )


@lru_cache(maxsize=160)
def commons_photo_candidate(make: str, model: str, chassis: str = "") -> dict[str, Any]:
    """Return one clearly UNVERIFIED real Wikimedia Commons photo candidate.

    Model/chassis labels and licensing are recorded; Commons search by filename
    is not a VIN/chassis proof. UI must show candidate status/attribution.
    """
    for piece in (make, model, chassis):
        if len(piece) > 80 or any(c in piece for c in "<>\\\r\n"):
            raise ValueError("Invalid vehicle name for image search")
    if not make.strip() or not model.strip():
        raise ValueError("make and model are required")
    needle = f"{make} {model} {chassis}".strip()
    params = {
        "action": "query", "generator": "search", "gsrsearch": needle,
        "gsrnamespace": 6, "gsrlimit": 12, "prop": "imageinfo",
        "iiprop": "url|extmetadata", "iiurlwidth": 900,
        "format": "json", "formatversion": 2,
    }
    url = "https://commons.wikimedia.org/w/api.php?" + urlencode(params)
    payload = _get_json(url)
    pages = ((payload.get("query") or {}).get("pages") or [])
    if not isinstance(pages, list):
        return {"status": "no_licensed_candidate", "source": "Wikimedia Commons"}
    make_aliases = {make.casefold()}
    if make.casefold() == "volkswagen":
        make_aliases.add("vw")
    elif make.casefold() == "mercedes-benz":
        make_aliases.add("mercedes")
    elif make.casefold() == "chevrolet":
        make_aliases.add("chevy")
    for page in pages:
        title = str(page.get("title", ""))
        lower_title = title.casefold()
        # Preserve only actual image files; don't use SVG or remote HTML.
        if not lower_title.endswith((".jpg", ".jpeg", ".png")):
            continue
        if not any(alias in lower_title for alias in make_aliases):
            continue
        if chassis:
            if chassis.casefold() not in lower_title:
                continue
            basis = "make_and_chassis_filename"
        elif model.casefold() in lower_title:
            basis = "make_and_model_filename"
        else:
            continue
        info = (page.get("imageinfo") or [{}])[0]
        extra = info.get("extmetadata") or {}
        label = _plain(str((extra.get("LicenseShortName") or {}).get("value", "")))
        license_lc = label.casefold()
        if not _permissive_license(license_lc):
            continue
        thumb = info.get("thumburl") or info.get("url")
        description_page = info.get("descriptionurl")
        if (
            not isinstance(thumb, str) or not isinstance(description_page, str)
            or urlsplit(thumb).hostname != "upload.wikimedia.org"
            or urlsplit(description_page).hostname != "commons.wikimedia.org"
        ):
            continue
        author = _plain(str((extra.get("Artist") or {}).get("value", "")))
        return {
            "status": "candidate_unverified",
            "filename_match_basis": basis,
            "image_url": thumb,
            "file_page": description_page,
            "title": title,
            "author": author or "See file page",
            "license": label,
            "license_url": _plain(str((extra.get("LicenseUrl") or {}).get("value", ""))) or None,
            "source": "Wikimedia Commons",
            "notice": "Real photo, but exact chassis/trim/year has NOT been independently verified; attribution and license apply.",
        }
    return {"status": "no_licensed_candidate", "source": "Wikimedia Commons",
            "notice": "No adequately labelled, permissively licensed photograph was found."}

from __future__ import annotations
