    @abstractmethod
    def close(self): ...
    @abstractmethod
    def connect(self, protocol_id: int, flags: int = 0): ...
    @abstractmethod
    def disconnect(self): ...
    @abstractmethod
    def send(self, messages: list[J2534Message], timeout_ms: int = 1000): ...
    @abstractmethod
