@dataclass(frozen=True)
class CanBusConfig:
    name: str
    bitrate: int = 500_000
    can_fd: bool = False
    data_bitrate: int | None = None
    def to_dict(self) -> dict:
        return {'name': self.name, 'bitrate': self.bitrate, 'can_fd': self.can_fd, 'data_bitrate': self.data_bitrate}

class GatewayRoutingEngine:
    """Read-only bidirectional diagnostic routing abstraction."""
    def __init__(self, buses: dict[str, SimulatedCanBus], topology: VehicleNetworkTopology):
        self.buses = buses; self.topology = topology
        self._request_to_target: dict[tuple[str, int], str] = {}
        self._response_to_source: dict[tuple[str, int], str] = {}
        self.forwarded_frames = 0; self.blocked_frames = 0

    def install(self) -> None:
        for route in self.topology.routes:
            ecu = self.topology.ecu(route.target_ecu_id)
            if route.source_bus not in self.buses or route.target_bus not in self.buses:
                raise ValueError(f'route references unknown bus: {route}')
            self._request_to_target[(route.source_bus, ecu.request_id)] = route.target_bus
            self._response_to_source[(route.target_bus, ecu.response_id)] = route.source_bus
        for bus_name, bus in self.buses.items():
            async def tx_hook(frame: CanFrame, source_bus=bus_name):
                target_bus = self._request_to_target.get((source_bus, frame.arbitration_id))
                if target_bus and target_bus != source_bus:
                    self.forwarded_frames += 1
                    await self.buses[target_bus].send(frame)
            bus.add_tx_hook(tx_hook)
            def rx_hook(frame: CanFrame, target_bus=bus_name):
                source_bus = self._response_to_source.get((target_bus, frame.arbitration_id))
                if source_bus and source_bus != target_bus:
                    self.forwarded_frames += 1
                    self.buses[source_bus].inject(frame)
            bus.add_rx_hook(rx_hook)

    async def start(self) -> None:
        return None
    async def stop(self) -> None:
        return None
    def route_for_ecu(self, ecu_id: str, source_bus: str | None = None) -> GatewayRoute | None:
        candidates = [r for r in self.topology.routes if r.target_ecu_id == ecu_id]
        if source_bus is not None: candidates = [r for r in candidates if r.source_bus == source_bus]
        return candidates[0] if candidates else None
    def stats(self) -> dict:
        return {'forwarded_frames': self.forwarded_frames, 'blocked_frames': self.blocked_frames}

class MultiBusDemultiplexer:
    """One receive task per physical/logical CAN bus."""
    def __init__(self, bus: SimulatedCanBus, response_ids: Iterable[int], poll_timeout_ms: int = 100):
        self.bus = bus; self.response_ids = set(response_ids); self.poll_timeout_ms = poll_timeout_ms
        self.queues: dict[int, asyncio.Queue] = {rid: asyncio.Queue() for rid in self.response_ids}
        self._task: asyncio.Task | None = None; self._stop: asyncio.Event | None = None
        self.unmatched: list[CanFrame] = []
    async def start(self) -> None:
        if self._task and not self._task.done(): return
        self._stop = asyncio.Event(); self._task = asyncio.create_task(self._run(), name='multi-bus-demux')
    async def stop(self) -> None:
        if self._stop: self._stop.set()
        if self._task: await self._task
        self._task = None
    async def _run(self) -> None:
        while self._stop and not self._stop.is_set():
            frame = await self.bus.receive(self.poll_timeout_ms)
            if frame is None: continue
            queue = self.queues.get(frame.arbitration_id)
            if queue is None:
                self.unmatched.append(frame)
                if len(self.unmatched) > 500: del self.unmatched[:250]
            else: queue.put_nowait(frame)

from __future__ import annotations
import asyncio
from collections import defaultdict

class RoutedCanChannel:
    def __init__(self, mux: 'CanBusDemultiplexer', response_id: int):
        self.mux = mux
        self.response_id = response_id
        self.queue: asyncio.Queue = asyncio.Queue()

    async def send(self, frame):
        await self.mux.bus.send(frame)

    async def receive(self, timeout_ms: int = 1000):
        try:
            return await asyncio.wait_for(self.queue.get(), timeout_ms / 1000)
        except asyncio.TimeoutError:
            return None

class CanBusDemultiplexer:
    """One physical CAN receive loop, fan-out by arbitration ID.

    This prevents concurrent UDS clients from consuming each other's ECU
    responses when multiple ECUs share one CAN bus.
    """
    def __init__(self, bus, *, poll_timeout_ms: int = 100):
        self.bus = bus
        self.poll_timeout_ms = poll_timeout_ms
        self._channels: dict[int, list[RoutedCanChannel]] = defaultdict(list)
        self._task: asyncio.Task | None = None
        self._stop = asyncio.Event()
        self.unmatched_frames: list = []

    def register(self, response_id: int) -> RoutedCanChannel:
        channel = RoutedCanChannel(self, response_id)
        self._channels[response_id].append(channel)
        return channel

    def unregister(self, channel: RoutedCanChannel) -> None:
        group = self._channels.get(channel.response_id, [])
        if channel in group:
            group.remove(channel)
        if not group:
            self._channels.pop(channel.response_id, None)

    async def start(self) -> None:
        if self._task and not self._task.done():
            return
        self._stop.clear()
        self._task = asyncio.create_task(self._run(), name='can-demultiplexer')

    async def stop(self) -> None:
        self._stop.set()
        if self._task:
            try:
                await self._task
            finally:
                self._task = None

    async def _run(self) -> None:
        while not self._stop.is_set():
            frame = await self.bus.receive(self.poll_timeout_ms)
            if frame is None:
                continue
            channels = list(self._channels.get(frame.arbitration_id, ()))
            if not channels:
                self.unmatched_frames.append(frame)
                if len(self.unmatched_frames) > 1000:
                    del self.unmatched_frames[:500]
                continue
            for channel in channels:
                channel.queue.put_nowait(frame)

from __future__ import annotations
import asyncio
from dataclasses import dataclass
from uuid import UUID
from vehicle.adapters.can_simulator import SimulatedCanBus
from vehicle.adapters.uds_simulator import UdsEcuSimulator
from vehicle.isotp.stack import IsoTpStack
from vehicle.protocol.trace import ProtocolTraceRecorder, TracedCanBus
from vehicle.uds.client import UdsClient
from vehicle.uds.diagnostics import UdsDiagnosticSession
from .models import EcuNode, VehicleNetworkTopology
from .multiplexer import CanBusDemultiplexer

@dataclass
class EcuRuntime:
    node: EcuNode
    connected: bool = True

class MultiEcuRuntime:
    """Shared-bus multi-ECU read-only diagnostic runtime.

    Per-operation UDS channels are intentionally created fresh. This keeps the
    transport loop independent from HTTP request event loops used by desktop,
    mobile and API test clients while retaining one logical vehicle session.
    """
    def __init__(self, *, session_id: UUID, topology: VehicleNetworkTopology):
        self.session_id = session_id
        self.topology = topology
        self.raw_bus = SimulatedCanBus()
        self.trace = ProtocolTraceRecorder(session_id=session_id)
        self.traced_bus = TracedCanBus(self.raw_bus, self.trace)
        self.mux = CanBusDemultiplexer(self.traced_bus)
        self.ecus: dict[str, EcuRuntime] = {}
        self.gateways = {g.gateway_id: g for g in topology.gateways}
        self._simulators: list[UdsEcuSimulator] = []
        self.connected = False

    async def connect(self) -> None:
        if self.connected:
            return
        for node in self.topology.ecus:
            UdsEcuSimulator(
                self.raw_bus,
                request_id=node.request_id,
                response_id=node.response_id,
                vin=node.metadata.get('vin', 'VINTEST1234567890'),
                software_version=node.metadata.get('software_version', f'{node.ecu_id}-SW-1.0'),
                hardware_version=node.metadata.get('hardware_version', f'{node.ecu_id}-HW-1.0'),
                dtc_records=node.metadata.get('dtc_records'),
            )
            self.ecus[node.ecu_id] = EcuRuntime(node=node)
        self.connected = True

    async def disconnect(self) -> None:
        await self.mux.stop()
        for runtime in self.ecus.values():
            runtime.connected = False
        self.ecus.clear()
        self.connected = False

    async def identify_all(self) -> dict[str, object]:
        self._require_connected()
        return await self._run_concurrent('identify_ecu')

    async def read_all_dtcs(self) -> dict[str, list]:
        self._require_connected()
        return await self._run_concurrent('read_dtcs')

    async def _run_concurrent(self, method: str) -> dict[str, object]:
        # Each HTTP/API operation gets fresh queues/channels to avoid asyncio
        # queue loop affinity across independent request event loops.
        await self.mux.start()
        channels = {r.node.ecu_id: self.mux.register(r.node.response_id) for r in self.ecus.values()}
        try:
            async def one(ecu_id: str, runtime: EcuRuntime):
                channel = channels[ecu_id]
                client = UdsClient(IsoTpStack(channel, runtime.node.request_id, runtime.node.response_id))
                diag = UdsDiagnosticSession(client)
                value = await getattr(diag, method)()
                return ecu_id, value
            pairs = await asyncio.gather(*(one(ecu_id, runtime) for ecu_id, runtime in self.ecus.items()), return_exceptions=False)
            return dict(pairs)
        finally:
            for channel in channels.values():
                self.mux.unregister(channel)
            await self.mux.stop()

    def correlate_dtcs(self, dtcs_by_ecu: dict[str, list]) -> list[dict]:
        by_code: dict[str, list[str]] = {}
        for ecu_id, records in dtcs_by_ecu.items():
            for record in records:
                by_code.setdefault(record.code, []).append(ecu_id)
        correlations = []
        for code, ecus in by_code.items():
            if len(ecus) > 1:
                correlations.append({
                    'type': 'SHARED_DTC', 'code': code, 'ecu_ids': sorted(ecus),
                    'evidence': f'DTC {code} reported by multiple ECUs',
                    'interpretation': 'Cross-ECU correlation; root cause is not confirmed.',
                })
            if code.startswith('U'):
                correlations.append({
                    'type': 'NETWORK_DTC', 'code': code, 'ecu_ids': sorted(ecus),
                    'evidence': f'Network-related DTC {code} reported by ECU set',
                    'interpretation': 'Consider communication path, gateway, power or bus integrity checks.',
                })
        return correlations

    def discover(self) -> VehicleNetworkTopology:
        return self.topology

    def trace_snapshot(self, limit: int = 500):
        return self.trace.snapshot(limit)

    def _require_connected(self) -> None:
        if not self.connected:
            raise RuntimeError('multi-ECU diagnostic runtime is disconnected')

from __future__ import annotations
from vehicle.obd.transport import DiagnosticTransport, TransportError

class ObdBleTransport(DiagnosticTransport):
    """BLE GATT transport seam. UUIDs are adapter-specific and therefore configurable."""
    def __init__(self, address: str, tx_uuid: str, rx_uuid: str):
        self.address, self.tx_uuid, self.rx_uuid = address, tx_uuid, rx_uuid
        self._client=None; self._buffer=bytearray()
    @property
    def connected(self): return bool(self._client and self._client.is_connected)
    async def connect(self):
        try:
            from bleak import BleakClient
            self._client=BleakClient(self.address); await self._client.connect()
            await self._client.start_notify(self.rx_uuid, lambda _, data: self._buffer.extend(data))
        except Exception as e: raise TransportError(str(e)) from e
    async def disconnect(self):
        if self._client and self._client.is_connected: await self._client.disconnect()
        self._client=None
    async def write(self, data: bytes):
        if not self.connected: raise TransportError("BLE transport is not connected")
        await self._client.write_gatt_char(self.tx_uuid, data, response=False)
    async def read_until(self, terminator=b">", timeout=2.0):
        import asyncio, time
        start=time.monotonic()
        while time.monotonic()-start < timeout:
            idx=self._buffer.find(terminator)
            if idx >= 0:
                out=bytes(self._buffer[:idx+len(terminator)]); del self._buffer[:idx+len(terminator)]; return out
            await asyncio.sleep(0.01)
        raise TransportError("BLE read timeout")

from __future__ import annotations
import asyncio
from vehicle.obd.transport import DiagnosticTransport, TransportError

class ObdWifiTransport(DiagnosticTransport):
    """Generic TCP transport for Wi-Fi OBD adapters exposing a socket."""
    def __init__(self, host: str, port: int = 35000):
        self.host, self.port = host, port
        self._reader=None; self._writer=None
    @property
    def connected(self): return self._writer is not None and not self._writer.is_closing()
    async def connect(self):
        try: self._reader, self._writer = await asyncio.wait_for(asyncio.open_connection(self.host, self.port), timeout=5)
        except (OSError, asyncio.TimeoutError) as e: raise TransportError(str(e)) from e
    async def disconnect(self):
        if self._writer:
            self._writer.close(); await self._writer.wait_closed()
        self._reader=self._writer=None
    async def write(self, data: bytes):
        if not self.connected: raise TransportError("Wi-Fi transport is not connected")
        self._writer.write(data); await self._writer.drain()
    async def read_until(self, terminator=b">", timeout=2.0):
        if not self._reader: raise TransportError("Wi-Fi transport is not connected")
        try: return await asyncio.wait_for(self._reader.readuntil(terminator), timeout)
        except (asyncio.TimeoutError, asyncio.IncompleteReadError) as e: raise TransportError(str(e)) from e

from __future__ import annotations
import asyncio
from vehicle.obd.transport import DiagnosticTransport, TransportError

class ObdUsbSerialTransport(DiagnosticTransport):
    """USB serial transport. pyserial is optional and imported only when used."""
    def __init__(self, port: str, baudrate: int = 115200):
        self.port, self.baudrate, self._serial = port, baudrate, None
    @property
    def connected(self): return self._serial is not None and self._serial.is_open
    async def connect(self):
        try:
            import serial
            self._serial = serial.Serial(self.port, self.baudrate, timeout=0.1)
        except Exception as e: raise TransportError(str(e)) from e
    async def disconnect(self):
        if self._serial: self._serial.close()
        self._serial=None
    async def write(self, data: bytes):
        if not self.connected: raise TransportError("USB transport is not connected")
        await asyncio.to_thread(self._serial.write, data)
    async def read_until(self, terminator=b">", timeout=2.0):
        if not self.connected: raise TransportError("USB transport is not connected")
        async def read():
            buf=bytearray()
            while True:
                b=await asyncio.to_thread(self._serial.read, 1)
                if b: buf += b; 
                if buf.endswith(terminator): return bytes(buf)
        try: return await asyncio.wait_for(read(), timeout)
        except asyncio.TimeoutError as e: raise TransportError("USB read timeout") from e

