class UdsDiagnosticSession:
    """Read-only UDS diagnostic facade for ECU identification and DTC capture."""

    VIN_DID = 0xF190
    SOFTWARE_VERSION_DID = 0xF187
    HARDWARE_VERSION_DID = 0xF191

    def __init__(self, client: UdsClient, *, identity_dids: dict[str, int] | None = None):
        self.client = client
        dids = identity_dids or {}
        self.vin_did = dids.get('vin', self.VIN_DID)
        self.software_version_did = dids.get('software_version', self.SOFTWARE_VERSION_DID)
        self.hardware_version_did = dids.get('hardware_version', self.HARDWARE_VERSION_DID)

    async def identify_ecu(self) -> EcuIdentity:
        values: dict[str, bytes | None] = {'vin': None, 'software_version': None, 'hardware_version': None}
        for name, did in (
            ('vin', self.vin_did),
            ('software_version', self.software_version_did),
            ('hardware_version', self.hardware_version_did),
        ):
            try:
                values[name] = await self.client.read_data_by_identifier(did)
            except Exception:
                # Identity is best-effort; one unsupported DID must not hide the others.
                values[name] = None

        def text(raw: bytes | None) -> str | None:
            if raw is None:
                return None
            value = bytes(x for x in raw if 32 <= x <= 126).decode('ascii', errors='ignore').strip()
            return value or None

        return EcuIdentity(
            vin=text(values['vin']),
            software_version=text(values['software_version']),
            hardware_version=text(values['hardware_version']),
        )

    async def read_dtcs(self, subfunction: int = 0x02) -> list[UdsDtcRecord]:
        payload = await self.client.read_dtc_information(subfunction)
        return parse_dtc_information(payload)

    @property
    def supports_clear_dtc(self) -> bool:
        # Service 0x14 is intentionally excluded from MVP/Phase 16 safety scope.
        return False

"""Shared explicit read-only UDS request and positive-response validation."""


def read_request(did: int | None, dtc_status_mask: int | None) -> bytes:
    if (did is None) == (dtc_status_mask is None):
        raise ValueError('Provide exactly one DID or DTC status mask')
    if did is not None:
        if not 0 <= did <= 65535:
            raise ValueError('DID must fit uint16')
        return b'\x22'+did.to_bytes(2,'big')
    if not 0 <= dtc_status_mask <= 255:
        raise ValueError('DTC status mask must fit uint8')
    return bytes((0x19,2,dtc_status_mask))


def validate_read_request(request: bytes):
    if not ((len(request) == 3 and request[0] == 0x22)
            or (len(request) == 3 and request[:2] == b'\x19\x02')):
        raise ValueError('Only ReadDataByIdentifier and reportDTCByStatusMask are supported')


def validate_positive(request: bytes, response: bytes):
    validate_read_request(request)
    if response[:1] == b'\x7F':
        raise ValueError(f'Negative UDS response: {response.hex().upper()}')
    expected = bytes((request[0]+0x40,)) + request[1:3 if request[0] == 0x22 else 2]
    if not response.startswith(expected):
        raise ValueError('UDS service/DID/subfunction response mismatch')
    if request[0] == 0x19 and (len(response) < 3 or (len(response)-3) % 4):
        raise ValueError('Truncated UDS DTC status/record response')

