import json
import sqlite3
from pathlib import Path
from typing import Any

class LocalDiagnosticStore:
    """Small offline-first SQLite store. Production Android uses the same logical schema via Drift/SQLite."""
    def __init__(self, path: str | Path = ":memory:"):
        self.db = sqlite3.connect(str(path))
        self.db.execute("CREATE TABLE IF NOT EXISTS records (id TEXT PRIMARY KEY, kind TEXT NOT NULL, payload TEXT NOT NULL, updated_at REAL NOT NULL)")
        self.db.execute("CREATE TABLE IF NOT EXISTS sync_queue (id TEXT PRIMARY KEY, operation TEXT NOT NULL, payload TEXT NOT NULL, created_at REAL NOT NULL)")
        self.db.commit()
    def upsert(self, record_id: str, kind: str, payload: dict[str, Any], updated_at: float) -> None:
        self.db.execute("INSERT INTO records(id,kind,payload,updated_at) VALUES(?,?,?,?) ON CONFLICT(id) DO UPDATE SET kind=excluded.kind,payload=excluded.payload,updated_at=excluded.updated_at", (record_id, kind, json.dumps(payload), updated_at))
        self.db.commit()
    def get(self, record_id: str):
        row = self.db.execute("SELECT id,kind,payload,updated_at FROM records WHERE id=?", (record_id,)).fetchone()
        if not row: return None
        return {"id": row[0], "kind": row[1], "payload": json.loads(row[2]), "updated_at": row[3]}

    def close(self) -> None:
        """Release the underlying SQLite connection."""
        self.db.close()

    def __enter__(self) -> "LocalDiagnosticStore":
        return self

    def __exit__(self, exc_type, exc, traceback) -> None:
        self.close()

from dataclasses import dataclass
import json, sqlite3, time, uuid

@dataclass(frozen=True)
class SyncOperation:
    id: str
    operation: str
    payload: dict
    created_at: float

class SyncQueue:
    def __init__(self, connection: sqlite3.Connection):
        self.db = connection
    def enqueue(self, operation: str, payload: dict) -> SyncOperation:
        item = SyncOperation(str(uuid.uuid4()), operation, payload, time.time())
        self.db.execute("INSERT INTO sync_queue(id,operation,payload,created_at) VALUES(?,?,?,?)", (item.id,item.operation,json.dumps(item.payload),item.created_at))
        self.db.commit()
        return item
    def pending(self, limit: int = 100):
        rows = self.db.execute("SELECT id,operation,payload,created_at FROM sync_queue ORDER BY created_at LIMIT ?", (limit,)).fetchall()
        return [SyncOperation(r[0],r[1],json.loads(r[2]),r[3]) for r in rows]
    def acknowledge(self, operation_id: str):
        self.db.execute("DELETE FROM sync_queue WHERE id=?", (operation_id,)); self.db.commit()

from dataclasses import dataclass
import struct

MAGIC = b"AAV1"

@dataclass(frozen=True)
class VciPacket:
    channel: int
    payload: bytes

class CustomVciCodec:
    """Reference framing for the future custom Android VCI. This is not a vehicle protocol."""
    @staticmethod
    def encode(packet: VciPacket) -> bytes:
        if not 0 <= packet.channel <= 255: raise ValueError("channel out of range")
        if len(packet.payload) > 65535: raise ValueError("payload too large")
        return MAGIC + bytes([packet.channel]) + struct.pack(">H", len(packet.payload)) + packet.payload
    @staticmethod
    def decode(frame: bytes) -> VciPacket:
        if len(frame) < 7 or frame[:4] != MAGIC: raise ValueError("invalid VCI frame")
        channel = frame[4]; length = struct.unpack(">H", frame[5:7])[0]
        if len(frame) != 7 + length: raise ValueError("invalid VCI length")
        return VciPacket(channel, frame[7:])

// Experimental ONLY: not imported by application code. No ECU or I/O access.
#include <cmath>
#include <cstddef>
#include <limits>
#ifdef _WIN32
#define EXPORT __declspec(dllexport)
#else
#define EXPORT __attribute__((visibility("default")))
#endif
extern "C" EXPORT int telemetry_mean(const double* values, std::size_t count, double* output) noexcept {
    if (!values || !output || !count) return 1;
    long double sum = 0, correction = 0;
    for (std::size_t i = 0; i < count; ++i) {
        if (!std::isfinite(values[i])) return 2;
        const long double value = values[i];
        const long double next = sum + value;
        correction += std::abs(sum) >= std::abs(value) ? (sum-next)+value : (value-next)+sum;
        sum = next;
    }
    const long double result = (sum+correction)/count;
    if (!std::isfinite(result) || std::abs(result) > std::numeric_limits<double>::max()) return 3;
    *output = static_cast<double>(result);
    return 0;
}

#include <cassert>
#include <cmath>
#include <cstddef>
#include <limits>
extern "C" int telemetry_mean(const double*, std::size_t, double*) noexcept;
int main() {
    double out=42; const double xs[]={1,2,3};
    assert(telemetry_mean(xs,3,&out)==0 && out==2);
    assert(telemetry_mean(nullptr,3,&out)==1);
    assert(telemetry_mean(xs,0,&out)==1);
    assert(telemetry_mean(xs,3,nullptr)==1);
    const double nan[]={std::numeric_limits<double>::quiet_NaN()};
    assert(telemetry_mean(nan,1,&out)==2);
    const double inf[]={std::numeric_limits<double>::infinity()};
    assert(telemetry_mean(inf,1,&out)==2);
    const double cancel[]={1e16,1,-1e16};
    assert(telemetry_mean(cancel,3,&out)==0 && std::abs(out-1.0/3)<1e-15);
    const double huge[]={1e308,1e308};
    assert(telemetry_mean(huge,2,&out)==0 && out==1e308);
}

"""User-scoped online installer helper; no Git client or shell interpolation."""
from __future__ import annotations

import argparse
import hashlib
from datetime import datetime, timezone
import json
import os
from pathlib import Path, PurePosixPath
import re
import shutil
import stat
import subprocess
import sys
import tempfile
import urllib.request
import urllib.error
import zipfile

OWNER = 'AI-Car-Scanner-online-installer-v1'
MARKER = '.ai-car-installer.json'
REPOSITORY = 'Grigor1995/AI-CAR-SCANER'


def manifest_data(path):
    data = json.loads(Path(path).read_text(encoding='utf-8'))
    if data.get('repository') != REPOSITORY or not re.fullmatch(r'[0-9a-f]{40}', data.get('commit', '')):
        raise ValueError('Installer manifest must pin the official repository and a full commit SHA')
    if data.get('source_mode', 'online') not in {'online', 'bundled'}:
        raise ValueError('Unknown installer source mode')
    if data.get('source_mode') == 'bundled' and not re.fullmatch(r'[0-9a-f]{64}', data.get('source_sha256', '')):
        raise ValueError('Bundled source must have a SHA-256 checksum')
    return data


def claim_root(root):
    root = root.resolve()
    if root == Path(root.anchor) or root == Path.home().resolve():
        raise ValueError('Choose a dedicated application folder')
    marker = root / MARKER
    if marker.is_file():
        if json.loads(marker.read_text(encoding='utf-8')).get('owner') != OWNER:
            raise ValueError('Installation folder belongs to another application')
    elif root.exists() and any(root.iterdir()):
        raise ValueError('Installation folder must be empty or managed by this installer')
    root.mkdir(parents=True, exist_ok=True)
    if not marker.exists():
        marker.write_text(json.dumps({'owner': OWNER}) + '\n', encoding='utf-8')
    return root


def extract_source(archive, output, commit):
    """Validate the whole snapshot before writing; never follow archive links."""
    prefix = 'AI-CAR-SCANER-' + commit
    with zipfile.ZipFile(archive) as source:
        total = 0
        for item in source.infolist():
            name = PurePosixPath(item.filename.replace('\\', '/'))
            if (not name.parts or name.parts[0] != prefix or name.is_absolute()
                    or '..' in name.parts or any(':' in part or part.rstrip(' .') != part
                        or re.match(r'^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\.|$)', part, re.I)
                        for part in name.parts)
                    or stat.S_ISLNK(item.external_attr >> 16)):
                raise ValueError('Unsafe repository snapshot entry: ' + item.filename)
            if not output.joinpath(*name.parts).resolve().is_relative_to(output.resolve()):
                raise ValueError('Repository snapshot escapes staging folder')
            total += item.file_size
        if total > 4 * 1024**3:
            raise ValueError('Unexpectedly large repository snapshot')
        source.extractall(output)
    checkout = output / prefix
    for relative in ('runner.py', 'finalbuild/scripts/local_runner.py', 'finalbuild/requirements.txt'):
        if not (checkout / relative).is_file():
            raise ValueError('Incomplete repository snapshot: ' + relative)
    return checkout


def promote_source(checkout, repository, previous_files=()):
    """Update only snapshot files; retain the venv, AI model and runner state."""
    files = {p.relative_to(checkout).as_posix() for p in checkout.rglob('*') if p.is_file()}
    # Validate manifest paths before deleting files from an earlier snapshot.
    for relative in set(previous_files) - files:
        path = repository / relative
        if not path.resolve().is_relative_to(repository.resolve()) or Path(relative).is_absolute():
            raise ValueError('Invalid previous installation manifest')
        if path.is_file():
            path.unlink()
    for relative in sorted(files):
        destination = repository / relative
        if not destination.resolve().is_relative_to(repository.resolve()):
            raise ValueError('Linked installation path is not overwritten')
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(checkout / relative, destination)
    return sorted(files)


def validate_local_model(args):
    model = getattr(args, 'model', None)
    if model is None:
        return None
    if not args.with_ai:
        raise ValueError('Enable AI before choosing a local model')
    model = Path(model).expanduser().resolve()
    try:
        with model.open('rb') as stream:
            if stream.read(4) != b'GGUF':
                raise ValueError('Select a GGUF model file')
    except OSError as error:
        raise ValueError(f'Cannot read local model: {model}') from error
    return model


def save_global_config(root, repository, state, with_ai):
    """Keep user ENV settings; replace only paths/options selected by Setup."""
    config = root / 'environment.json'
    if config.is_symlink() or config.with_suffix('.tmp').is_symlink():
        raise ValueError('Linked global configuration files are not overwritten')
    defaults = repository / 'finalbuild/config/environment.json'
    data = json.loads(defaults.read_text(encoding='utf-8')) if defaults.is_file() else {'version': 1, 'environment': {}}
    if config.is_file():
        existing = json.loads(config.read_text(encoding='utf-8'))
        if existing.get('version') != 1 or not isinstance(existing.get('environment'), dict):
            raise ValueError('Invalid global environment.json; expected version 1 and environment object')
        data['environment'].update(existing['environment'])
    values = data['environment']
    if not config.is_file():
        values['AI_CAR_BACKEND_PORT'] = state.get('port', values.get('AI_CAR_BACKEND_PORT', 8001))
        values['LOCAL_LLM_SERVER_PORT'] = state.get('ai_port', values.get('LOCAL_LLM_SERVER_PORT', 8000))
    values['AI_CAR_DISABLE_LLM_AUTOSTART'] = not with_ai
    if with_ai:
        for key, field in [('LOCAL_LLM_MODEL_PATH', 'model'), ('LOCAL_LLM_SERVER_PATH', 'llama')]:
            if state.get(field): values[key] = state[field]
    temporary = config.with_suffix('.tmp')
    temporary.write_text(json.dumps(data, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
    temporary.replace(config)


def install(args):
    manifest = manifest_data(args.manifest)
    local_model = validate_local_model(args)
    root = claim_root(args.root)
    logs = root / 'logs'
    logs.mkdir(exist_ok=True)
    log = logs / ('setup-' + datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ') + '.log')
    repository = root / 'repo'
    if repository.is_symlink() or getattr(repository, 'is_junction', lambda: False)():
        raise ValueError('A linked repository is not modified by the installer')
    previous = json.loads((root / MARKER).read_text(encoding='utf-8'))
    # Preserve the previous file list until a replacement snapshot is promoted.
    with log.open('w', encoding='utf-8') as output:
        def progress(message):
            print(message, flush=True)
            print(message, file=output, flush=True)
        progress('[SETUP] Repository: ' + REPOSITORY + '@' + manifest['commit'])
        with tempfile.TemporaryDirectory(prefix='ai-car-source-', dir=root) as staging:
            stage = Path(staging)
            if manifest.get('source_mode') == 'bundled':
                archive = getattr(args, 'source_archive', None) or Path(args.manifest).parent / 'source.zip'
                archive = Path(archive)
                if not archive.is_file():
                    raise ValueError('Bundled source is missing. Rebuild Setup.exe with python installer.py')
                progress('[SOURCE] Verifying bundled Git snapshot; no GitHub login or download required')
                with archive.open('rb') as stream:
                    digest = hashlib.file_digest(stream, 'sha256').hexdigest()
                if digest != manifest['source_sha256']:
                    raise ValueError('Bundled source checksum mismatch. Rebuild or download Setup.exe again')
            else:
                archive = stage / 'repository.zip'
                url = f'https://codeload.github.com/{REPOSITORY}/zip/{manifest["commit"]}'
                progress('[DOWNLOAD] GitHub source snapshot; internet access required')
                request = urllib.request.Request(url, headers={'User-Agent': OWNER})
                try:
                    with urllib.request.urlopen(request, timeout=60) as response, archive.open('wb') as destination:
                        if not response.geturl().startswith('https://'):
                            raise ValueError('Insecure download redirect rejected')
                        count = 0
                        while chunk := response.read(1024 * 1024):
                            count += len(chunk)
                            if count > 1024**3:
                                raise ValueError('Unexpectedly large repository download')
                            destination.write(chunk)
                except urllib.error.HTTPError as error:
                    if error.code in (401, 403, 404):
                        raise RuntimeError(f'GitHub source is not publicly accessible (HTTP {error.code}). '
                                           'The repository may be private or the commit unavailable. '
                                           'Build the default bundled installer with python installer.py (without --online-only).') from error
                    raise
            checkout = extract_source(archive, stage, manifest['commit'])
            previous['ready'] = False
            (root / MARKER).write_text(json.dumps(previous, indent=2), encoding='utf-8')
            previous['files'] = promote_source(checkout, repository, previous.get('files', []))
            previous.update(owner=OWNER, commit=manifest['commit'], ready=False)
            (root / MARKER).write_text(json.dumps(previous, indent=2), encoding='utf-8')
        command = [sys.executable, str(repository / 'runner.py'), 'setup', '--skip-android']
        if not args.with_ai:
            command.append('--skip-ai')
        elif local_model:
            command += ['--model', str(local_model)]
        progress('[SETUP] Desktop/backend dependencies' + (' + local AI (several GB)' if args.with_ai else '; local AI disabled'))
        env = os.environ.copy()
        env.update(PYTHONUTF8='1', PYTHONIOENCODING='utf-8', PYTHONUNBUFFERED='1')
        if (root / 'environment.json').is_file():
            env['AI_CAR_ENV_CONFIG'] = str(root / 'environment.json')
        with subprocess.Popen(command, cwd=repository, env=env, stdout=subprocess.PIPE,
                              stderr=subprocess.STDOUT, text=True, encoding='utf-8', errors='replace') as child:
            for line in child.stdout:
                progress(line.rstrip('\n'))
            code = child.wait()
        if code:
            raise RuntimeError(f'Application setup failed ({code}); see {log}')
        for relative in ('.venv/Scripts/pythonw.exe', '.runner-state.json'):
            if not (repository / relative).is_file():
                raise RuntimeError('Setup returned without required file: ' + relative)
        state = json.loads((repository / '.runner-state.json').read_text(encoding='utf-8'))
        save_global_config(root, repository, state, args.with_ai)
        previous.update(ready=True, ai_enabled=args.with_ai, ai_source='local' if local_model else 'download')
        (root / MARKER).write_text(json.dumps(previous, indent=2), encoding='utf-8')
        progress('[READY] Desktop and backend installed. AI: ' + str(args.with_ai))
    return 0


def launch(args):
    root = args.root.resolve()
    installed = json.loads((root / MARKER).read_text(encoding='utf-8'))
    if installed.get('owner') != OWNER or not installed.get('ready'):
        raise RuntimeError('Installation is incomplete; run Setup again')
    repository = root / 'repo'
    env = os.environ.copy()
    env.update(PYTHONUTF8='1', PYTHONIOENCODING='utf-8', PYTHONUNBUFFERED='1')
    if (root / 'environment.json').is_file():
        env['AI_CAR_ENV_CONFIG'] = str(root / 'environment.json')
    # Each fixed client connects to the independently managed shared backend. Hide its console,
    # retain stdout/stderr on disk, and report failed startup through a dialog.
    with (root / 'logs/desktop.log').open('a', encoding='utf-8') as output:
        result = subprocess.run([str(repository / '.venv/Scripts/python.exe'), str(repository / 'runner.py'), 'desktop', '--app', getattr(args,'app','user')],
                                cwd=repository, env=env, stdout=output, stderr=subprocess.STDOUT,
                                creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
    if result.returncode:
        raise RuntimeError(f'Desktop exited with code {result.returncode}. See {root / "logs/desktop.log"}')
    return 0


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest='command', required=True)
    setup = commands.add_parser('install')
    setup.add_argument('--root', type=Path, required=True)
    setup.add_argument('--manifest', type=Path, required=True)
    setup.add_argument('--source-archive', type=Path)
    setup.add_argument('--error-file', type=Path)
    setup.add_argument('--with-ai', action='store_true')
    setup.add_argument('--model', type=Path, help='Use an existing GGUF without copying or downloading its weights')
    run = commands.add_parser('launch')
    run.add_argument('--root', type=Path, required=True)
    run.add_argument('--app',choices=('user','customer','market'),default='user')
    args = parser.parse_args(argv)
    try:
        return install(args) if args.command == 'install' else launch(args)
    except Exception as error:
        if args.command == 'launch' and os.name == 'nt':
            import ctypes
            ctypes.windll.user32.MessageBoxW(None, str(error), 'AI Car Scanner', 0x10)
        else:
            if getattr(args, 'error_file', None):
                try:
                    args.error_file.write_text(str(error), encoding='utf-8')
                except OSError:
                    pass
            marker = args.root / MARKER
            if marker.is_file():
                try:
                    if json.loads(marker.read_text(encoding='utf-8')).get('owner') == OWNER:
                        logs = args.root / 'logs'
                        logs.mkdir(exist_ok=True)
                        with (logs / 'bootstrap-errors.log').open('a', encoding='utf-8') as output:
                            print(str(error), file=output)
                except (OSError, ValueError):
                    pass
            if sys.stderr is not None:
                print('[SETUP ERROR] ' + str(error), file=sys.stderr)
        return 1


if __name__ == '__main__':
    raise SystemExit(main())

"""Build native applications with explicit prerequisites, logs and artifacts.

Examples from the repository root:
  python build.py --check
  python build.py --targets desktop android
  python build.py --skip-unavailable

Windows EXE packaging requires Windows; iOS requires macOS/Xcode.
Run the same local entrypoint on each required operating system.
"""
from __future__ import annotations

import argparse
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import platform
import re
import shutil
import signal
import threading
import subprocess
import sys
import venv

REPO = Path(__file__).resolve().parents[2]
PROJECT = REPO / "finalbuild"
TARGETS = ("desktop", "android", "ios")


class BuildError(RuntimeError):
    pass


def executable(name: str) -> str | None:
    return shutil.which(name)


def android_sdk() -> Path | None:
    candidates = [os.environ.get("ANDROID_HOME"), os.environ.get("ANDROID_SDK_ROOT")]
    local = PROJECT / "apps/mobile-android/local.properties"
    if local.is_file():
        for line in local.read_text(encoding="utf-8").splitlines():
            if line.startswith("sdk.dir="):
                candidates.append(line.partition("=")[2].replace("\\:", ":").replace("\\\\", "\\"))
    candidates += [str(Path.home() / "Android/Sdk"), str(Path.home() / "Library/Android/sdk"), str(REPO / ".build-tools/setup/android-sdk")]
    if os.environ.get("LOCALAPPDATA"):
        candidates.append(str(Path(os.environ["LOCALAPPDATA"]) / "Android/Sdk"))
    return next((Path(p).expanduser().resolve() for p in candidates if p and Path(p).expanduser().is_dir()), None)


def java_executable() -> str | None:
    if os.environ.get("JAVA_HOME"):
        candidate = Path(os.environ["JAVA_HOME"]) / "bin" / ("java.exe" if platform.system() == "Windows" else "java")
        if candidate.is_file():
            return str(candidate)
    managed = REPO / ".build-tools/setup/jdk/bin" / ("java.exe" if platform.system() == "Windows" else "java")
    if managed.is_file(): return str(managed)
    return executable("java")


def preflight(target: str) -> list[str]:
    problems = []
    if target == "desktop":
        if platform.system() != "Windows":
            problems.append("Desktop .exe packaging requires Windows; run this builder on Windows.")
        if sys.version_info < (3, 12):
            problems.append("Desktop requires Python 3.12+ (Windows Python 3.14 x64 recommended).")
        if sys.maxsize <= 2**32:
            problems.append("Desktop requires a 64-bit Python installation.")
    elif target == "android":
        java = java_executable()
        if not java:
            problems.append("Install JDK 17 and set JAVA_HOME (or put java on PATH).")
        else:
            try:
                version = subprocess.run([java, "-version"], capture_output=True, text=True, timeout=15)
                match = re.search(r'version\s+"(\d+)', version.stdout + version.stderr)
                if version.returncode or match is None or not 17 <= int(match[1]) <= 23:
                    problems.append("This Gradle version supports JDK 17–23; set JAVA_HOME to JDK 17 or 21.")
            except (OSError, subprocess.TimeoutExpired) as error:
                problems.append(f"Cannot run Java: {error}")
        sdk = android_sdk()
        if sdk is None:
            problems.append("Install Android Studio SDK; set ANDROID_HOME or ANDROID_SDK_ROOT.")
        else:
            if not (sdk / "platforms/android-36/android.jar").is_file():
                problems.append("Install SDK platform android-36 using Android Studio SDK Manager.")
            if not (sdk / "build-tools").is_dir() or not any((sdk / "build-tools").iterdir()):
                problems.append("Install Android SDK build-tools (35.0.0 or newer).")
        if platform.system() != "Windows" and executable("bash") is None:
            problems.append("Install bash to run the bundled Gradle wrapper.")
    elif target == "ios":
        if platform.system() != "Darwin":
            return ["iOS requires macOS with Xcode; run this builder on a Mac."]
        for tool in ("xcodebuild", "xcrun", "xcodegen"):
            if executable(tool) is None:
                problems.append(f"Install {tool}; XcodeGen can be installed with: brew install xcodegen")
        if not problems:
            try:
                result = subprocess.run(["xcrun", "--sdk", "iphonesimulator", "--show-sdk-path"], capture_output=True, text=True, timeout=30)
                if result.returncode:
                    problems.append("Select full Xcode with xcode-select, accept its license and install the iOS Simulator SDK.")
            except (OSError, subprocess.TimeoutExpired) as error:
                problems.append(f"Cannot query the iOS Simulator SDK: {error}")
    else:
        raise ValueError(f"Unknown build target: {target}")
    return problems


class Runner:
    def __init__(self, log: Path):
        self.log = log
        log.parent.mkdir(parents=True, exist_ok=True)

    def run(self, command: list[str], *, cwd: Path = PROJECT, env: dict | None = None, timeout: int = 1800, input_text: str | None = None) -> None:
        command = [str(item) for item in command]
        env = dict(os.environ if env is None else env)
        env["PYTHONUNBUFFERED"] = "1"
        print(f"[BUILD] {command[0]} {' '.join(command[1:3])} ...", flush=True)
        with self.log.open("a", encoding="utf-8") as log:
            log.write("\nCOMMAND: " + subprocess.list2cmdline(command) + "\n")
            log.flush()
            # Keep the complete log and show live output while long tools run.
            offset = log.tell()
            done = threading.Event()
            def stream():
                with self.log.open(encoding="utf-8", errors="replace") as source:
                    source.seek(offset)
                    while True:
                        chunk = source.read()
                        if chunk:
                            print(chunk, end="", flush=True)
                        if done.wait(0.2):
                            print(source.read(), end="", flush=True)
                            return
            watcher = threading.Thread(target=stream, daemon=True)
            watcher.start()
            options = {"creationflags": subprocess.CREATE_NEW_PROCESS_GROUP} if os.name == "nt" else {"start_new_session": True}
            process = None
            try:
                process = subprocess.Popen(command, cwd=cwd, env=env, stdout=log, stderr=subprocess.STDOUT,
                                           stdin=subprocess.PIPE if input_text is not None else None,
                                           text=input_text is not None, **options)
                if input_text is None:
                    process.wait(timeout=timeout)
                else:
                    process.communicate(input=input_text, timeout=timeout)
            except (subprocess.TimeoutExpired, KeyboardInterrupt) as error:
                if process is not None:
                    if os.name == "nt":
                        subprocess.run(["taskkill", "/PID", str(process.pid), "/T", "/F"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=15)
                    else:
                        try:
                            os.killpg(process.pid, signal.SIGKILL)
                        except ProcessLookupError:
                            pass
                    process.wait(timeout=15)
                if isinstance(error, KeyboardInterrupt):
                    raise
                raise BuildError(f"Command timed out after {timeout}s; see {self.log}") from error
            finally:
                done.set()
                watcher.join(timeout=5)
        if process.returncode:
            raise BuildError(f"Command failed (exit {process.returncode}); see {self.log}")


def require_file(path: Path) -> Path:
    if not path.is_file() or path.stat().st_size == 0:
        raise BuildError(f"Build command returned but required artifact is missing/empty: {path}")
    return path


def desktop_python(args, runner: Runner, tools: Path) -> Path:
    if args.no_install:
        runner.run([sys.executable, "-c", "import PyInstaller, PySide6, PIL"])
        return Path(sys.executable)
    environment = tools / "desktop-venv"
    python = environment / "Scripts/python.exe"
    if not python.exists():
        venv.EnvBuilder(with_pip=True).create(environment)
    requirements = ["-r", "requirements.txt"]
    if args.with_tests:
        requirements += ["-r", "backend/requirements-dev.txt", "-r", "apps/desktop/requirements-dev.txt"]
    runner.run([str(python), "-m", "pip", "install", *requirements])
    return python


def build_desktop(args, runner: Runner, work: Path, output: Path, tools: Path) -> list[Path]:
    python = desktop_python(args, runner, tools)
    env = os.environ.copy()
    env.update({"AI_CAR_DISABLE_LLM_AUTOSTART": "1", "QT_QPA_PLATFORM": "offscreen"})
    if args.with_tests:
        runner.run([str(python), "scripts/run_desktop_tests.py", "--min-core-coverage", "90",
                    "--reports-dir", str(output / "test-reports")], env=env)
    icons = work / "icons"
    source = PROJECT / "assets/AI-Car-Scanner-master.png"
    # Honor edited local artwork; never regenerate tracked assets in-place.
    if executable("git") and (REPO / ".git").exists():
        edited = subprocess.run(["git", "diff", "--quiet", "HEAD", "--", "assets/AI-Car-Scanner-mobile.png"], cwd=PROJECT)
        if edited.returncode == 1:
            source = PROJECT / "assets/AI-Car-Scanner-mobile.png"
    runner.run([str(python), "apps/desktop/stage_windows_icons.py", "--source", str(source), "--output-dir", str(icons)], env=env)
    env["AI_CAR_ICON_STAGE_DIR"] = str(icons)
    dist = work / "dist"
    runner.run([str(python), "-m", "PyInstaller", "--noconfirm", "--clean", "--distpath", str(dist / "backend"), "--workpath", str(work / "backend"), "apps/desktop/specs/backend_service.spec"], env=env)
    require_file(dist / "backend/backend_service.exe")
    artifacts=[Path(shutil.make_archive(str(output / "AI-Car-Backend-Windows"), "zip", dist / "backend"))]
    for role in getattr(args,'apps',('user','customer','market')):
        role_env={**env,'AI_CAR_PRODUCT':role.upper()}
        target=dist / role
        runner.run([str(python), "-m", "PyInstaller", "--noconfirm", "--clean", "--distpath", str(target), "--workpath", str(work / role), "apps/desktop/specs/product.spec"], env=role_env)
        require_file(target / ('AI-Car-'+role.title()+'.exe'))
        (target/'README.txt').write_text('AI Car '+role.title()+' — independent client.\nStart the shared backend separately: backend_service.exe --migrate\nConfigure --backend-url http://127.0.0.1:8001.\nNo backend/AI process is embedded in this app.\n',encoding='utf-8')
        artifacts.append(Path(shutil.make_archive(str(output / ('AI-Car-'+role.title()+'-Windows')), "zip", target)))
    return [require_file(path) for path in artifacts]


def build_android(args, runner: Runner, work: Path, output: Path, tools: Path) -> list[Path]:
    project = PROJECT / "apps/mobile-android"
    env = os.environ.copy()
    java=java_executable()
    if java is None:raise BuildError('JDK 17–23 is required')
    wrapper=require_file(project/'gradle/wrapper/gradle-wrapper.jar')
    command = [str(java),'-cp',str(wrapper),'org.gradle.wrapper.GradleWrapperMain']
    tasks=[];roles=getattr(args,'apps',('user','customer','market'))
    for role in roles:
        variant=role.title()+'Debug';tasks+=[':app:assemble'+variant]
        if args.with_tests:tasks+=[':app:test'+variant+'UnitTest',':app:lint'+variant]
    if args.android_api_url:tasks.append('-PapiBaseUrl='+args.android_api_url)
    runner.run(command + tasks + ["--no-daemon", "--console=plain"], cwd=project, env=env)
    artifacts=[]
    for role in roles:
        source=project / f'app/build/outputs/apk/{role}/debug/app-{role}-debug.apk'
        target=output / ('AI-Car-'+role.title()+'-Android-debug.apk')
        shutil.copy2(require_file(source),target);artifacts.append(require_file(target))
    return artifacts


def simulator_destination() -> str:
    result = subprocess.run(["xcrun", "simctl", "list", "devices", "available", "--json"], capture_output=True, text=True, check=True, timeout=30)
    candidates = []
    for runtime, devices in json.loads(result.stdout).get("devices", {}).items():
        if ".iOS-" not in runtime:
            continue
        version = tuple(int(value) for value in re.findall(r"\d+", runtime))
        for device in devices:
            if device.get("isAvailable") and "iPhone" in device.get("name", "") and device.get("udid"):
                candidates.append((version, device["udid"]))
    if not candidates:
        raise BuildError("iOS tests require an installed iPhone simulator runtime; install one in Xcode Settings > Platforms.")
    return "platform=iOS Simulator,id=" + max(candidates)[1]


def build_ios(args, runner: Runner, work: Path, output: Path, tools: Path) -> list[Path]:
    project = PROJECT / "apps/mobile-ios"
    runner.run(["xcodegen", "generate", "--spec", "project.yml"], cwd=project)
    def command(role):
        return ["xcodebuild", "-project", "AICarScanner.xcodeproj", "-scheme", "AICarScanner"+role.title(), "-configuration", "Debug", "-derivedDataPath", str(work / "DerivedData"), "CODE_SIGNING_ALLOWED=NO"]
    artifacts=[]
    for role in getattr(args,'apps',('user','customer','market')):
        runner.run(command(role) + ["-sdk", "iphonesimulator", "-destination", "generic/platform=iOS Simulator", "build"], cwd=project)
        application=work / ('DerivedData/Build/Products/Debug-iphonesimulator/AICarScanner'+role.title()+'.app')
        require_file(application/'Info.plist')
        artifacts.append(require_file(Path(shutil.make_archive(str(output / ('AI-Car-'+role.title()+'-iOS-Simulator')), "zip", application.parent, application.name))))
    if args.with_tests:
        runner.run(command('user')+["-destination",simulator_destination(),"-enableCodeCoverage","YES","-resultBundlePath",str(output/'TestResults.xcresult'),"test"],cwd=project)
    return artifacts


BUILDERS = {"desktop": build_desktop, "android": build_android, "ios": build_ios}


def artifact_record(path: Path, run: Path) -> dict:
    digest = hashlib.sha256()
    with path.open("rb") as file:
        for chunk in iter(lambda: file.read(1024 * 1024), b""):
            digest.update(chunk)
    return {"path": str(path.relative_to(run)), "size_bytes": path.stat().st_size, "sha256": digest.hexdigest()}


def execute(args) -> int:
    plans = {target: preflight(target) for target in args.targets}
    for target, problems in plans.items():
        print(f"[{target.upper()}] " + ("READY" if not problems else "UNAVAILABLE: " + "; ".join(problems)), flush=True)
    if args.check:
        return 2 if any(plans.values()) else 0
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
    run = args.output.resolve() / stamp
    run.mkdir(parents=True)
    tools = REPO / ".build-tools"
    summary = {"status": "RUNNING", "host": platform.system(), "requested_targets": args.targets, "with_tests": args.with_tests, "targets": {}}
    report = run / "build-summary.json"

    def save():
        report.write_text(json.dumps(summary, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")

    save()
    for target, problems in plans.items():
        if problems:
            summary["targets"][target] = {"status": "UNAVAILABLE", "reasons": problems, "artifacts": []}
            save()
            continue
        output = run / target
        output.mkdir()
        runner = Runner(output / "build.log")
        work = tools / "work" / stamp / target
        work.mkdir(parents=True)
        try:
            artifacts = BUILDERS[target](args, runner, work, output, tools)
            if not artifacts:
                raise BuildError("No artifacts produced")
            records = [artifact_record(require_file(path), run) for path in artifacts]
            entry = {"status": "PASS", "artifacts": records}
        except KeyboardInterrupt:
            summary["targets"][target] = {"status": "CANCELLED", "artifacts": [], "log": str(runner.log.relative_to(run))}
            for pending in args.targets:
                summary["targets"].setdefault(pending, {"status": "NOT_RUN", "artifacts": []})
            summary["status"] = "CANCELLED"
            save()
            print(f"\n[SUMMARY] CANCELLED — {report}", flush=True)
            return 130
        except Exception as error:
            entry = {"status": "FAIL", "error": str(error), "artifacts": []}
        entry["log"] = str(runner.log.relative_to(run))
        summary["targets"][target] = entry
        print(f"[{target.upper()}] {entry['status']}" + (f": {entry['error']}" if entry.get("error") else ""), flush=True)
        save()
    statuses = [result["status"] for result in summary["targets"].values()]
    if "FAIL" in statuses:
        summary["status"] = "FAIL"
    elif "UNAVAILABLE" in statuses:
        summary["status"] = "PARTIAL" if "PASS" in statuses else "UNAVAILABLE"
    else:
        summary["status"] = "PASS"
    save()
    print(f"[SUMMARY] {summary['status']} — {report}", flush=True)
    if "FAIL" in statuses or "PASS" not in statuses:
        return 1
    if "UNAVAILABLE" in statuses and not args.skip_unavailable:
        return 2
    return 0


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--targets", nargs="+", choices=TARGETS, default=list(TARGETS))
    parser.add_argument("--apps",choices=("user","customer","market"),nargs="+",default=["user","customer","market"],help="Independent apps to build; default builds all three")
    parser.add_argument("--output", type=Path, default=REPO / "artifacts", help="Artifact base directory; each run has its own timestamped folder")
    parser.add_argument("--check", action="store_true", help="Check toolchains only; do not install, build or write outputs")
    parser.add_argument("--skip-unavailable", action="store_true", help="Allow a partial local build; unavailable targets remain explicitly reported")
    parser.add_argument("--with-tests", action="store_true", help="Run Desktop regression, Android JVM/lint, and iOS XCTest before reporting success")
    parser.add_argument("--no-install", action="store_true", help="Use current Python's existing Desktop dependencies instead of creating/updating an isolated environment")
    parser.add_argument("--android-api-url", help="Backend URL embedded in the Android app, e.g. http://10.0.2.2:8001/")
    args = parser.parse_args(argv)
    args.targets = list(dict.fromkeys(args.targets))
    if args.android_api_url:
        from urllib.parse import urlsplit
        try:
            url = urlsplit(args.android_api_url)
            if url.port == 0:
                raise ValueError("port zero")
        except ValueError:
            parser.error("--android-api-url has an invalid host or port")
        if url.scheme not in {"http", "https"} or not url.hostname or url.username or url.password or url.query or url.fragment:
            parser.error("--android-api-url requires an HTTP(S) backend URL without credentials/query/fragment")
    try:
        return execute(args)
    except KeyboardInterrupt:
        print("Build cancelled.", file=sys.stderr)
        return 130
    except (OSError, subprocess.SubprocessError) as error:
        print(f"Build setup failed: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

"""Remove only untracked Python/test/lint caches. Preview is the default.

Build outputs, test reports, SDKs, environments, models and user data are kept.
The entrypoint is repository-root clean.py and works from any working directory.
"""
from __future__ import annotations

import argparse
from dataclasses import dataclass
import os
from pathlib import Path
import shutil
import subprocess

ROOT = Path(__file__).resolve().parents[2]
CACHE_DIRS = frozenset({'__pycache__', '.pytest_cache', '.ruff_cache'})
SKIP_DIRS = frozenset({'.git', '.venv', 'venv', '.build-tools', 'artifacts', 'build',
                       'build-debug', 'build-release', 'dist', 'dist-debug', 'dist-release',
                       'desktop-test-reports', '.gradle', '.kotlin', 'node_modules',
                       'models', 'assets', 'VehicleModels', 'resources'})


@dataclass(frozen=True)
class Candidate:
    path: Path
    bytes: int


def tracked_paths(root: Path) -> frozenset[str]:
    result = subprocess.run(['git', '-C', str(root), 'ls-files', '-z'], capture_output=True, check=True)
    return frozenset(os.fsdecode(path) for path in result.stdout.split(b'\0') if path)


def is_link(path: Path) -> bool:
    return path.is_symlink() or getattr(path, 'is_junction', lambda: False)()


def tree_bytes(path: Path) -> int:
    if path.is_file():
        return path.stat().st_size
    total = 0
    for base, dirs, files in os.walk(path, followlinks=False):
        dirs[:] = [name for name in dirs if not is_link(Path(base) / name)]
        for name in files:
            file = Path(base) / name
            if not is_link(file):
                total += file.stat().st_size
    return total


def candidates(root: Path, tracked: frozenset[str]) -> list[Candidate]:
    root = root.resolve()
    result = []
    def protected(path):
        relative = path.relative_to(root).as_posix()
        return relative in tracked or any(name.startswith(relative + '/') for name in tracked)
    for base, dirs, files in os.walk(root, followlinks=False):
        retained = []
        for name in dirs:
            path = Path(base) / name
            if is_link(path) or name in SKIP_DIRS:
                continue
            if name in CACHE_DIRS:
                if not protected(path): result.append(Candidate(path, tree_bytes(path)))
                # Do not traverse even a tracked cache directory.
            else:
                retained.append(name)
        dirs[:] = retained
        for name in files:
            path = Path(base) / name
            if (name == '.coverage' or name.startswith('.coverage.')) and not is_link(path) and not protected(path):
                result.append(Candidate(path, tree_bytes(path)))
    return sorted(result, key=lambda candidate: str(candidate.path))


def remove(root: Path, candidate: Candidate) -> None:
    root = root.resolve()
    path = candidate.path
    if is_link(path) or not path.resolve().is_relative_to(root) or path.resolve() == root:
        raise ValueError(f'Unsafe cleanup path: {path}')
    if path.is_dir(): shutil.rmtree(path)
    elif path.exists(): path.unlink()


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--apply', action='store_true', help='Remove the listed untracked caches; otherwise preview only')
    args = parser.parse_args(argv)
    try:
        plan = candidates(ROOT, tracked_paths(ROOT))
        for candidate in plan:
            print(f'{candidate.path.relative_to(ROOT)} ({candidate.bytes:,} bytes)')
        if args.apply:
            for candidate in plan: remove(ROOT, candidate)
        print(f'{"Removed" if args.apply else "Preview"}: {len(plan)} cache entries, {sum(c.bytes for c in plan):,} bytes')
        if not args.apply: print('Run python clean.py --apply to remove these caches.')
        return 0
    except (OSError, ValueError, subprocess.SubprocessError) as error:
        print(f'Cleanup stopped: {error}')
        return 1


if __name__ == '__main__':
    raise SystemExit(main())

"""Paired baseline/current comparison, frozen reference loaded from a Git revision."""
from __future__ import annotations
import argparse
import hashlib
import json
from pathlib import Path
import statistics
import subprocess
import time
import types
from benchmark_pipeline import ROOT, fixture, measure


def reference(revision):
    # Execute trusted source from the explicitly selected local Git revision.
    analysis_source=subprocess.check_output(['git','show',f'{revision}:finalbuild/backend/telemetry/analysis.py'],cwd=ROOT,text=True)
    service_source=subprocess.check_output(['git','show',f'{revision}:finalbuild/backend/telemetry/service.py'],cwd=ROOT,text=True)
    analysis=types.ModuleType('telemetry._baseline_analysis');analysis.__package__='telemetry'
    exec(compile(analysis_source,'baseline_analysis.py','exec'),analysis.__dict__)
    namespace={'__package__':'telemetry','compute_stats':analysis.compute_stats,'detect_events':analysis.detect_events}
    service_source=service_source.replace('from .analysis import compute_stats, detect_events','')
    exec(compile(service_source,'baseline_service.py','exec'),namespace)
    return namespace['TelemetryService'],hashlib.sha256((analysis_source+service_source).encode()).hexdigest()


def main():
    p=argparse.ArgumentParser();p.add_argument('--baseline-ref',default='540e00f');p.add_argument('--output',type=Path,required=True);args=p.parse_args()
    cls,digest=reference(args.baseline_ref);results={}
    for count in (1000,10000,50000):
        current,sid=fixture(count);old=cls();old.append(current._samples[sid])
        jobs={'baseline':lambda:old.summarize(sid),'optimized':lambda:current.summarize(sid)}
        # IDs and generation times are intentionally fresh on every summary.
        def canonical(summary):
            data=summary.model_dump(mode='json');data.pop('generated_at');
            for event in data['events']:event.pop('id')
            return data
        assert canonical(jobs['baseline']())==canonical(jobs['optimized']()),'summary mismatch'
        for fn in jobs.values():
            for _ in range(5):fn()
        raw={name:[] for name in jobs}
        for iteration in range(40):
            for name in (list(jobs) if iteration%2==0 else list(reversed(jobs))):
                start=time.perf_counter_ns();jobs[name]();raw[name].append((time.perf_counter_ns()-start)/1e6)
        result={name:{'p50_ms':statistics.median(v),'p95_ms':sorted(v)[37],'p99_ms':max(v),'raw_ms':v} for name,v in raw.items()}
        result['p50_improvement_percent']=100*(1-result['optimized']['p50_ms']/result['baseline']['p50_ms'])
        result['equivalence']='PASS'
        result['resources']={name:measure(fn,10) for name,fn in jobs.items()}
        results[str(count)]=result
    args.output.parent.mkdir(parents=True,exist_ok=True)
    args.output.write_text(json.dumps({'baseline_ref':args.baseline_ref,'reference_sha256':digest,'iterations':40,'ordering':'alternating AB/BA','results':results},indent=2)+'\n',encoding='utf-8')
    print({key:round(value['p50_improvement_percent'],2) for key,value in results.items()})

if __name__=='__main__':main()

#!/usr/bin/env python3
"""Aggregate FRESH local Desktop v1.0 automated evidence, never approve manual GO."""
from __future__ import annotations
import argparse
from datetime import datetime, timezone
import hashlib
import json
from pathlib import Path
import subprocess

ROOT = Path(__file__).resolve().parents[1]
REPORT = ROOT / 'desktop-test-reports'
EXE = ROOT / 'dist-release/icon-preview/AICarScanner.exe'


def read_fresh(path: Path, since: int) -> dict:
    if not path.is_file():
        raise RuntimeError(f'Missing report: {path}')
    if path.stat().st_mtime < since - 3:  # protect against stale reports / coarse NTFS timestamps
        raise RuntimeError(f'Report is stale: {path}')
    return json.loads(path.read_text(encoding='utf-8'))


def main() -> int:
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--mode', choices=('full', 'reuse', 'source'), required=True)
    p.add_argument('--since', type=int, required=True)
    a = p.parse_args()
    issues = []
    inputs = {}
    for key, path in (
        ('desktop_suite', REPORT/'summary.json'),
        ('performance', REPORT/'performance.json'),
        ('visible_ui', REPORT/'real-ui-acceptance/results.json'),
    ):
        try:
            inputs[key] = read_fresh(path, a.since)
        except (OSError, ValueError, RuntimeError) as exc:
            issues.append(str(exc))
    suite = inputs.get('desktop_suite', {})
    perf = inputs.get('performance', {})
    visible = inputs.get('visible_ui', {})
    core = suite.get('production_core_coverage_percent')
    source = suite.get('combined_coverage_percent')
    if suite.get('status') != 'PASS' or source is None or source < 90 or core is None or core < 90:
        issues.append('Source test suite and both >=90% coverage gates must PASS')
    if perf.get('status') != 'PASS' or perf.get('violations'):
        issues.append('Local Qt navigation/event-loop performance gates must PASS')
    budgets = perf.get('performance_budget_ms') or {}
    if budgets.get('navigation_p95') != 25 or budgets.get('qt_timer_p95') != 2:
        issues.append('Performance gates must use navigation p95 <=25ms and event-loop p95 <=2ms')
    if visible.get('status') != 'PASS' or visible.get('failed') != 0 or not visible.get('tests_total'):
        issues.append('Visible UI automated acceptance must PASS')
    packaged = a.mode != 'source'
    # A mock backend PASS cannot prove real FastAPI starts. Require freshly
    # produced real-service probes for both source and packaged modes.
    for mode in (('source', 'frozen') if packaged else ('source',)):
        try:
            backend = read_fresh(REPORT / 'fastapi-startup' / f'{mode}.json', a.since)
            if backend.get('status') != 'PASS' or not backend.get('health'):
                issues.append(f'Real FastAPI {mode} startup failed')
        except (OSError, ValueError, RuntimeError) as exc:
            issues.append(str(exc))
    # Real subprocess crash/recovery is separate from the mocked Qt UI run.
    try:
        recovery = read_fresh(
            REPORT / 'fastapi-recovery' / 'source-integration.json', a.since
        )
        if (
            recovery.get('status') != 'PASS'
            or recovery.get('health_before_crash') is not True
            or recovery.get('health_after_recovery') is not True
            or recovery.get('cleanup') != 'PASS'
            or recovery.get('original_pid') == recovery.get('replacement_pid')
        ):
            issues.append('Real FastAPI crash/restart integration gate did not PASS')
    except (OSError, ValueError, RuntimeError) as exc:
        issues.append(str(exc))
    hash_value = None
    if packaged:
        frozen = perf.get('packaged_exe') or {}
        if frozen.get('status') != 'PASS' or frozen.get('repetitions') != 3 or frozen.get('passed') != 3:
            issues.append('Frozen EXE 3/3 stability gate must PASS')
        if not any(c.get('mode') == 'frozen-exe' and c.get('status') == 'PASS' for c in visible.get('cases', [])):
            issues.append('Visible packaged EXE startup/screenshot/shutdown evidence missing')
        for suffix in ('baseline', 'fusion-cleanup'):
            try:
                result = read_fresh(REPORT / f'packaged-{suffix}-result.json', a.since)
                if result.get('status') != 'PASS' or result.get('returncode') != 0:
                    issues.append(f'Frozen {suffix} lifecycle smoke failed')
            except (OSError, ValueError, RuntimeError) as exc:
                issues.append(str(exc))
        if EXE.is_file():
            with EXE.open('rb') as source_exe:
                hash_value = hashlib.file_digest(source_exe, 'sha256').hexdigest()
        else:
            issues.append(f'Missing executable: {EXE}')
        # The runner verifies icon report during a fresh build; reused bundles
        # must never be described as built from the current main source.
        if a.mode == 'full':
            try:
                icons = read_fresh(ROOT / 'dist-release/icon-preview/desktop-icon-report.json', a.since)
                if icons.get('status') != 'PASS':
                    issues.append('Fresh build icon verification failed')
            except (OSError, ValueError, RuntimeError) as exc:
                issues.append(str(exc))
    sha = subprocess.run(['git', 'rev-parse', 'HEAD'], cwd=ROOT, text=True,
                         capture_output=True, check=False)
    result = {
        'title': 'AI-CAR-SCANER Desktop v1.0 Local Release Candidate',
        'generated_utc': datetime.now(timezone.utc).isoformat(),
        'git_commit': sha.stdout.strip() if sha.returncode == 0 else 'unknown',
        'mode': a.mode,
        'automated_status': 'FAIL' if issues else ('PASS' if packaged else 'SOURCE_ONLY_PASS'),
        'manual_acceptance': 'PENDING',
        'release_decision': 'NOT_YET_GO',
        'tests_passed': sum(int(r.get('cases', {}).get('passed', 0)) for r in suite.get('group_results', [])),
        'all_source_coverage_percent': source,
        'production_core_coverage_percent': core,
        'qt_navigation_p95_ms': (perf.get('source_qt') or {}).get('navigation_latency', {}).get('p95_ms'),
        'qt_event_loop_p95_ms': (perf.get('source_qt') or {}).get('qt_timer_turnaround', {}).get('p95_ms'),
        'packaged_exe_sha256': hash_value,
        'visible_ui_cases': visible.get('tests_total'),
        'issues': issues,
        'evidence_paths': ['desktop-test-reports/summary.json',
                           'desktop-test-reports/performance.json',
                           'desktop-test-reports/real-ui-acceptance/results.json',
                           'desktop-test-reports/real-ui-acceptance/report.html',
                           'desktop-test-reports/fastapi-recovery/source-integration.json',
                           'desktop-test-reports/fastapi-startup/source.json',
                           *(['desktop-test-reports/fastapi-startup/frozen.json'] if packaged else [])],
        'limitations': 'Real FastAPI startup is checked; GUI mock tests do not validate live LLM/OBD or cloud-host recovery. Manual acceptance is mandatory.',
    }
    REPORT.mkdir(parents=True, exist_ok=True)
    path = REPORT / 'release-v1-readiness.json'
    path.write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
    print(f"[DESKTOP-V1] {result['automated_status']} | source={source}% core={core}% | tests={result['tests_passed']}")
    print(f'[DESKTOP-V1] Evidence: {path}')
    for msg in issues:
        print(f'[DESKTOP-V1] FAIL: {msg}')
    print('[DESKTOP-V1] Manual acceptance: PENDING, no release tag created')
    return 1 if issues else 0


if __name__ == '__main__':
    raise SystemExit(main())

"""Compare Qt/PySide6 native bundles after a Windows frozen startup crash.

Run from finalbuild/: python scripts/diagnose_frozen_qt.py
This script is read-only except for writing its JSON report in dist-debug/.
It deliberately does not import Qt or load any native DLL.
"""
from __future__ import annotations

from collections import defaultdict
from hashlib import sha256
from importlib.metadata import PackageNotFoundError, version
from pathlib import Path
import json
import os
import sys

ROOT = Path(__file__).resolve().parents[1]
DIST = ROOT / "dist-debug"
NAMES = ("AIQtProbe", "AICarScannerDebug")
KEYS = (
    "qt6", "pyside6", "shiboken6", "libcrypto", "libssl",
    "vcruntime", "msvcp", "icu", "zlib",
)


def is_native_candidate(p: Path) -> bool:
    name = p.name.lower()
    return p.suffix.lower() in {".pyd", ".dll"} and any(
        key in name for key in KEYS
    )


def scan(name: str) -> dict:
    internal = DIST / name / "_internal"
    result = {"folder": str(internal), "present": internal.is_dir(), "dlls": {}}
    if not internal.is_dir():
        return result
    for file in sorted(internal.rglob("*")):
        if not file.is_file() or not is_native_candidate(file):
            continue
        rel = file.relative_to(internal).as_posix()
        result["dlls"][rel] = {
            "name": file.name,
            "bytes": file.stat().st_size,
            "sha256": sha256(file.read_bytes()).hexdigest(),
        }
    return result


def main() -> int:
    print("Python executable:", sys.executable)
    packages = [
        "PySide6", "PySide6_Essentials", "PySide6_Addons",
        "shiboken6", "pyinstaller", "pyinstaller-hooks-contrib",
    ]
    versions = {}
    for package in packages:
        try:
            versions[package] = version(package)
        except PackageNotFoundError:
            versions[package] = "NOT INSTALLED"
    print("Package versions:", versions)
    print("QT_API:", os.environ.get("QT_API", "(unset)"))
    print("PATH:", os.environ.get("PATH", "")[:500])
    bundles = {name: scan(name) for name in NAMES}
    for name, result in bundles.items():
        print(f"Bundle {name}: present={result['present']} native files={len(result['dlls'])}")
    qt, app = (bundles[name]["dlls"] for name in NAMES)
    qt_by_filename = defaultdict(list)
    app_by_filename = defaultdict(list)
    for rel, data in qt.items():
        qt_by_filename[data["name"].lower()].append((rel, data))
    for rel, data in app.items():
        app_by_filename[data["name"].lower()].append((rel, data))
    names = sorted(set(qt_by_filename) | set(app_by_filename))
    differences = []
    for basename in names:
        q = qt_by_filename.get(basename, [])
        a = app_by_filename.get(basename, [])
        q_hashes = {item[1]["sha256"] for item in q}
        a_hashes = {item[1]["sha256"] for item in a}
        if q_hashes != a_hashes or len(q) != len(a):
            differences.append({
                "filename": basename,
                "qt_probe": [{"path": p, "sha256": d["sha256"]} for p, d in q],
                "desktop": [{"path": p, "sha256": d["sha256"]} for p, d in a],
            })
    report = {
        "venv_python": sys.executable,
        "versions": versions,
        "bundles": bundles,
        "differing_native_files": differences,
    }
    DIST.mkdir(parents=True, exist_ok=True)
    report_path = DIST / "qt-bundle-audit.json"
    report_path.write_text(
        json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8"
    )
    print("\nDifferent/missing Qt-related DLL/PYD files:")
    for item in differences:
        print(" ", item["filename"])
        for name in NAMES:
            records = item["qt_probe" if name == NAMES[0] else "desktop"]
            for record in records:
                print(f"    {name}: {record['path']} sha256={record['sha256'][:16]}")
        if not item["qt_probe"] or not item["desktop"]:
            print("    [MISSING FROM ONE BUNDLE]")
    print("Report:", report_path)
    print("Differences are diagnostic clues, not proof of a specific DLL conflict.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

